window.__SEARCH_INDEX__ = [{"slug":"overview","url":"overview.html","title":"LangGraph 概述","group":"LangGraph","sections":[{"h":"安装#","id":"安装","t":"pip uv bash 复制 bash 复制 创建一个最小的图： python 复制 如需完整的计算器智能体，请参阅 LangGraph 快速入门 。"},{"h":"能力#","id":"能力","t":"LangGraph 提供了面向有状态、长时间运行工作流的运行时基础原语。它不对提示词做抽象，也不强制固定的智能体架构。 确定性步骤与智能体步骤 ：在一个图中将手写节点与模型驱动的节点组合起来。 持久化 ：对状态做检查点，并在失败或暂停后恢复。 人在回路 ：暂停执行，检查或编辑状态，然后继续。 记忆 ：短期线程状态与跨会话的长期记忆。 流式输出 ：在图运行过程中流式输出 token、状态更新和其他事件。"},{"h":"集成、部署与可观测性#","id":"集成部署与可观测性","t":"LangGraph 可以独立使用。不过，你也可以将它与其他 LangCHain 产品搭配使用： LangChain 基于 LangGraph 构建的集成与智能体抽象。 LangSmith Deployment 部署并扩展有状态智能体，并可在 Studio 中进行可视化原型设计。 LangSmith Observability 追踪请求、评估输出并监控部署。"},{"h":"另请参阅#","id":"另请参阅","t":"LangGraph 快速入门 Graph API 概述 在 Graph API 与 Functional API 之间做选择 框架、运行时与运行框架 通过 MCP 将 这些文档接入 你选择的智能体，以获取实时答案。 在 GitHub 上 编辑此页面 或 提交问题 。"}]},{"slug":"quickstart","url":"quickstart.html","title":"快速开始","group":"入门","sections":[{"h":"前提条件#","id":"前提条件","t":"在开始之前，请确保你拥有来自模型提供商的 API 密钥（例如 Gemini、Anthropic、OpenAI）。 有关所有可用的提供商，请参阅 聊天模型集成 。 如果你使用 LangSmith Gateway ，可以 自带提供商密钥 ，或使用 Gateway Credits 在没有提供商密钥的情况下访问模型。"},{"h":"设置#","id":"设置","t":"安装 langgraph 、 langchain 和 langchain-anthropic ： pip uv bash 复制 bash 复制 本示例使用 Anthropic。在 shell 或 .env 文件中设置你的 API 密钥： Shell .env bash 复制 bash 复制 要使用其他提供商，请参阅 聊天模型集成 ，并在后续步骤中调整模型初始化。"},{"h":"1. 选择 API#","id":"1.-选择-api","t":"两种方式构建的是同一个计算器智能体：模型可以调用工具，然后智能体再次调用模型，直到返回最终答案。 如果你希望将智能体定义为由节点和边构成的图，请 使用 Graph API 。 如果你希望将智能体定义为单个函数，请 使用 Functional API 。 选择一个标签页。创建一个文件。将以下每个步骤的代码依次添加到上一步代码的下方。 不确定该选哪个？请参阅 在 Graph API 与 Functional API 之间选择 。有关概念性信息，请参阅 Graph API 概览 和 Functional API 概览 。"},{"h":"第 1 步：阅读指南#","id":"第-1-步阅读指南","t":"判断该项目使用的是 Python 还是 TypeScript/JavaScript。获取并按照对应页面操作；将其视为包名、模型字符串和代码的唯一权威来源： Python: https://docs.langchain.com/oss/python/langgraph/quickstart.md TypeScript: https://docs.langchain.com/oss/javascript/langgraph/quickstart.md 只使用 使用 Graph API 标签页。不要实现 Function"},{"h":"第 2 步：安装依赖#","id":"第-2-步安装依赖","t":"使用该项目中已有的包管理器，安装 Graph API 路径所需的包。"},{"h":"第 3 步：配置模型凭据#","id":"第-3-步配置模型凭据","t":"本快速入门默认使用 Anthropic。检查是否已设置 ANTHROPIC_API_KEY 。如果未设置，请用户创建密钥并在 shell 或 .env 文件中设置，然后停下并等待确认。不要编造、硬编码或提交 API 密钥。如果用户根据集成文档更倾向于使用其他聊天模型提供商，请在确认后相应调整示例。"},{"h":"第 4 步：实现计算器智能体#","id":"第-4-步实现计算器智能体","t":"依据指南定义工具与模型，然后定义 Graph API 的状态、节点、边以及编译后的图。"},{"h":"第 5 步：可选的 LangSmith 追踪#","id":"第-5-步可选的-langsmith-追踪","t":"询问用户是否需要追踪。如果需要，请他们自行设置 LANGSMITH_TRACING=true 和 LANGSMITH_API_KEY 。不要编造 LangSmith 密钥。"},{"h":"第 6 步：运行智能体#","id":"第-6-步运行智能体","t":"使用指南中的示例算术查询调用智能体，并打印最终结果。"},{"h":"规则#","id":"规则","t":"保持在本快速入门的范围内。除非用户要求，否则不要添加部署、评估或无关的框架。 优先采用所获取指南中展示的 Graph API 结构，而不是另创一种智能体模式。 当密钥、提供商选择或项目约定不明确时，先询问而不是猜测。"},{"h":"2. 定义工具和模型#","id":"2.-定义工具和模型","t":"本示例使用 Claude Sonnet 模型，并定义加法、乘法和除法工具。 为智能体创建文件（ agent.py 或 agent.ts ）。添加以下内容： python 复制"},{"h":"3. 定义状态#","id":"3.-定义状态","t":"图的状态存储消息和 LLM 调用次数。 在工具和模型下方添加以下内容： 💡 提示 LangGraph 中的状态会在智能体的整个执行过程中持久保留。 配合 operator.add 的 Annotated 类型会把新消息追加到列表中，而不是替换列表。 python 复制"},{"h":"4. 定义模型节点#","id":"4.-定义模型节点","t":"模型节点调用 LLM，并决定是否调用工具。 在状态 schema 下方添加以下内容： python 复制"},{"h":"5. 定义工具节点#","id":"5.-定义工具节点","t":"工具节点调用工具并返回结果。 在模型节点下方添加以下内容： python 复制"},{"h":"6. 定义结束逻辑#","id":"6.-定义结束逻辑","t":"条件边函数根据 LLM 是否发起工具调用，路由到工具节点或结束。 在工具节点下方添加以下内容： python 复制"},{"h":"7. 构建并编译智能体#","id":"7.-构建并编译智能体","t":"在路由函数下方添加以下内容。使用 \u00000\u0000 构建图，并使用 \u00001\u0000 编译它： python 复制"},{"h":"8. 设置 LangSmith 追踪#","id":"8.-设置-langsmith-追踪","t":"LangSmith 会在智能体运行时展示工具调用和模型响应。 此步骤是可选的。在 smith.langchain.com 注册、创建 API 密钥，并在运行智能体之前于 shell 中设置以下环境变量： bash 复制"},{"h":"9. 运行智能体#","id":"9.-运行智能体","t":"在编译后的图下方添加以下内容： python 复制 运行该文件： bash 复制 你应当会看到人类消息、对 add 的工具调用、工具结果 7 ，以及最终的助手回复。具体文本因模型而异，但工具结果是 7 。 要检查你的文件，请与完整示例进行对比： 完整代码示例 python 复制 构建 LangGraph Functional API 计算器快速入门 按照 LangGraph 快速入门，在当前工作目录中使用 Functional API 构建一个 LangGraph 计算器智能体。"},{"h":"第 1 步：阅读指南#","id":"第-1-步阅读指南-2","t":"判断该项目使用的是 Python 还是 TypeScript/JavaScript。获取并遵循匹配的页面；将其作为包名、模型字符串和代码的权威依据： Python： https://docs.langchain.com/oss/python/langgraph/quickstart.md TypeScript： https://docs.langchain.com/oss/javascript/langgraph/quickstart.md 仅使用 Use the Functional API 标签页。不要实现 G"},{"h":"第 2 步：安装依赖#","id":"第-2-步安装依赖-2","t":"使用本项目已在使用的包管理器，安装 Functional API 路径所需的包。"},{"h":"第 3 步：配置模型凭证#","id":"第-3-步配置模型凭证","t":"本快速入门默认使用 Anthropic。检查是否已设置 ANTHROPIC_API_KEY 。如果未设置，请让用户创建密钥，并在 shell 或 .env 文件中设置，然后停止并等待确认。不要编造、硬编码或提交 API 密钥。如果用户更倾向于使用集成文档中的其他聊天模型提供商，请在确认后相应地调整示例。"},{"h":"第 4 步：实现计算器智能体#","id":"第-4-步实现计算器智能体-2","t":"定义工具和模型，然后定义指南中的 Functional API 任务和入口点。"},{"h":"第 5 步：可选的 LangSmith 追踪#","id":"第-5-步可选的-langsmith-追踪-2","t":"询问用户是否需要追踪。如果需要，请他们自行设置 LANGSMITH_TRACING=true 和 LANGSMITH_API_KEY 。不要编造 LangSmith 密钥。"},{"h":"第 6 步：运行智能体#","id":"第-6-步运行智能体-2","t":"针对指南中的一个示例算术查询调用智能体，并打印最终结果。"},{"h":"规则#","id":"规则-2","t":"将范围限制在本快速入门内。除非用户要求，否则不要添加部署、评测或无关的框架。 优先采用所获取指南中展示的 Functional API 结构，而不是自行设计不同的智能体模式。 当密钥、提供商选择或项目约定不明确时，应询问而不是猜测。"},{"h":"2. 定义工具和模型#","id":"2.-定义工具和模型-2","t":"本示例使用 Claude Sonnet 模型，并定义用于加法、乘法和除法的工具。 为智能体创建一个文件（ agent.py 或 agent.ts ）。添加以下内容： python 复制"},{"h":"3. 定义模型任务#","id":"3.-定义模型任务","t":"模型任务调用 LLM，并决定是否调用工具。 在工具和模型下方添加以下内容： 💡 提示 \u00000\u0000 装饰器将函数标记为智能体中的任务。可以在入口点中同步或异步调用任务。 python 复制"},{"h":"4. 定义工具任务#","id":"4.-定义工具任务","t":"工具任务调用工具并返回结果。 在模型任务下方添加以下内容： python 复制"},{"h":"5. 定义智能体#","id":"5.-定义智能体","t":"在任务下方添加以下内容。使用 \u00000\u0000 定义智能体： ℹ 注意 Functional API 在单个函数中使用普通控制流（循环和条件语句），而不是显式的节点和边。 python 复制"},{"h":"6. 设置 LangSmith 追踪#","id":"6.-设置-langsmith-追踪","t":"LangSmith 会在智能体运行时显示工具调用和模型响应。 此步骤是可选的。在 smith.langchain.com 注册、创建 API 密钥，并在运行智能体之前于 shell 中设置以下环境变量： bash 复制"},{"h":"7. 运行智能体#","id":"7.-运行智能体","t":"在入口点下方添加以下内容： python 复制 运行该文件： bash 复制 你应该会看到人类消息、对 add 的工具调用、工具结果 7 ，以及最终的助手回复。具体文本因模型而异，但工具结果应为 7 。 要检查你的文件，请将其与完整示例进行对比： 完整代码示例 python 复制"},{"h":"后续步骤#","id":"后续步骤","t":"你现在已经有了一个可用的计算器智能体。可以继续学习以下任一主题： 学习这些 API ：先阅读 在 Graph API 与 Functional API 之间做选择 ，然后阅读 Graph API 的构建清单 或 Functional API 的构建清单 。 添加持久化 ：使用 检查点保存器 ，使运行能够跨会话暂停与恢复。 添加人在回路 ：通过 中断 暂停，以进行审批或编辑。 流式输出结果 ：参阅 流式输出 ，了解 token 与状态更新。 深入探索 ： 在 Graph API 中思考 、 在 Functional "}]},{"slug":"choosing-apis","url":"choosing-apis.html","title":"在 Graph API 与 Functional API 之间选择","group":"入门","sections":[{"h":"Graph API（默认）#","id":"graph-api默认","t":"当你直接基于 LangGraph 构建时，请选择 Graph API： 跨节点显式共享的 状态 条件分支，以及稍后汇聚的并行路径 用于调试和文档的图示意图 团队对工作流结构的评审 可以从 Graph API 构建检查清单 或 用 Graph API 思考 开始。"},{"h":"Functional API（其他框架）#","id":"functional-api其他框架","t":"当你已有其他框架中的智能体，并希望获得 LangSmith Deployment 的功能、又不想把该智能体重写为图时，请选择 Functional API： 对现有过程式代码或框架代码的改动最小 标准控制流（ if / else 、循环、函数调用） 以函数作用域内的值为单位，而非共享状态模式 关于封装并部署的模式，请参见 部署其他框架 。关于 Functional API 的概念与操作指南，请参见 Functional API 概览 。"},{"h":"并排形态对比#","id":"并排形态对比","t":"同一个小工作流在两套 API 中写法不同。下面的示例先对一个数字分类，然后返回一条消息： Graph Functional python 复制 python 复制 Graph API 让状态与转换变得显式。Functional API 保留普通的控制流，并在任务之间传递值。 关注点 Graph API Functional API 风格 声明式的节点、边和共享状态 命令式函数，配合 @entrypoint / @task （Python）或 entrypoint / task （TypeScript） 控制流 边和"},{"h":"另请参阅#","id":"另请参阅","t":"Graph API 构建检查清单 用 Graph API 思考 Graph API 概览 选择工作单元 部署其他框架 Functional API 概览 将这些文档连接 到你选择的智能体，通过 MCP 获得实时回答。 在 GitHub 上编辑此页 或 提交 issue 。"}]},{"slug":"persistence","url":"persistence.html","title":"持久化","group":"核心能力","sections":[{"h":"快速开始#","id":"快速开始","t":"使用检查点保存器、存储或两者来编译你的图： python 复制 ℹ 注意 Agent Server 会自动处理持久化 使用 Agent Server 时，你无需手动实现或配置检查点保存器或存储。服务器会在后台处理持久化基础设施。"},{"h":"检查点保存器与存储#","id":"检查点保存器与存储","t":"检查点保存器 存储 持久化内容 图状态快照 应用定义的键值数据 范围 单个线程 跨线程 记忆类型 短期、线程范围的记忆 长期、跨线程的记忆 用途 对话连续性、人在回路、时间旅行和容错 用户偏好、事实和共享知识 访问方式 在图配置中传入 thread_id 从节点或应用代码中读写条目 完整指南 Checkpointers Stores"},{"h":"常见问题排查#","id":"常见问题排查","t":""},{"h":"PostgresSaver：thread_id 过长#","id":"postgressaverthreadid-过长","t":"使用 PostgresSaver （或 AsyncPostgresSaver ）时， thread_id 存储在一个长度有限的列中。如果你的 thread_id 超过该列的长度，就会看到数据库错误。 修复： 将 thread_id 的值控制在 255 个字符以内。如果需要确定性 ID，请使用 UUID 或哈希： python 复制"},{"h":"MemorySaver 在重启之间不会持久化#","id":"memorysaver-在重启之间不会持久化","t":"MemorySaver 和 InMemorySaver 将检查点存储在 RAM 中。进程重启时，所有检查点都会丢失。 修复： 生产环境中请使用持久化的检查点保存器： PostgresSaver ：支持异步的 PostgreSQL SqliteSaver ：用于开发的本地文件存储"},{"h":"检查点无限增长#","id":"检查点无限增长","t":"在长对话中，检查点会不断累积。这可能增加延迟和存储成本。 修复： 定期清理旧检查点，或设置保留策略： python 复制"},{"h":"从父图访问子图的状态#","id":"从父图访问子图的状态","t":"当子图更新状态时，父图可能不会立即看到这些变化。这是因为每个子图管理自己的检查点命名空间。 修复： 对需要跨图边界的数据使用 通过存储共享状态 ，或将子图配置为写入父检查点。"},{"h":"后续步骤#","id":"后续步骤","t":"使用检查点保存器 来持久化并检查线程状态。 使用存储 来跨线程持久化需要长期保留的数据。 将这些文档连接 到你选择的智能体，通过 MCP 获取实时答案。 在 GitHub 上编辑此页面 或 提交问题 。"}]},{"slug":"checkpointers","url":"checkpointers.html","title":"检查点保存器","group":"核心能力","sections":[{"h":"为什么使用检查点保存器#","id":"为什么使用检查点保存器","t":"以下功能需要使用检查点保存器： 人在回路 ：检查点保存器通过允许人类检查、中断和批准图的步骤来支持 人在回路工作流 。这些工作流需要检查点保存器，因为用户必须能够查看图在任意时间点的状态，并且图必须能够在用户对状态做出任何更新后恢复执行。示例见 中断 。 记忆 ：检查点保存器允许交互之间存在 \"记忆\" 。对于重复的人类交互（例如对话），任何后续消息都可以发送到该线程，线程会保留对先前消息的记忆。有关如何使用检查点保存器添加和管理对话记忆的信息，请参见 添加记忆 。 时间旅行 ：检查点保存器允许 \"时间旅行\" ，使用"},{"h":"核心概念#","id":"核心概念","t":""},{"h":"线程#","id":"线程","t":"线程是分配给检查点保存器所保存的每个检查点的唯一 ID 或线程标识符。它包含一系列 运行 的累积状态。当执行一次运行时，助手底层图的 状态 将被持久化到该线程。 使用检查点保存器调用图时，你 必须 在配置的 configurable 部分中指定 thread_id ： python 复制 线程的当前状态和历史状态都可以被检索。要持久化状态，必须在执行运行之前创建线程。LangSmith API 提供了多个用于创建和管理线程及线程状态的端点。详情请参见 API 参考 。 检查点保存器使用 thread_id 作为存储"},{"h":"检查点#","id":"检查点","t":"线程在特定时间点的状态称为检查点。检查点是在每个 超步 保存的图状态快照，由 StateSnapshot 对象表示（完整字段参考见 StateSnapshot 字段 ）。 超步 LangGraph 会在每个 超步 边界创建一个检查点。超步是图的一次单独“tick”，在该步中被调度的所有节点都会执行（可能并行执行）。对于像 START -> A -> B -> END 这样的顺序图，输入、节点 A 和节点 B 分别有各自的超步——每完成一个就会产生一个检查点。理解超步边界对 时间旅行 很重要，因为你只能从检查点（即超"},{"h":"获取与更新状态#","id":"获取与更新状态","t":""},{"h":"获取状态#","id":"获取状态","t":"与已保存的图状态交互时，你 必须 指定 线程标识符 。你可以通过调用 graph.get_state(config) 查看图的*最新*状态。该调用会返回一个 StateSnapshot 对象，它对应配置中提供的线程 ID 所关联的最新检查点；如果提供了检查点 ID，则对应线程中该检查点 ID 所关联的检查点。 python 复制 在此示例中， get_state 的输出如下所示： text 复制 StateSnapshot 字段 字段 类型 描述 values dict 该检查点处的状态通道值。 next tupl"},{"h":"获取状态历史#","id":"获取状态历史","t":"你可以通过调用 \u00000\u0000 获取给定线程的完整图执行历史。该调用会返回一个 StateSnapshot 对象列表，对应配置中提供的线程 ID。重要的是，检查点按时间先后排序，最新的检查点 / StateSnapshot 位于列表首位。 python 复制 在此示例中， \u00000\u0000 的输出如下所示： text 复制 查找特定检查点 你可以过滤状态历史，以查找符合特定条件的检查点： python 复制 列出所有线程 若要查看检查点保存器为哪些线程保存了状态（例如构建管理视图或调试视图），在列出检查点时省略 thread_id "},{"h":"重放#","id":"重放","t":"重放会从先前的检查点重新执行步骤。用先前的 checkpoint_id 调用图，即可重新运行该检查点之后的节点。该检查点之前的节点会被跳过（其结果已保存）。该检查点之后的节点会重新执行，包括任何 LLM 调用、API 请求或 中断 ——中断在重放期间总是会被重新触发。 有关重放历史执行的完整细节和代码示例，请参阅 时间旅行 。"},{"h":"更新状态#","id":"更新状态","t":"你可以使用 \u00000\u0000 编辑图状态。这会用更新后的值创建一个新的检查点——它不会修改原始检查点。该更新与节点更新的处理方式相同：当定义了 归并函数 时，值会通过归并函数传递，因此带归并函数的通道会*累积*值，而不是覆盖值。 你可以选择指定 as_node ，以控制该更新被视为来自哪个节点，这会影响接下来执行哪个节点。详情请参阅 时间旅行：\u00001\u0000 。"},{"h":"持久化模式#","id":"持久化模式","t":"LangGraph 支持三种持久化模式，让你可以在性能与数据一致性之间取得平衡。你可以在调用任意图执行方法时指定持久化模式： python 复制 持久化模式按持久性从低到高排列如下： \"exit\" ：LangGraph 仅在图执行退出时持久化变更——无论是成功、出错，还是由于人在回路中断而退出。这为长时间运行的图提供了最佳性能，但意味着中间状态不会被保存，因此你无法在执行中途从系统故障（例如进程崩溃）中恢复。 \"async\" ：LangGraph 在下一步执行期间异步持久化变更。这提供了良好的性能与持久性，但如果进"},{"h":"新线程上的首个持久化检查点#","id":"新线程上的首个持久化检查点","t":"对于新线程，持久化模式还决定了在第一个用户节点执行之前提交哪些检查点。内部的 __start__ 超步会先运行；步骤 0 是在该超步之后写入的循环检查点。 \"exit\" ：在运行结束之前不存在任何检查点。运行期间崩溃不会留下该线程的任何记录。 \"async\" ：LangGraph 会在第一个用户节点执行之前开始写入输入检查点，但不等待写入完成。第一个用户节点可能在任何一个检查点提交之前就已运行。 \"sync\" ：LangGraph 会在第一个用户节点执行之前提交输入检查点（步骤 -1 ）和步骤 0 检查点。 ⚠ 警"},{"h":"优化检查点存储#","id":"优化检查点存储","t":"默认情况下，LangGraph 检查点会在每个超步写入每个状态通道的完整值。对于累积量很大的长时间运行线程——例如多轮对话——这可能会随着时间推移导致存储量显著增长。 \u00000\u0000 只存储增量差值，而不是完整的累积值，从而大幅减小追加密集型通道的检查点大小。用法以及存储与延迟之间的权衡请参见 DeltaChannel 。 ⚠ 警告 DeltaChannel 需要 langgraph>=1.2 ，目前处于 beta 阶段。该 API 在未来的版本中可能发生变化。"},{"h":"检查点库#","id":"检查点库","t":"在底层，检查点由符合 \u00000\u0000 接口的检查点对象驱动。LangGraph 提供了多种检查点实现，它们全部通过独立、可安装的库实现。 ℹ 注意 有关可用的提供方，请参阅 检查点集成 。 langgraph-checkpoint ：检查点保存器的基接口（ \u00001\u0000 ）以及序列化/反序列化接口（ \u00002\u0000 ）。包含用于实验的内存检查点实现（ \u00003\u0000 ）。LangGraph 自带 langgraph-checkpoint 。 langgraph-checkpoint-sqlite ：一种使用 SQLite 数据库的 LangGr"},{"h":"检查点接口#","id":"检查点接口","t":"每个检查点都符合 \u00000\u0000 接口，并实现以下方法： .put - 存储检查点及其配置和元数据。 .put_writes - 存储与检查点关联的中间写入（即 待处理写入 ）。 .get_tuple - 根据给定配置（ thread_id 和 checkpoint_id ）获取检查点元组。用于在 graph.get_state() 中填充 StateSnapshot 。 .list - 列出符合给定配置和筛选条件的检查点。用于在 graph.get_state_history() 中填充状态历史。传入 config=No"},{"h":"序列化器#","id":"序列化器","t":"当检查点保存图状态时，它们需要序列化状态中的通道值。这通过序列化器对象完成。 langgraph_checkpoint 定义了用于实现序列化器的 协议 ，并提供了默认实现（ \u00001\u0000 ），可处理多种类型，包括 LangChain 和 LangGraph 基础类型、日期时间、枚举等。 使用 pickle 进行序列化 默认序列化器 \u00000\u0000 在底层使用 ormsgpack 和 JSON，这并不适用于所有类型的对象。 如果你希望为 msgpack 编码器目前不支持的对象的（例如 Pandas 数据帧）回退到 pickle， "},{"h":"构建自定义检查点#","id":"构建自定义检查点","t":"💡 提示 在构建过程中，使用 一致性测试套件 验证你的实现。它覆盖全部五个基础方法以及包括增量通道在内的扩展能力。在发布前于 CI 中运行它。 本节介绍如何从零开始为自定义存储后端实现 BaseCheckpointSaver 。如果你已有可用的检查点，只需要添加增量通道支持，请跳转到 增量通道支持 。"},{"h":"概述#","id":"概述","t":"LangGraph 的持久化层构建在两个存储抽象之上： 检查点表 —— 每个超步一行；存储序列化的图状态（ channel_values 、 channel_versions 、 versions_seen ），并链接到其父检查点。 写入表 —— 每个超步内每个节点输出一行；存储链接到检查点的 (task_id, channel, value) 元组。 你的检查点管理器同时管理这两张表。 put 写入一行检查点； put_writes 写入节点输出行； get_tuple 将二者读取回 CheckpointTupl"},{"h":"基础契约#","id":"基础契约","t":"继承 BaseCheckpointSaver 并实现这五个方法。它们全部是必需的——缺少基类方法会在运行时抛出 NotImplementedError 。 python 复制 put / aput 存储一行检查点记录。返回带有已存储的 checkpoint_id 的更新后配置。 关键要求： 使用 self.serde.dumps_typed(checkpoint) 序列化检查点——它会处理所有 LangGraph 原生类型，包括 delta 通道使用的 _DeltaSnapshot 数据块。 完整存储 metada"},{"h":"行键 / 索引设计#","id":"行键-索引设计","t":"你存储和索引检查点的方式会直接影响正确性与性能。 推荐模式（SQL）： sql 复制 由于 checkpoint_id 是 ULID，它按字典序排序——值越大越新。\"获取最新\"就是 ORDER BY checkpoint_id DESC LIMIT 1 ；\"按 ID 获取\"就是在主键上做等值查找。 对于非 SQL 存储： 同样的原则适用。无论你采用哪种键方案，按 (thread_id, checkpoint_ns, checkpoint_id) 直接查找都必须是 O(1) 或接近 O(1)。避免那种按 ID 查找检"},{"h":"序列化#","id":"序列化","t":"检查点、写入和元数据始终使用 self.serde （继承自 BaseCheckpointSaver ，默认是 JsonPlusSerializer ）。不要直接对元数据使用 pickle ——它能工作，但 JsonPlusSerializer 产生人类可读的输出，并且版本处理更好。 JsonPlusSerializer 会自动处理所有 LangGraph 原生类型： _DeltaSnapshot ——delta 通道使用的哨兵数据块（msgpack 扩展码 7） Pydantic v2 模型、dataclasse"},{"h":"扩展能力#","id":"扩展能力","t":"这些方法是可选的，但能解锁额外的 Agent Server 功能。如果你的存储后端能够高效支持它们，就实现它们。 方法 它启用的能力 adelete_for_runs 回滚多任务策略 acopy_thread 高效的线程分叉 aprune 线程历史修剪 aget_delta_channel_history 高效的 delta 通道状态重建（见下文） Agent Server 会在启动时自动检测你的检查点器实现了哪些能力，并激活相应的功能。"},{"h":"Delta 通道支持#","id":"delta-通道支持","t":"ℹ 注意 DeltaChannel 处于 beta 阶段。 在设计稳定之前，API 与磁盘上的表示形式都可能发生变化。 DeltaChannel 是一种归并函数通道，它在检查点 blob 中只存储一个哨兵值（ MISSING ），而不是完整的通道值。状态通过归并函数重放祖先写入来重建。这使得对于像 messages 这类随时间不断累积的通道，每一步的检查点 blob 为 O(1)，而不是 O(N)。 运行时需要什么 当加载一个其 delta 通道不在 channel_values 中的检查点时，LangGraph "},{"h":"使用一致性测试套件进行测试#","id":"使用一致性测试套件进行测试","t":"langgraph-checkpoint-conformance 会依据完整契约验证你的实现，包括 delta 通道历史： python 复制 python 复制 该套件会自动检测你的检查点器实现了哪些扩展能力（包括 aget_delta_channel_history ），并针对每项能力运行相应的测试。在发布之前，请把它纳入你的 CI 流程。 将本文档连接到你的智能体 ，通过 MCP 获取实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"stores","url":"stores.html","title":"存储","group":"核心能力","sections":[{"h":"基本用法#","id":"基本用法","t":"以下代码片段单独展示 InMemoryStore ，未使用 LangGraph： python 复制 记忆通过 tuple 划分命名空间，在下面的示例中为 (<user_id>, \"memories\") 。命名空间可以是任意长度、表示任意内容，不必是用户特定的。 python 复制 使用 store.put 方法将记忆保存到存储中的命名空间。指定上文定义的命名空间，以及记忆的键值对：键就是记忆的唯一标识符（ memory_id ），值（一个字典）就是记忆本身。 python 复制 使用 store.search 方"},{"h":"列出命名空间中的条目#","id":"列出命名空间中的条目","t":"在不传入 query 和 filter 的情况下调用 \u00002\u0000 （或异步的 \u00003\u0000 ），会返回存储在 namespace_prefix 下的条目，数量最多为 limit 。当不需要语义排序时，可用它来枚举命名空间中的所有内容。 python 复制 有三点行为需要注意： namespace_prefix 按前缀匹配，而非精确匹配。 (\"alice\",) 也会返回 (\"alice\", \"memories\") 、 (\"alice\", \"preferences\") 等下的条目。若要限定到单一层级，请传入完整命名空间，或在客户"},{"h":"语义搜索#","id":"语义搜索","t":"除了简单的检索之外，存储还支持语义搜索，让你可以基于含义而非精确匹配来查找记忆。要启用该功能，请为存储配置嵌入模型： python 复制 现在搜索时，你可以使用自然语言查询来查找相关记忆： python 复制 你可以通过配置 fields 参数，或在存储记忆时指定 index 参数，来控制记忆的哪些部分会被嵌入： python 复制"},{"h":"在 LangGraph 中使用#","id":"在-langgraph-中使用","t":"存储与检查点保存器协同工作：检查点保存器将状态保存到线程中（如上所述），而存储允许你保存任意信息，以便*跨*线程访问。使用检查点保存器和存储编译图的方式如下。 python 复制 然后像之前一样，使用 thread_id 调用图，同时使用 user_id ，它像之前一样充当该特定用户记忆的命名空间。 python 复制 你可以通过 Runtime 对象从*任意节点*访问存储和 user_id 。当你在节点函数中将其添加为参数时，LangGraph 会自动注入 Runtime 。你可以用它来保存记忆： python "},{"h":"构建自定义存储#","id":"构建自定义存储","t":"要使用除内置实现之外的存储后端，请继承 BaseStore 并实现其必需的方法。内置的 InMemoryStore 是最简单的参考实现。"},{"h":"基础契约#","id":"基础契约","t":"全部五个异步方法都是必需的。同步对应方法（ put 、 get 、 delete 、 search 、 list_namespaces ）是可选的，但建议提供，以兼容同步图执行。 方法 描述 aput(namespace, key, value, index=None) 存储或覆盖单个条目 aget(namespace, key) 按键检索单个条目；不存在时返回 None adelete(namespace, key) 删除单个条目 asearch(namespace_prefix, *, query=None, "},{"h":"命名空间设计#","id":"命名空间设计","t":"命名空间是字符串元组，例如 (\"user_id\", \"memories\") 。存储实现必须支持： 前缀匹配 ： asearch((\"alice\",)) 返回 (\"alice\",) 、 (\"alice\", \"memories\") 以及其他任何子命名空间下的条目。 精确键查找 ： aget((\"alice\", \"memories\"), \"some-key\") 必须是 O(1) 或接近 O(1)。 对于 SQL 后端，一种常见的模式是： sql 复制"},{"h":"序列化#","id":"序列化","t":"存储值是普通的 Python 字典——不需要特殊的序列化器。使用 json.dumps / json.loads 或直接使用 JSONB 列进行序列化。不要存储无法 JSON 序列化的原始 Python 对象。"},{"h":"语义搜索支持#","id":"语义搜索支持","t":"如果你的后端支持向量搜索，请在 asearch 上实现 query 参数： 接受 query: str | None 参数。 当 query 不为 None 时，对其进行嵌入并按余弦相似度对结果排序。 当提供 query 时，结果中的每个 Item 应包含 score 字段。 如果你的后端不支持向量搜索，在传入 query 时抛出 NotImplementedError 。"},{"h":"测试#","id":"测试","t":"目前还没有针对自定义存储的一致性测试套件。请以 InMemoryStore 作为参考进行测试： python 复制"},{"h":"后续步骤#","id":"后续步骤","t":"将自定义存储添加到 Agent Server — 部署你的实现 检查点保存器 — 线程范围的状态持久化 将这些文档 连接 到你选择的智能体，通过 MCP 获取实时答案。 在 GitHub 上 编辑此页面 或 提交 issue 。"}]},{"slug":"fault-tolerance","url":"fault-tolerance.html","title":"容错","group":"核心能力","sections":[{"h":"重试#","id":"重试","t":"重试策略会根据异常类型和退避设置，自动重新运行失败的节点尝试。 将 retry_policy= 传给 \u00001\u0000 ： python 复制"},{"h":"默认行为#","id":"默认行为","t":"默认情况下， retry_on 使用 default_retry_on ，它会重试 任何 异常，以下异常（及其子类）除外： ValueError TypeError ArithmeticError ImportError LookupError NameError SyntaxError RuntimeError ReferenceError StopIteration StopAsyncIteration OSError 对于来自 requests 和 httpx 等流行 HTTP 库的异常，它只会在状态码为 5"},{"h":"参数#","id":"参数","t":"参数 类型 默认值 描述 max_attempts int 3 最大尝试次数，包含第一次尝试。 initial_interval float 0.5 首次重试前的秒数。 backoff_factor float 2.0 每次重试后应用于间隔的乘数。 max_interval float 128.0 重试之间的最大秒数。 jitter bool True 为间隔添加随机抖动。 retry_on type[Exception] | Sequence[type[Exception]] | Callable[[Except"},{"h":"自定义重试逻辑#","id":"自定义重试逻辑","t":"向 retry_on 传入一个可调用对象或异常类型。导入 default_retry_on 以扩展默认行为： python 复制"},{"h":"查看重试状态#","id":"查看重试状态","t":"在节点内部使用执行信息来查看当前尝试序号。当主调用持续失败时，这对切换到备用方案很有用： python 复制 execution_info 暴露以下字段： 属性 类型 描述 node_attempt int 当前尝试序号（从 1 开始）。首次尝试为 1 ，首次重试为 2 ，依此类推。 node_first_attempt_time float | None 首次尝试开始时的 Unix 时间戳。在多次重试之间保持不变。 thread_id str | None 当前执行的线程 ID。未使用检查点保存器时为 None "},{"h":"重试边界与幂等性#","id":"重试边界与幂等性","t":"重试 会从头重新运行整个节点函数。这为节点执行提供了 至少一次 语义：当策略匹配时，LangGraph 会再次调用该节点。它并不能让外部副作用恰好发生一次。 text 复制 检查点 在 超步 边界写入，而不是在函数执行中途写入。失败尝试产生的图写入会被丢弃。节点执行期间的副作用（支付、邮件、外部写入）不在此边界内。应用代码必须让这些副作用具备幂等性。 同样的重新执行模型也适用于 中断 之后或崩溃恢复之后。请参阅 重新执行与幂等性 。要在节点内部对工作进行保存点，以便恢复时跳过已完成的单元，请把每个单元包装在 任务 "},{"h":"使用幂等键保护副作用#","id":"使用幂等键保护副作用","t":"将稳定的幂等键随副作用一起发送，以便服务提供商可以对重试去重。该键必须在副作用运行 之前 就已持久化。不要在同一节点内生成它并依赖其返回值： text 复制 K1 从未被写入检查点。请从已经持久化的状态中派生该键： python 复制 当不存在持久的业务标识时，在副作用之前用一个独立节点持久化生成的键。在进程崩溃的情况下，只有当中间的检查点已持久化时，这种做法才有效。该模式请使用 同步持久化 。 python 复制 两项要求： 该键可从持久状态重现。 重试或在全新进程中的恢复会重建出相同的键。 外部服务遵守该键。 "},{"h":"将缺失的确认视为未知#","id":"将缺失的确认视为未知","t":"如果服务提供商已提交而确认丢失，图就没有本地记录，即使副作用可能已经发生。当服务提供商去重时，后续使用相同键的尝试可以避免盲目重复，但结果仍然未知。把缺失的本地状态视为未知，而不是视为副作用未发生的证据。在补偿或继续之前，向服务提供商查询该操作的状态。 对于无法在 API 层面实现幂等的副作用，请将它们移出可重试的节点。例如，在重试耗尽后从 错误处理器 中运行它们，或从一个按任务 ID 去重的独立 worker 中运行。"},{"h":"超时#","id":"超时","t":"ℹ 注意 需要 langgraph>=1.2 。 \u00000\u0000 上的 timeout= 参数用于限制单个节点在一次尝试中可运行的时长。传入一个数字（秒）、一个 timedelta ，或一个 \u00003\u0000 以分别设置运行限制与空闲限制： python 复制 ⚠ 警告 节点超时仅适用于 异步 节点。为同步节点设置 timeout 会在编译期被拒绝。若要包装阻塞式 I/O，请在异步节点内使用 asyncio.to_thread 。"},{"h":"运行超时#","id":"运行超时","t":"run_timeout 是对单次尝试的硬性实际耗时上限。无论节点是否有活动，它都不会被刷新： python 复制 当超出该限制时，LangGraph 会抛出 \u00000\u0000 ，清除失败尝试产生的所有写入，并由重试策略决定是否重试。"},{"h":"空闲超时#","id":"空闲超时","t":"idle_timeout 是一种可因进展而重置的上限。只有当节点在指定时长内停止产生可观测的进展时，它才会触发——与 run_timeout 不同，只要节点产生进展信号，计时就会重置： python 复制 你可以同时设置 run_timeout 和 idle_timeout 。两者中先触发的一方会取消该次尝试。 进展信号 在默认的 refresh_on=\"auto\" 下，空闲计时会在以下任一情况下重置： 通过 CONFIG_KEY_SEND 进行的状态写入 流式输出（产出的异步流式数据块） 子任务调度 运行时流写入"},{"h":"NodeTimeoutError#","id":"nodetimeouterror","t":"超时触发时，LangGraph 会抛出 \u00000\u0000 ，并附带说明命中了哪个限制的结构化上下文： 属性 类型 描述 node str 执行超时的节点名称。 elapsed float 超时触发前经过的秒数。 kind Literal[\"idle\", \"run\"] 触发的是哪种超时。 idle_timeout float | None 所配置的空闲超时（秒），如有。 run_timeout float | None 所配置的运行超时（秒），如有。 NodeTimeoutError 默认可重试。将 timeout 与重试策略"},{"h":"使用 Send 设置动态超时#","id":"使用-send-设置动态超时","t":"使用 \u00000\u0000 动态派发节点时（例如在 map-reduce 模式中），可以直接在 Send 上传入超时，以覆盖目标节点针对该次推送的静态超时： python 复制 若在 Send 上省略超时，则适用目标节点的超时（在 \u00001\u0000 时设置）。这样你可以为节点设置默认超时，并针对单次调用收紧它。"},{"h":"错误处理#","id":"错误处理","t":"ℹ 注意 需要 langgraph>=1.2 。 错误处理器在节点失败且所有重试都已耗尽后运行。它接收当前状态，可以更新状态，或使用 \u00000\u0000 路由到其他节点。这适用于补偿流程（Saga 模式），在这种流程中你希望优雅地恢复，而不是中止整个图。 将 error_handler= 传给 \u00001\u0000 ： python 复制 只有当重试策略耗尽后，处理器才会触发；如果未配置重试策略，则立即触发。重试策略与错误处理器彼此解耦：可以独立配置何时重试、何时补偿。"},{"h":"NodeError#","id":"nodeerror","t":"错误处理器通过带类型的 error: NodeError 参数接收失败上下文，该参数由类型注解注入（与 runtime: Runtime 的模式相同）： python 复制 \u00000\u0000 是一个冻结的 dataclass，包含两个字段： 属性 类型 描述 node str 执行失败的节点名称。 error BaseException 失败节点抛出的异常。 error: NodeError 参数是可选的。不需要失败上下文的处理器可以使用更简单的签名，例如 (state) 或 (state, runtime) 。"},{"h":"使用 Command 路由#","id":"使用-command-路由","t":"错误处理器可以返回 \u00000\u0000 来更新状态并路由到特定节点，从而实现 Saga / 补偿模式： python 复制 charge_payment 会在遇到 ConnectionError 时最多重试 3 次。如果重试耗尽（或错误不是 ConnectionError ），处理器会通过更新状态并路由到 finalize 来执行补偿，而不是中止图。"},{"h":"可安全恢复的失败#","id":"可安全恢复的失败","t":"ℹ 注意 失败来源会被记录到检查点。如果图被中断，或进程在节点失败之后、处理器完成之前崩溃，那么当图从检查点恢复时，处理器看到的仍是相同的 NodeError 上下文。"},{"h":"与 interrupt() 的行为#","id":"与-interrupt-的行为","t":"⚠ 警告 在节点内部抛出的 interrupt() 不会 被路由到错误处理器。中断使用 GraphBubbleUp 机制来暂停图执行，以支持人在回路工作流，绕过重试策略和错误处理器。图会照常暂停。"},{"h":"子图失败#","id":"子图失败","t":"如果某个节点封装了一个子图，且子图抛出了未处理的异常，该异常会浮现到父节点。如果父节点配置了错误处理器，处理器会触发，并在 error.error 中携带子图的异常。"},{"h":"恢复策略#","id":"恢复策略","t":"重试和错误处理器涵盖了自动重试以及耗尽后的补偿。另外两种常见模式存在于你的节点逻辑中： 策略 由谁修复 机制 瞬时错误 系统 节点上的 重试策略 重试后可恢复的失败 开发者 \u00000\u0000 / \u00001\u0000 （Saga / 补偿） LLM 可恢复的错误 LLM 将错误存入状态，并使用 \u00000\u0000 路由回去 用户可修复的错误 人类 使用 \u00000\u0000 暂停 意外错误 开发者 让异常向上浮现并使运行失败"},{"h":"LLM 可恢复的错误#","id":"llm-可恢复的错误","t":"当工具调用或解析以模型能够纠正的方式失败时，在节点中捕获该错误、将其写入状态，并路由回智能体，以便 LLM 进行调整： python 复制 这是应用层面的控制流，而不是 error_handler 。节点处理一种已知的失败模式，并让运行继续存活。"},{"h":"意外错误#","id":"意外错误","t":"不要捕获你无法处理的失败。如果没有匹配的重试策略或错误处理器，异常会向上浮现并使运行失败，以便你修复缺陷： python 复制"},{"h":"图默认值#","id":"图默认值","t":"ℹ 注意 需要 langgraph>=1.2 。 无需在每次 add_node 调用中重复相同的 retry_policy= 、 error_handler= 、 timeout= 或 cache_policy= ，可以使用 \u00005\u0000 在一个地方配置图级别的全局默认值： python 复制 现在 step_a 和 step_b 共享同一套重试策略、错误处理器和超时配置，无需任何重复。"},{"h":"优先级#","id":"优先级","t":"直接传给 add_node() 的节点级取值始终会覆盖 set_node_defaults() 设置的默认值。默认值在 compile() 时解析，因此你可以在 add_node() 之前或之后以任意顺序调用 set_node_defaults() ： python 复制"},{"h":"默认错误处理器#","id":"默认错误处理器","t":"当每次图运行都对应一个外部流程（例如后台任务表中的一行），且任何未处理的节点失败都应将那个流程标记为失败时， error_handler 默认值尤其有用，这样就不必在每个 add_node 上重复 error_handler= 。当某个步骤需要自己的逻辑时，节点级处理器仍然优先： python 复制 如果 fetch_data 在重试后仍然失败，则运行 mark_process_failed 。如果 charge_payment 在重试后仍然失败，则改为运行 refund_payment ，因为节点级处理器覆盖了默"},{"h":"适用性矩阵#","id":"适用性矩阵","t":"并非所有默认值都适用于所有节点类型。错误处理器节点（通过 add_node(error_handler=...) 注册的节点）会被排除在某些默认值之外，以防止不安全行为： set_node_defaults 参数 适用于常规节点 适用于错误处理器节点 原因 retry_policy ✅ ✅ 处理器在瞬时故障时应被重试 timeout ✅ ✅ 卡住的处理器应像卡住的常规节点一样被取消 error_handler ✅ ❌ 处理器绝不能捕获自身 cache_policy ✅ ❌ 缓存处理器结果是不安全的"},{"h":"作用范围#","id":"作用范围","t":"在父图上设置的默认值 不会 被子图继承。每个图维护自己的默认值。"},{"h":"Functional API#","id":"functional-api","t":"Functional API 中的 @task 和 @entrypoint 也提供相同的 timeout= 和 retry_policy= 参数： python 复制 其行为与 add_node 完全一致：超时时抛出 NodeTimeoutError ，缓冲区中的写入被清除，由重试策略决定是否重试。"},{"h":"优雅关闭#","id":"优雅关闭","t":"协作式关闭让你可以在当前超步完成后停止正在进行的图运行，并保存一个可恢复的检查点。这对于处理 SIGTERM 信号，或任何需要在不丢失工作的情况下回收资源的外部监管程序都很有用。 ℹ 注意 需要 langgraph>=1.2 。 创建一个 \u00000\u0000 并将其作为 control= 传给 invoke 或 stream 。从任意线程调用 request_drain() 以发出运行应停止的信号： python 复制"},{"h":"语义#","id":"语义","t":"排空是协作式的，在超步之间生效，绝不会抢占已在运行的工作： 场景 行为 节点正在执行中 运行至完成。排空在下一个超步生效。 带重试策略的节点正在重试 重试循环运行至耗尽或成功。排空在其后生效。 图在与排空同一轮次自然结束 正常返回。检查 control.drain_requested 以区分于普通运行。 还有剩余超步 抛出 GraphDrained(reason) 。检查点已保存且可恢复。 子图请求排空 GraphDrained 冒泡穿过父图，并在父图自己的下一个超步边界处停止它。"},{"h":"排空后恢复#","id":"排空后恢复","t":"使用相同的 thread_id ，通过 invoke(None, config) 恢复已排空的运行： python 复制"},{"h":"在节点内读取排空状态#","id":"在节点内读取排空状态","t":"通过 runtime 参数访问排空状态，以便在到达超步边界之前调整节点行为： python 复制"},{"h":"SIGTERM 钩子模式#","id":"sigterm-钩子模式","t":"处理进程关闭的推荐模式： python 复制 ℹ 注意 request_drain() 不会取消正在运行的 asyncio 任务，也不会终止线程。如果需要硬性上限，请将排空与优雅超时和任务取消结合使用。"},{"h":"限制#","id":"限制","t":"超时仅支持异步 ：带 timeout 的同步节点会在编译时被拒绝。 每个节点一个处理器 ：每个节点最多只能有一个 error_handler 。 处理器失败会向上冒泡 ：如果错误处理器本身抛出异常，该异常会像该节点没有处理器一样向外传播。 set_node_defaults 不会被子图继承 ：每个图独立管理自己的默认值。 Connect these docs to your agent of choice via MCP for real-time answers. Edit this page on GitHub"}]},{"slug":"event-streaming","url":"event-streaming.html","title":"事件流式输出","group":"核心能力","sections":[{"h":"快速开始#","id":"快速开始","t":"py 复制 如果想对部署在 Agent Server 后面的图进行流式输出，请参阅 LangSmith Streaming API 。"},{"h":"各部分如何协同工作#","id":"各部分如何协同工作","t":"流式输出栈包含两个主要层级： 流式输出（Streaming） 从 Pregel 引擎发出原始的图执行事件。 事件流式输出（Event streaming） 对这些事件进行规范化，让它们经过流转换器，并暴露类型化投影。 Pregel 引擎运行图步骤 发出 原始 Pregel 事件 updates 、 values 、 messages 、 custom 、 checkpoints 、 tasks 、 debug 发送至 事件路由器让每个事件经过转换器管道 级联经过 流转换器 ValuesTransformerMess"},{"h":"事件流式输出提供的能力#","id":"事件流式输出提供的能力","t":"运行流在单一底层事件流之上暴露类型化投影： 投影 用途 stream 遍历每个协议事件。 stream.messages 流式输出聊天模型消息与 token 增量。 stream.values 遍历状态快照并等待最终值。 stream.output 等待最终输出。 stream.subgraphs 发现并观察嵌套的图执行。 stream.interrupts 查看人在回路的中断载荷。 stream.interrupted 检查运行是否因等待人工输入而暂停。 stream.extensions 消费自定义流转换器的投"},{"h":"流式输出消息#","id":"流式输出消息","t":"使用 stream.messages 处理聊天模型输出： py 复制 在同步代码中， message.text 是可迭代的。逐 token 输出时遍历它，或调用 str(message.text) 获取完整文本。 message.reasoning 暴露推理增量。 message.tool_calls 暴露工具调用块。每个块包含该调用的 id 、 name ，以及其 args 中新增的部分。如果你需要按精确到达顺序获取文本、推理和工具调用块，请遍历消息流的原始事件，而不是分别遍历各个投影。"},{"h":"流式输出子图#","id":"流式输出子图","t":"使用 stream.subgraphs 观察嵌套的图工作，而无需解析命名空间字符串： py 复制 subgraph.graph_name 是编译后的图或智能体的 name 。从工具分派的具名智能体（例如通过 Deep Agents task 工具调用的 create_agent(name=...) ）会以该名称出现在这里，并且开启该作用域的 lifecycle 事件带有一个 cause ，指回分派它的工具调用。更多信息请参阅 Lifecycle 。 关于产品专属的流，子智能体流请参阅 Deep Agents str"},{"h":"流式输出状态#","id":"流式输出状态","t":"使用 stream.values 在每个步骤之后流式输出完整状态快照： py 复制"},{"h":"流式输出多个投影#","id":"流式输出多个投影","t":"在异步代码中并发消费时，使用 astream_events 配合 asyncio.gather ： py 复制 对于同步代码，使用 stream.interleave(...) 按严格的到达顺序消费多个投影： py 复制"},{"h":"中断后恢复#","id":"中断后恢复","t":"当图因等待人工输入而暂停时，查看 stream.interrupted 和 stream.interrupts ，然后携带 Command 再次调用 stream_events(..., version=\"v3\") 来恢复。 恢复需要图在编译时配置了检查点保存器，并且配置中带有线程 ID——请参阅 持久化 。 py 复制"},{"h":"流式输出所有协议事件#","id":"流式输出所有协议事件","t":"当你需要原始协议事件流时，直接使用运行对象本身： py 复制 每个事件都是一个 ProtocolEvent 信封，包裹着特定通道的载荷。转换器的 process(event) 接收的也是同样的结构。 py 复制 namespace 是从根图到发出该事件的作用域的路径。根是空数组 [] 。每个子执行会添加一个 \"name:runtime_id\" 段，因此子图内部的嵌套工具调用看起来像 [\"researcher:6f4d\", \"tools:91ac\"] 。 : 之前是稳定的图或节点名称；后缀是每次调用的运行时 ID。当"},{"h":"通道与事件生命周期#","id":"通道与事件生命周期","t":"原始事件在通道上流动。通道名称会作为事件的 method 出现；每个通道发出特定形状的事件。 通道 用途 values 完整的图状态快照。 updates 每个节点的状态增量。 messages 以内容块为中心的聊天模型输出。 tools 工具调用开始、流式输出、结束和错误事件。 lifecycle 运行、子图和子智能体的状态变化。 checkpoints 用于分支和时间旅行的轻量检查点信封。 input 人在回路输入请求与响应。 tasks Pregel 任务创建与结果事件。 custom 来自图代码的用户自定义"},{"h":"消息#","id":"消息","t":"messages 通道将输出建模为内容块。数据的 event 字段为以下之一： message-start content-block-start content-block-delta content-block-finish message-finish 内容块具有明确的边界：一个块开始，发出零个或多个增量，然后结束，之后同一条消息中的下一个块才开始。这使得 token 流式输出、推理块、工具调用块和多模态内容都变得明确，而无需依赖特定提供商的格式。 message-finish 可能包含 token 用量；不"},{"h":"工具#","id":"工具","t":"tools 通道暴露工具执行过程。数据的 event 字段为以下之一： tool-started tool-output-delta tool-finished tool-error 工具事件通过工具调用 ID 关联，因此一次工具执行可以关联回 messages 通道上发起它的工具调用内容块。"},{"h":"生命周期#","id":"生命周期","t":"lifecycle 通道跟踪根运行、子图和子智能体的状态。数据的 event 字段为以下之一： started running completed failed interrupted 除 event 之外，生命周期数据还可能包含可选的 graph_name 、 error 以及 cause ，用于描述子作用域启动的原因（父工具调用、扇出发送、边转换）。"},{"h":"构建你自己的投影#","id":"构建你自己的投影","t":"流转换器是事件流式输出中的投影层。它们观察协议事件，维护自己的状态，并暴露一次运行的派生视图 —— 诸如工具活动、token 总数、进度事件、产物，或面向另一种协议的消息。 StreamChannel 是转换器用来发布这些视图的投影原语。 内置投影（ stream.messages 、 stream.values 、 stream.subgraphs 、 stream.output ）以及产品特定投影（LangChain 的 stream.tool_calls 、Deep Agents 的 stream.subag"},{"h":"转换器如何工作#","id":"转换器如何工作","t":"事件流式输出始于 LangGraph Pregel 引擎的流式输出。运行时将这些块规范化为协议事件，然后由流处理器将每个事件路由通过一栈流转换器。 mermaid 复制 流处理器是单个流的中枢调度器。对于每个协议事件，它会： 按顺序调用每个已注册转换器的 process(event) 钩子。 将具名 StreamChannel 的推送接回协议事件流。 将事件存入运行流，除非某个转换器将其抑制。 在运行结束时对每个转换器调用 finalize() 或 fail() 。 转换器是观察性的。它们不会回调图运行时。相反，它"},{"h":"转换器的结构#","id":"转换器的结构","t":"转换器实现 StreamTransformer 接口： py 复制 init() 创建投影对象。用户转换器的投影出现在 stream.extensions 下。 process() 观察每个协议事件。 ProtocolEvent 的结构参见 流式输出所有协议事件 。仅当你刻意想要抑制原始事件时才返回 false 。 finalize() 在流成功结束后关闭或结算非通道投影。 fail() 将错误传播到非通道投影。"},{"h":"声明所需的流模式#","id":"声明所需的流模式","t":"required_stream_modes 控制底层图在流式输出期间发出哪些 Pregel 流模式。运行时取所有已注册转换器 required_stream_modes 的并集，并将该并集作为 stream_mode 参数传给图的 .stream() 调用。 没有任何转换器请求的模式永远不会被发出 —— 声明 (\"custom\",) 正是让 custom 事件在整个运行中流动的原因。 py 复制 process() 接收图发出的每个事件，并负责按 event[\"method\"] 进行过滤。该声明开启上游发出；它不会"},{"h":"StreamChannel#","id":"streamchannel","t":"StreamChannel 是转换器用于流式输出值的投影原语。它始终在 stream.extensions.<name> 上暴露一个可迭代流。构造函数参数决定每次 push() 是否也作为 custom:<name> 事件流入运行的主事件流 —— 也就是说，在迭代原始协议事件时，该投影的值是否会出现。 需求 使用 仅作为侧通道投影 StreamChannel() 同时让每次 push 流入主事件流 StreamChannel(name) 具名通道的负载必须可序列化，因为每个推送的值还会在主事件流中变成 custom"},{"h":"示例：具名通道#","id":"示例具名通道","t":"向 StreamChannel 传入字符串名称，即可通过 stream.extensions 暴露流式投影， 并且 将每个推送的值作为 custom:<name> 协议事件转发到运行的主事件流中： py 复制"},{"h":"示例：未具名通道#","id":"示例未具名通道","t":"不带名称时，该通道仅是侧通道投影 —— 可通过 stream.extensions 访问，但对迭代原始事件的消费者不可见。对于持有无法序列化到主事件流中的进程内句柄（promise、异步可迭代对象、类实例）的投影，这是正确的选择。 下面的示例将未具名通道与 get_stream_writer 搭配使用，后者让图节点发出 custom 通道事件，然后由转换器将其排入投影： py 复制"},{"h":"示例：最终值投影#","id":"示例最终值投影","t":"当投影不应流入主事件流时，使用未具名流、promise 或其他进程内对象： py 复制"},{"h":"在调用时或编译时注册#","id":"在调用时或编译时注册","t":"在调用时传入转换器，以便本地实验： py 复制 当该图的每次运行都应产生该投影时，将转换器编译进图： py 复制"},{"h":"内置：ToolCallTransformer#","id":"内置toolcalltransformer","t":"LangGraph 内置了 ToolCallTransformer 。注册它即可在普通 StateGraph 上暴露 stream.tool_calls ： py 复制"},{"h":"相关内容#","id":"相关内容","t":"LangGraph 定义了流式输出的基础原语。如需在 LangChain 或 Deep Agents 中使用流式输出，请参阅相关产品文档： LangChain 智能体流式输出 介绍了 ReAct 风格的智能体消息、工具调用以及中间件更新。 Deep Agents 流式输出 介绍了子智能体、嵌套消息以及子智能体的工具调用。 LangChain 前端模式 与 LangGraph 前端模式 展示了构建在流式状态之上的 UI 使用场景。 LangSmith Streaming API 介绍了针对部署在 Agent Serv"}]},{"slug":"streaming","url":"streaming.html","title":"流式输出","group":"核心能力","sections":[{"h":"快速开始#","id":"快速开始","t":""},{"h":"基本用法#","id":"基本用法","t":"LangGraph 图提供 \u00000\u0000 （同步）和 \u00001\u0000 （异步）方法，以迭代器的形式产出流式输出。传入一个或多个 流模式 来控制你接收的数据。 python 复制 shell 复制 完整示例 python 复制 shell 复制 💡 提示 使用 LangSmith 调试流式事件、逐个令牌检查 LLM 输出并监控延迟。跟随 追踪快速入门 完成配置。"},{"h":"流式输出格式（v2）#","id":"流式输出格式v2","t":"ℹ 注意 需要 LangGraph 1.1 或更高版本。本页所有示例均使用 version=\"v2\" 。 向 stream() 或 astream() 传入 version=\"v2\" 可获得统一的输出格式。无论流模式是什么、有多少个模式、子图设置如何，每个块都是一个结构一致的 StreamPart 字典： python 复制 每种流模式都有对应的 TypedDict ，包含 \u00001\u0000 、 \u00002\u0000 、 \u00003\u0000 、 \u00004\u0000 、 \u00005\u0000 、 \u00006\u0000 、 \u00007\u0000 。你可以从 langgraph.types 导入这些类型。联合"},{"h":"流模式#","id":"流模式","t":"将以下一个或多个流模式以列表形式传给 \u00000\u0000 或 \u00001\u0000 方法： 模式 类型 说明 values \u00000\u0000 每个步骤后的完整状态。 updates \u00000\u0000 每个步骤后的状态更新。同一步骤中的多个更新会分别流式输出。 messages \u00000\u0000 LLM 调用产生的（LLM 令牌，元数据）二元组。 custom \u00000\u0000 节点通过 \u00000\u0000 发出的自定义数据。 checkpoints \u00000\u0000 检查点事件（格式与 get_state() 相同）。需要检查点保存器。 tasks \u00000\u0000 任务开始/结束事件，包含结果和错误。需要检查"},{"h":"图状态#","id":"图状态","t":"使用 updates 和 values 流模式，可以在图执行过程中对流式输出其状态。 updates 在图执行的每一步之后，流式输出状态的 更新内容 。 values 在图执行的每一步之后，流式输出状态的 完整值 。 python 复制 updates values 用于仅流式输出每一步之后各节点返回的 状态更新 。流式输出内容既包含节点名称，也包含更新内容。 python 复制 shell 复制 用于在每一步之后流式输出图的 完整状态 。 python 复制 shell 复制"},{"h":"LLM token#","id":"llm-token","t":"使用 messages 流式输出模式，可以从图的任意部分（包括节点、工具、子图或任务） 逐个 token 流式输出大语言模型（LLM）的结果。 \u00000\u0000 模式 的流式输出是一个元组 (message_chunk, metadata) ，其中： message_chunk ：来自 LLM 的 token 或消息片段。 metadata ：包含图节点与 LLM 调用相关细节的字典。 如果你的 LLM 没有对应的 LangChain 集成，可以改用 custom 模式流式输出其结果。详情参阅 与任意 LLM 搭配使用 。 "},{"h":"自定义数据#","id":"自定义数据","t":"要从 LangGraph 节点或工具内部发送 用户自定义数据 ，请按以下步骤操作： 使用 \u00000\u0000 获取流写入器并发送自定义数据。 在调用 .stream() 或 .astream() 时设置 stream_mode=\"custom\" ，以便在流中接收自定义数据。可以组合多个模式（例如 [\"updates\", \"custom\"] ），但其中至少有一个必须是 \"custom\" 。 ⚠ 警告 在 Python \\< 3.11 的异步代码中没有 \u00000\u0000 在 Python \\< 3.11 上运行的异步代码中， \u00001\u0000 将无法"},{"h":"子图输出#","id":"子图输出","t":"要将 子图 的输出包含在流式输出中，可以在父图的 .stream() 方法中设置 subgraphs=True 。这样会同时流式输出父图和所有子图的输出。 输出将以元组 (namespace, data) 的形式流式返回，其中 namespace 是一个元组，包含调用子图的节点路径，例如 (\"parent_node:<task_id>\", \"child_node:<task_id>\") 。 v2（LangGraph 1.1 或更高版本） v1（默认） 使用 version=\"v2\" 时，子图事件使用相同的 Stre"},{"h":"检查点#","id":"检查点","t":"使用 checkpoints 流式模式可以在图执行过程中接收检查点事件。每个检查点事件的格式与 get_state() 的输出相同。需要配置 检查点保存器 。 python 复制"},{"h":"任务#","id":"任务","t":"使用 tasks 流式模式可以在图执行过程中接收任务开始和结束事件。任务事件包含正在运行的节点、其结果以及任何错误的信息。需要配置 检查点保存器 。 python 复制"},{"h":"调试#","id":"调试","t":"使用 debug 流式模式可以在图执行过程中流式输出尽可能多的信息。流式输出包括节点名称以及完整状态。 python 复制 ℹ 注意 debug 模式将 checkpoints 和 tasks 事件与额外元数据组合在一起。如果只需要调试信息的一部分，可以直接使用 checkpoints 或 tasks 。"},{"h":"同时使用多种模式#","id":"同时使用多种模式","t":"你可以向 stream_mode 参数传入一个列表，从而同时流式输出多种模式。 当 version=\"v2\" 时，每个数据块都是一个 StreamPart 字典。使用 chunk[\"type\"] 来区分不同的模式： v2 v1 python 复制 python 复制"},{"h":"进阶#","id":"进阶","t":""},{"h":"与任意 LLM 配合使用#","id":"与任意-llm-配合使用","t":"你可以使用 stream_mode=\"custom\" 从 任意 LLM API 流式输出数据——即使该 API 未 实现 LangChain 聊天模型接口。 这让你可以集成原生 LLM 客户端，或集成提供自有流式接口的外部服务，从而使 LangGraph 在自定义场景下具备很强的灵活性。 python 复制 扩展示例：流式输出任意聊天模型 python 复制 让我们用一个包含工具调用的 \u00000\u0000 来调用图： python 复制"},{"h":"为特定聊天模型禁用流式输出#","id":"为特定聊天模型禁用流式输出","t":"如果你的应用同时混用了支持流式输出的模型和不支持流式输出的模型，你可能需要为不支持流式输出的 模型显式禁用流式输出。 在初始化模型时设置 streaming=False 。 init\\_chat\\_model 聊天模型接口 python 复制 python 复制 ℹ 注意 并非所有聊天模型集成都支持 streaming 参数。如果你的模型不支持该参数，请改用 disable_streaming=True 。该参数通过基类在所有聊天模型上可用。"},{"h":"迁移到 v2#","id":"迁移到-v2","t":"v2 流式输出格式（本页通篇使用）提供统一的输出格式。以下是关键差异及迁移方式的概要： 场景 v1（默认） v2（ version=\"v2\" ） 单一流模式 原始数据（dict） 包含 type 、 ns 、 data 的 StreamPart dict 多个流模式 (mode, data) 元组 相同的 StreamPart dict，按 chunk[\"type\"] 过滤 子图流式输出 (namespace, data) 元组 相同的 StreamPart dict，检查 chunk[\"ns\"] 多个模式 + 子"},{"h":"Python \\< 3.11 中的异步#","id":"python-3.11-中的异步","t":"在低于 3.11 的 Python 版本中， asyncio 任务 不支持 context 参数。 这限制了 LangGraph 自动传播上下文的能力，并在两个关键方面影响 LangGraph 的流式输出机制： 你 必须 在异步 LLM 调用（例如 ainvoke() ）中显式传入 \u00001\u0000 ，因为回调不会被自动传播。 你 不能 在异步节点或工具中使用 \u00000\u0000 ——必须直接传入 writer 参数。 扩展示例：手动传入配置的异步 LLM 调用 python 复制 扩展示例：使用 stream writer 的异步自定"}]},{"slug":"interrupts","url":"interrupts.html","title":"中断","group":"核心能力","sections":[{"h":"使用 interrupt 暂停#","id":"使用-interrupt-暂停","t":"\u00000\u0000 函数会暂停图执行并向调用方返回一个值。当你在节点内调用 \u00001\u0000 时，LangGraph 会保存当前图状态，并等待你带着输入恢复执行。 要使用 \u00000\u0000 ，你需要： 一个 检查点保存器 来持久化图状态（生产环境请使用持久化检查点保存器） 配置中有一个 线程 ID ，以便运行时知道要从哪个状态恢复 在你想暂停的位置调用 interrupt() （负载必须可 JSON 序列化） python 复制 当你调用 \u00000\u0000 时，会发生以下情况： 图执行被挂起 ，位置正是调用 \u00000\u0000 的那一点 状态被保存 ，通过检查点保存器"},{"h":"恢复中断#","id":"恢复中断","t":"中断暂停执行后，你通过再次调用图来恢复它，并传入一个包含恢复值的 Command 。恢复值会被回传给 interrupt 调用，使节点能够带着外部输入继续执行。 驱动可能发生中断的图的推荐方式是 事件流式输出 ——它通过 stream.interrupts 和 stream.interrupted 呈现中断，并通过 stream.output 暴露最终状态。 python 复制 查看示例追踪 打开此示例对应的公开 LangSmith 运行记录。 ℹ 注意 默认的 graph.invoke(...) API 仍然可用"},{"h":"定义中断响应 Schema#","id":"定义中断响应-schema","t":"\u00000\u0000 的 response_schema 参数描述了你恢复图时所期望的输入。客户端可以使用该 Schema 渲染带类型的输入表单。 ℹ 注意 中断响应 Schema 需要 langgraph>=1.2.12 。 传入一个 Pydantic 模型类、来自 typing_extensions 的 TypedDict ，或一个 dataclass 来校验恢复值。LangGraph 会将类型转换为 JSON Schema，并将其包含在 Interrupt.response_schema 中，与中断的 value 负载分开"},{"h":"常见模式#","id":"常见模式","t":"中断带来的关键能力是能够暂停执行并等待外部输入。这在多种用例中很有用，包括： 审批工作流 ：在执行关键操作（API 调用、数据库变更、金融交易）之前暂停 处理多个中断 ：在同一次调用中恢复多个中断时，将中断 ID 与恢复值配对 审查与编辑 ：让人类在继续之前审查和修改 LLM 输出或工具调用 中断工具调用 ：在执行工具调用之前暂停，以便在执行前审查和编辑该工具调用 校验人类输入 ：在进入下一步之前暂停以校验人类输入"},{"h":"使用人在回路（HITL）中断进行流式输出#","id":"使用人在回路hitl中断进行流式输出","t":"在使用人在回路工作流构建交互式智能体时，你可以使用 事件流式输出 ，在并发消费消息块与状态快照的同时处理中断。 使用 graph.stream_events(..., version=\"v3\") 返回的带类型投影，在循环中执行直到运行结束： 通过 stream.messages 逐 token 流式输出 AI 响应 通过 stream.values 观察每一步的状态快照 通过 stream.interrupted 检测中断，并从 stream.interrupts 读取其负载 通过以 Command(resume="},{"h":"处理多个中断#","id":"处理多个中断","t":"当并行分支同时中断时（例如扇出到多个节点，每个节点都调用 interrupt() ），你可能需要在单次调用中恢复多个中断。 在单次调用中恢复多个中断时，请将每个中断 ID 映射到其恢复值。 这能确保每个响应在运行时与正确的中断配对。 python 复制 查看示例追踪 打开此示例对应的公开 LangSmith 运行记录。"},{"h":"批准或拒绝#","id":"批准或拒绝","t":"中断最常见的用途之一，是在执行关键操作之前暂停并请求批准。例如，你可能想让人工批准一次 API 调用、一次数据库变更，或任何其他重要决策。 python 复制 恢复图时，传入 True 表示批准，传入 False 表示拒绝： python 复制 完整示例 python 复制 查看示例追踪 打开此示例对应的公开 LangSmith 运行记录。"},{"h":"审核并编辑状态#","id":"审核并编辑状态","t":"有时你希望让人工在继续之前审核并编辑图状态的一部分。这适用于纠正 LLM、补充缺失信息或做出调整。 python 复制 恢复时，提供编辑后的内容： python 复制 完整示例 python 复制 查看示例追踪 打开此示例对应的公开 LangSmith 运行记录。"},{"h":"工具中的中断#","id":"工具中的中断","t":"你也可以直接在工具函数内部放置中断。这样，工具在被调用时就会暂停以等待批准，并允许在执行工具调用之前对其进行人工审查与编辑。 首先，定义一个使用 \u00000\u0000 的工具： python 复制 当你希望审批逻辑与工具本身放在一起，使其可在图的不同部分复用时，这种方式很有用。LLM 可以自然地调用该工具，而中断会在工具被调用时暂停执行，让你可以批准、编辑或取消该操作。 完整示例 python 复制"},{"h":"校验人类输入#","id":"校验人类输入","t":"有时你需要校验来自人类的输入，并在值无效时重新提示。推荐的做法是 每次节点调用只调用一次 interrupt() ，从节点返回并将错误消息存储在状态中，然后使用 条件边 循环回到该节点，直到提供有效的值。 ⚠ 警告 避免在单个节点内使用 while True + interrupt() 循环。 因为节点在每次恢复时都会从头重新运行（参见 中断规则 ），一个多次调用 interrupt() 的循环会导致每次恢复都重放之前的所有迭代：第一次恢复重放 1 次迭代，第二次重放 2 次，依此类推。 正确的模式： 将重新提示的"},{"h":"中断的规则#","id":"中断的规则","t":"当你在节点内调用 \u00000\u0000 时，LangGraph 会通过抛出一个异常来挂起执行，该异常会通知运行时暂停。这个异常会沿着调用栈向上传播并被运行时捕获，运行时随后通知图保存当前状态并等待外部输入。 当执行恢复时（在你提供了所请求的输入之后），运行时会把整个节点从头重新启动——它不会从调用 \u00000\u0000 的那一行继续。这意味着在 \u00001\u0000 之前运行过的代码都会再次执行。因此，在使用中断时有一些重要规则需要遵循，以确保它们按预期表现。"},{"h":"不要在 try/except 中包裹 interrupt 调用#","id":"不要在-tryexcept-中包裹-interrupt-调用","t":"\u00000\u0000 在调用点暂停执行的方式是抛出一个特殊异常。如果你把 \u00001\u0000 调用包裹在 try/except 块中，你就会捕获到这个异常，中断就不会被传回图。 ✅ 把 \u00000\u0000 调用与容易出错的代码分开 ✅ 在 try/except 块中使用具体的异常类型 Separating Explicit python 复制 python 复制 🔴 不要把 \u00000\u0000 调用包裹在裸露的 try/except 块中 python 复制"},{"h":"不要调整节点内 interrupt 调用的顺序#","id":"不要调整节点内-interrupt-调用的顺序","t":"在单个节点中使用多个中断很常见，但如果处理不当，这可能导致意外的行为。 当一个节点包含多个中断调用时，LangGraph 会为该节点所执行的任务保存一份专门的恢复值列表。每当执行恢复时，它都会从节点头部开始。对于遇到的每个中断，LangGraph 会检查任务的恢复列表中是否存在匹配的值。匹配是 严格基于索引的 ，因此节点内中断调用的顺序很重要。 ✅ 在节点的多次执行之间保持 \u00000\u0000 调用一致 python 复制 🔴 不要在节点内有条件地跳过 \u00000\u0000 调用 🔴 不要使用在多次执行之间不确定的逻辑来循环 \u00000\u0000 调用，"},{"h":"不要在 interrupt 调用中返回复杂值#","id":"不要在-interrupt-调用中返回复杂值","t":"取决于所使用的检查点存储，复杂值可能无法序列化（例如你无法序列化一个函数）。为了让你的图能够适配任何部署环境，最佳实践是只使用可以合理序列化的值。 ✅ 向 \u00000\u0000 传递简单的、可 JSON 序列化的类型 ✅ 传递包含简单值的字典/对象 Simple Structured python 复制 python 复制 🔴 不要向 \u00000\u0000 传递函数、类实例或其他复杂对象 Functions Class python 复制 python 复制"},{"h":"在 interrupt 之前调用的副作用必须是幂等的#","id":"在-interrupt-之前调用的副作用必须是幂等的","t":"由于中断的工作方式是在调用它们的节点上重新运行，所以在 \u00000\u0000 之前调用的副作用应当（最好是）幂等。作为背景，幂等意味着同一操作可以多次应用，而不会在首次执行之外改变结果。 举个例子，你可能在节点内有一次用于更新记录的 API 调用。如果在这次调用之后调用了 \u00000\u0000 ，那么当节点恢复时，该调用会被重新运行多次，可能会覆盖最初的更新或创建重复记录。 ✅ 在 \u00000\u0000 之前使用幂等操作 ✅ 把副作用放在 \u00000\u0000 调用之后 ✅ 在可能的情况下把副作用拆分到独立的节点中 在下面这些审批后的示例中，副作用只在审批成功时才运行。"},{"h":"以函数方式调用子图时的使用#","id":"以函数方式调用子图时的使用","t":"在节点内调用子图时，父图会从调用子图并触发 \u00000\u0000 的 节点开头 处恢复执行。同样， 子图 也会从调用 \u00001\u0000 的节点开头处恢复执行。 python 复制"},{"h":"使用中断进行调试#","id":"使用中断进行调试","t":"为了调试和测试图，你可以将静态中断用作断点，从而逐个节点地步进执行图。静态中断会在节点执行之前或之后的指定位置触发。你可以在编译图时通过指定 interrupt_before 和 interrupt_after 来设置这些中断。 ℹ 注意 静态中断 不 推荐用于人在回路工作流。请改用 \u00000\u0000 函数。 编译时 运行时 python 复制 断点在 compile 期间设置。 interrupt_before 指定在节点执行之前应暂停执行的节点。 interrupt_after 指定在节点执行之后应暂停执行的节点。 需要"},{"h":"使用 LangSmith Studio#","id":"使用-langsmith-studio","t":"你可以在运行图之前，使用 LangSmith Studio 在 UI 中为图设置静态中断。你也可以使用该 UI 在执行过程中的任意时刻检查图状态。 通过 MCP 将 这些文档 连接到你所选择的智能体，以获取实时答案。 在 GitHub 上 编辑此页面 或 提交 issue 。"}]},{"slug":"use-time-travel","url":"use-time-travel.html","title":"使用时间旅行","group":"核心能力","sections":[{"h":"概述#","id":"概述","t":"LangGraph 通过 检查点 支持时间旅行： 重放 ：从先前的检查点重试。 分叉 ：从先前的检查点分叉并修改状态，以探索替代路径。 两种方式都通过从先前的检查点恢复来实现。检查点之前的节点不会重新执行（结果已保存）。检查点之后的节点会重新执行，包括所有 LLM 调用、API 请求和 中断 （可能产生不同的结果）。"},{"h":"重放#","id":"重放","t":"使用先前检查点的 config 调用图，即可从该点重放。 ⚠ 警告 重放会重新执行节点——它并不只是从缓存中读取。LLM 调用、API 请求和 中断 会再次触发，并可能返回不同的结果。从最终检查点重放（没有 next 节点）不执行任何操作。 使用 \u00000\u0000 找到要重放的检查点，然后用该检查点的 config 调用 \u00001\u0000 ： python 复制"},{"h":"分叉#","id":"分叉","t":"分叉会从过去的检查点创建一个带有修改后状态的新分支。在先前的检查点上调用 \u00000\u0000 创建分叉，然后用 None 调用 \u00002\u0000 继续执行。 ⚠ 警告 update_state 不会 回滚线程。它会创建一个从指定点分叉的新检查点。原始执行历史保持完整。 python 复制"},{"h":"从指定节点分叉#","id":"从指定节点分叉","t":"调用 \u00000\u0000 时，值会使用指定节点的写入器（包括 归并函数 ）来应用。检查点会记录该节点产生了此更新，执行则从该节点的后继节点恢复。 默认情况下，LangGraph 从检查点的版本历史中推断 as_node 。当从特定检查点分叉时，这种推断几乎总是正确的。 在以下情况下需显式指定 as_node ： 并行分支 ：多个节点在同一步中更新了状态，而 LangGraph 无法确定哪个是最后一个（ InvalidUpdateError ）。 无执行历史 ：在新的线程上设置状态（常见于 测试 ）。 跳过节点 ：将 as_no"},{"h":"中断#","id":"中断","t":"如果你的图使用 \u00000\u0000 来支持 人在回路 工作流，那么在时间旅行期间中断总会被重新触发。包含该中断的节点会重新执行， interrupt() 会暂停以等待新的 Command(resume=...) 。 python 复制"},{"h":"多个中断#","id":"多个中断","t":"如果你的图在多个点收集输入（例如多步骤表单），你可以从两个中断之间分叉，从而修改后续的答案，而无需重新询问先前的问题。 python 复制"},{"h":"子图#","id":"子图","t":"对 子图 进行时间旅行取决于子图是否拥有自己的检查点器。这决定了你可以从何种粒度的检查点进行时间旅行。 继承的检查点器（默认） 子图检查点器 默认情况下，子图会继承父图的检查点器。父图会将整个子图视为 单个超步 ——整个子图的执行只有一个父图层级的检查点。从子图之前的位置进行时间旅行会从头重新执行该子图。 在默认子图中，你无法时间旅行到节点*之间*的某个位置——你只能从父图层级进行时间旅行。 python 复制 在子图上设置 checkpointer=True ，使其拥有自己的检查点历史。这会在子图 内部 的每个步"}]},{"slug":"add-memory","url":"add-memory.html","title":"记忆","group":"核心能力","sections":[{"h":"添加短期记忆#","id":"添加短期记忆","t":"短期 记忆（线程级 持久化 ）使智能体能够跟踪多轮对话。要添加短期记忆： python 复制"},{"h":"在生产环境中使用#","id":"在生产环境中使用","t":"在生产环境中，请使用由数据库支持的检查点保存器： python 复制 示例：使用 Postgres 检查点保存器 text 复制 💡 提示 首次使用 Postgres 检查点保存器时，需要调用 checkpointer.setup() 同步 异步 python 复制 python 复制 示例：使用 MongoDB 检查点保存器 text 复制 💡 提示 设置 要使用 MongoDB 检查点保存器 ，你需要一个 MongoDB 集群。如果还没有集群，请按照 本指南 创建一个。有关以智能体为中心的完整演练，请参阅 Mo"},{"h":"在子图中使用#","id":"在子图中使用","t":"如果你的图包含 子图 ，你只需在编译父图时提供检查点。LangGraph 会自动将检查点传播到子图。 python 复制 你还可以配置特定于子图的检查点行为。有关持久化级别（包括中断支持与有状态续接）的详细信息，请参阅 子图持久化 。 python 复制"},{"h":"添加长期记忆#","id":"添加长期记忆","t":"使用长期记忆在各对话之间存储用户特定或应用特定的数据。 python 复制"},{"h":"在节点内访问存储#","id":"在节点内访问存储","t":"使用存储编译图之后，LangGraph 会自动将存储注入到你的节点函数中。访问存储的推荐方式是通过 Runtime 对象。 python 复制"},{"h":"在生产环境中使用#","id":"在生产环境中使用-2","t":"在生产环境中，请使用由数据库支持的存储： python 复制 示例：使用 Postgres 存储 text 复制 💡 提示 首次使用 Postgres 存储时，需要调用 store.setup() 异步 同步 python 复制 python 复制 示例：使用 MongoDB 存储 text 复制 💡 提示 使用 query 进行语义搜索需要 MongoDB Vector Search（ $vectorSearch ），它可运行在 MongoDB Atlas 上，或运行在启用了 Search and Vector "},{"h":"使用语义搜索#","id":"使用语义搜索","t":"在图的内存存储中启用语义搜索，可让图智能体按语义相似度搜索存储中的条目。 python 复制 带语义搜索的长期记忆 python 复制"},{"h":"管理短期记忆#","id":"管理短期记忆","t":"启用 短期记忆 后，检查点会在同一线程内跨轮次持久化图状态。调用模型的节点控制将状态中的哪些数据纳入模型输入。持久化状态并不会自动将全部状态发送给模型。将过长的消息历史传给模型可能会超出其上下文窗口。常见解决方案包括： 裁剪消息 ：移除最前或最后 N 条消息（在调用 LLM 之前） 从 LangGraph 状态中永久 删除消息 汇总消息 ：对历史中较早的消息进行汇总，并用一条摘要替换它们 管理检查点 以存储和检索消息历史 自定义策略（例如消息过滤等） 这样可以让智能体持续跟踪对话，同时不超出 LLM 的上下文窗口。"},{"h":"裁剪消息#","id":"裁剪消息","t":"大多数 LLM 都有一个最大支持的上下文窗口（以 token 计）。决定何时截断消息的一种方法是：统计消息历史中的 token 数量，并在接近该上限时进行截断。如果你使用 LangChain，可以使用裁剪消息工具，并指定要从列表中保留的 token 数量，以及用于处理边界的 strategy （例如保留最后 max_tokens ）。 在下面的示例中，节点将裁剪后的消息列表传给模型，但不会从状态中删除消息。 要裁剪消息历史，请使用 \u00000\u0000 函数： python 复制 完整示例：裁剪消息 python 复制 text"},{"h":"删除消息#","id":"删除消息","t":"你可以从图状态中删除消息，以管理消息历史。当你想要删除特定消息或清空整个消息历史时，这很有用。 要从图状态中删除消息，可以使用 RemoveMessage 。要让 RemoveMessage 生效，你需要使用带有 \u00002\u0000 归并函数 的状态键，例如 \u00003\u0000 。 要删除特定消息： python 复制 要删除 所有 消息： python 复制 ⚠ 警告 删除消息时， 请确保 生成的消息历史是有效的。请查看你所用 LLM 提供方的限制。例如： 部分提供方要求消息历史以 user 消息开头 大多数提供方要求带有工具调用的 a"},{"h":"摘要消息#","id":"摘要消息","t":"如上所示，裁剪或删除消息的问题在于，你可能会因为清空消息队列而丢失信息。因此，一些应用受益于一种更精细的做法：使用聊天模型对消息历史进行摘要。 可以使用提示词和编排逻辑来对消息历史进行摘要。例如，在 LangGraph 中，你可以扩展 \u00000\u0000 以包含 summary 键： python 复制 然后，你可以生成聊天历史的摘要，并将任何已有的摘要作为下一次摘要的上下文。这个 summarize_conversation 节点可以在 messages 状态键中累积了一定数量的消息之后被调用。 python 复制 完整示例"},{"h":"管理检查点#","id":"管理检查点","t":"你可以查看和删除检查点保存器存储的信息。 查看线程状态 Graph/Functional API Checkpointer API python 复制 text 复制 python 复制 text 复制 查看线程的历史记录 Graph/Functional API 检查点 API python 复制 text 复制 python 复制 text 复制 删除某个线程的所有检查点 python 复制"},{"h":"数据库管理#","id":"数据库管理","t":"如果你使用任何基于数据库的持久化实现（例如 Postgres、Redis 或 Oracle）来存储短期和/或长期记忆，那么在与数据库配合使用之前，你需要运行迁移来设置所需的数据库模式。 按照惯例，大多数针对特定数据库的库都会在检查点或存储实例上定义 setup() 方法，用于运行所需的迁移。不过，你应当向你所使用的 \u00001\u0000 或 \u00002\u0000 实现确认确切的方法名与用法。 我们建议将迁移作为专门的部署步骤来运行，或者你也可以确保它们作为服务器启动的一部分来执行。 通过 MCP 将 这些文档 连接到你所选的智能体，以获取实时"}]},{"slug":"use-subgraphs","url":"use-subgraphs.html","title":"子图","group":"核心能力","sections":[{"h":"环境准备#","id":"环境准备","t":"pip uv bash 复制 bash 复制 💡 提示 为 LangGraph 开发配置 LangSmith 注册 LangSmith ，以快速发现问题并提升你的 LangGraph 项目性能。LangSmith 让你能够使用追踪数据来调试、测试和监控用 LangGraph 构建的 LLM 应用——阅读 如何开始使用 LangSmith 了解更多信息。"},{"h":"定义子图通信#","id":"定义子图通信","t":"添加子图时，需要定义父图与子图之间的通信方式： 模式 使用场景 状态 schema 在节点内调用子图 父图与子图具有 不同的状态 schema （没有共享键），或者你需要在两者之间转换状态 你需要编写一个包装函数，把父图状态映射为子图输入，并把子图输出映射回父图状态 将子图添加为节点 父图与子图 共享状态键 ——子图读写与父图相同的通道 你直接把编译好的子图传给 add_node ——无需包装函数"},{"h":"在节点内调用子图#","id":"在节点内调用子图","t":"当父图与子图具有 不同的状态 schema （没有共享键）时，在节点函数内部调用子图。当你想在 多智能体 系统中为每个智能体保留私有的消息历史时，这种做法很常见。 节点函数会在调用子图之前把父图状态转换为子图状态，并在返回之前把结果转换回父图状态。 python 复制 完整示例：不同的状态 schema python 复制 text 复制 完整示例：不同的状态 schema（两层子图） 这是一个包含两层子图的示例：父图 -> 子图 -> 孙图。 python 复制 text 复制"},{"h":"将子图添加为节点#","id":"将子图添加为节点","t":"当父图与子图 共享状态键 时，你可以把编译好的子图直接传给 add_node 。无需包装函数——子图会自动读写父图的状态通道。例如，在 多智能体 系统中，智能体通常通过共享的 messages 键通信。 如果你的子图与父图共享状态键，可以按照以下步骤把它添加到图中： 定义子图工作流（下例中的 subgraph_builder ）并编译它 在定义父图工作流时，把编译好的子图传给 \u00000\u0000 方法 python 复制 完整示例：共享状态 schema python 复制 text 复制"},{"h":"子图持久化#","id":"子图持久化","t":"当你使用子图时，需要决定其内部数据在调用之间如何处理。设想一个将任务委派给专家子智能体的客服机器人：「账单专家」子智能体应该记住客户先前的问题，还是在每次被调用时都从空白开始？ .compile() 上的 checkpointer 参数控制子图持久化： 模式 checkpointer= 行为 每次调用 None （默认） 每次调用都从空白开始，并继承父级的检查点，以支持单次调用内的 中断 和 持久执行 。 每线程 True 状态在同一线程的多次调用之间累积。每次调用都从上次中断处继续。 无状态 False 完全不进"},{"h":"有状态#","id":"有状态","t":"有状态子图会继承父图的检查点保存器，从而支持 中断 、 持久化 以及状态检查。两种有状态模式的区别在于状态保留的时长。 每次调用（默认） 💡 提示 对于大多数应用而言，这是推荐模式，包括将子智能体作为工具调用的 多智能体 系统。它支持 中断 、 持久化 和并行调用，同时保持每次调用相互隔离。 当对子图的每次调用彼此独立、且子智能体无需记住之前调用中的任何内容时，使用按调用持久化。这是最常见的模式，尤其适用于 多智能体 系统，其中子智能体处理诸如「查询该客户的订单」或「总结这份文档」之类的一次性请求。 省略 chec"},{"h":"无状态#","id":"无状态","t":"当你希望像普通函数调用一样运行子智能体、不承担检查点开销时，可以使用这种方式。子图无法暂停/恢复，也无法受益于 持久执行 。请使用 checkpointer=False 进行编译。 ⚠ 警告 没有检查点时，子图不具备持久执行能力。如果进程在运行中途崩溃，子图无法恢复，必须从头重新运行。 python 复制"},{"h":"检查点器参考#","id":"检查点器参考","t":"通过 .compile() 上的 checkpointer 参数控制子图的持久化： python 复制 特性 按调用（默认） 按线程 无状态 checkpointer= None True False 中断（HITL） ✅ ✅ ❌ 多轮记忆 ❌ ✅ ❌ 多次调用（不同子图） ✅ ⚠️（在同一节点内对多个按线程子图的调用可能导致命名空间冲突。有可用的变通方案。） ✅ 多次调用（同一子图） ✅ ❌ ✅ 状态查看 ⚠️（按调用持久化的状态查看仅适用于当前这次调用（在中断期间）。每次调用都从头开始，因此调用完成后没有累积的"},{"h":"查看子图状态#","id":"查看子图状态","t":"当你启用 持久化 后，可以使用 subgraphs 选项查看子图状态。使用 无状态 检查点（ checkpointer=False ）时，不会保存任何子图检查点，因此子图状态不可用。 ℹ 注意 查看子图状态要求 LangGraph 能够 静态发现 该子图——也就是说，它要么 作为节点添加 ，要么 在节点内调用 。如果在 工具 函数或其他间接调用中调用子图（例如 子智能体 模式），则不起作用。无论嵌套层级如何，中断仍然会传播到顶层图。 按调用 按线程 返回 仅当前这次调用 的子图状态。每次调用都从头开始。 pytho"},{"h":"流式输出子图输出#","id":"流式输出子图输出","t":"要观察嵌套图的执行过程，我们推荐使用 事件流式输出 ： stream.subgraphs 投影会发现每一次嵌套运行，并在无需解析命名空间字符串的情况下暴露其 path 、 messages 和 values 。 python 复制 如果你需要原始的协议事件，可以直接迭代该流，并基于 event[\"method\"] 和 event[\"params\"][\"namespace\"] 进行过滤： python 复制 从子图流式输出 python 复制 text 复制 通过 MCP 将 这些文档 连接到你选择的智能体，以获取实"}]},{"slug":"workflows-agents","url":"workflows-agents.html","title":"工作流与智能体","group":"模式","sections":[{"h":"环境设置#","id":"环境设置","t":"要构建工作流或智能体，你可以使用 任何支持结构化输出和工具调用的聊天模型 。以下示例使用 Anthropic： 安装依赖： bash 复制 初始化 LLM： python 复制"},{"h":"LLM 与增强#","id":"llm-与增强","t":"工作流和智能体系统基于 LLM 以及你为其添加的各种增强功能。 工具调用 、 结构化输出 和 短期记忆 是几种按需定制 LLM 的选项。 python 复制"},{"h":"提示词链#","id":"提示词链","t":"提示词链是指每次 LLM 调用都会处理上一次调用的输出。它通常用于执行可拆分为更小、可验证步骤的明确定义的任务。一些示例包括： 将文档翻译成不同语言 验证生成内容的一致性 Graph Functional python 复制 python 复制"},{"h":"并行化#","id":"并行化","t":"借助并行化，LLM 可以同时处理同一个任务。这可以通过同时运行多个相互独立的子任务来实现，也可以通过多次运行同一任务以检查不同的输出来实现。并行化通常用于： 拆分子任务并并行运行，从而提升速度 多次运行任务以检查不同的输出，从而提升置信度 一些示例包括： 运行一个子任务处理文档中的关键词，再运行第二个子任务检查格式错误 多次运行同一个任务，依据不同标准为文档的准确性打分，例如引用数量、使用的来源数量以及来源质量 Graph Functional python 复制 python 复制"},{"h":"路由#","id":"路由","t":"路由工作流会先处理输入，然后将其导向特定上下文的任务。这让你可以为复杂任务定义专门化的流程。例如，一个用于回答产品相关问题的工作流可能会先处理问题类型，然后将请求路由到针对定价、退款、退货等的具体流程。 Graph Functional python 复制 python 复制"},{"h":"编排器-工作者#","id":"编排器-工作者","t":"在编排器-工作者配置中，编排器会： 将任务拆解为子任务 将子任务委派给工作者 将工作者的输出综合为最终结果 编排器-工作者工作流提供了更高的灵活性，通常用于无法像 并行化 那样预先定义子任务的场景。这在编写代码或需要跨多个文件更新内容的工作流中很常见。例如，一个需要为多个 Python 库在数量未知的文档中更新安装说明的工作流，就可能采用这种模式。 Graph Functional python 复制 python 复制"},{"h":"在 LangGraph 中创建工作者#","id":"在-langgraph-中创建工作者","t":"编排器-工作者工作流非常常见，LangGraph 对其提供了内置支持。 Send API 让你可以动态创建工作节点，并向它们发送特定输入。每个工作者拥有自己的状态，所有工作者的输出都会写入一个共享的状态键，编排器图可以访问该键。这使得编排器能够获取全部工作者输出，并将它们综合为最终输出。下面的示例遍历一个章节列表，并使用 Send API 将每个章节发送给对应的工作者。 python 复制"},{"h":"评估器-优化器#","id":"评估器-优化器","t":"在评估器-优化器工作流中，一次 LLM 调用生成一个响应，另一次 LLM 调用对该响应进行评估。如果评估器或 人在回路 判定该响应需要改进，就会提供反馈并重新生成响应。该循环会持续进行，直到生成可接受的响应。 当任务有特定的成功标准、但需要反复迭代才能满足该标准时，通常会使用评估器-优化器工作流。例如，在两种语言之间翻译文本时并不总是存在完美匹配。可能需要经过几次迭代，才能生成在两种语言之间含义一致的译文。 Graph Functional python 复制 python 复制"},{"h":"智能体#","id":"智能体","t":"智能体通常被实现为使用 工具 执行动作的 LLM。它们在持续的反馈循环中运行，适用于问题与解决方案都不可预测的场景。相比工作流，智能体拥有更高的自主性，可以就使用哪些工具以及如何解决问题做出决策。你仍然可以定义可用的工具集，以及规范智能体行为的准则。 ℹ 注意 若要开始使用智能体，请参阅 快速入门 ，或在 LangChain 中进一步了解 它们的工作原理 。 Using Graph Functional python 复制 python 复制 python 复制"},{"h":"ToolNode#","id":"toolnode","t":"\u00000\u0000 是一个预构建节点，用于在 LangGraph 工作流中执行工具。它会自动处理并行工具执行、错误处理以及状态注入。 当你需要细粒度地控制图执行工具的方式时，请使用 \u00000\u0000 。这一构建块为许多 LangGraph 智能体模式中的工具执行提供了支撑。 python 复制 从工具访问图状态与上下文 由 ToolNode 执行的工具会将模型生成的参数作为第一个参数接收。若要读取并非由模型生成的图侧数据，请使用以下选项之一： 在 Python 中，从注入的 \u00000\u0000 参数中读取状态与运行作用域上下文。 在 JavaScr"}]},{"slug":"case-studies","url":"case-studies.html","title":"案例研究","group":"案例与实践","sections":[]},{"slug":"agentic-rag","url":"agentic-rag.html","title":"使用 LangGraph 构建自定义 RAG 智能体","group":"案例与实践","sections":[{"h":"概念#","id":"概念","t":"本教程涵盖以下概念： 使用以下组件进行 检索 文档加载器 ， 文本分割器 、 嵌入模型 ，以及 向量存储 LangGraph Graph API ，包括状态、节点、边和条件边。"},{"h":"环境准备#","id":"环境准备","t":"安装所需的软件包并设置你的 API 密钥： python 复制 python 复制"},{"h":"设置 LangSmith#","id":"设置-langsmith","t":"RAG 应用按顺序执行检索与生成。当你运行本教程中的示例时， LangSmith 会为每次查询记录一条追踪，方便你检查检索过程、工具调用和模型响应。 在 注册 LangSmith 之后，设置环境变量以开始记录追踪： shell 复制 或者，在 Python 中设置它们： python 复制 💡 提示 如果你正在构建生产级智能体，我们还建议你设置 LangSmith Engine ，它可以监控你的追踪、检测问题并提出修复方案。"},{"h":"预处理文档#","id":"预处理文档","t":"1. 抓取文档 使用 Lilian Weng 博客 中的三篇文章。通过一个基于 requests 和 BeautifulSoup 的最小辅助函数抓取页面内容。 python 复制 2. 分割文档 将抓取到的文档切分为更小的块，以便建立索引并存入向量存储： python 复制"},{"h":"创建检索工具#","id":"创建检索工具","t":"将分割后的文档建立索引并存入向量存储，以支持语义搜索。 1. 索引文档 使用内存向量存储和 OpenAI 嵌入模型： python 复制 2. 创建检索工具 使用 @tool 装饰器创建一个检索工具： python 复制 3. 测试该工具 python 复制"},{"h":"生成查询或作出回应#","id":"生成查询或作出回应","t":"检索工具就绪后，就可以开始把智能体构建为一个 LangGraph 图。在 Graph API 中，一个图由以下部分组成： 状态 ：节点读取和更新的共享数据。本教程使用 \u00000\u0000 ，它存储一个由 聊天消息 组成的 messages 列表。 节点 ：接收当前状态、执行一个步骤（例如调用模型或工具）并返回状态更新的函数。 边 ：定义下一个运行哪个节点的连接，包括根据状态进行分支的 条件边 。 第一个节点是智能体的决策点。基于迄今为止的对话，模型要么直接回答用户，要么在问题需要博客上下文时调用检索工具。正是这一选择使该系统具"},{"h":"文档评分#","id":"文档评分","t":"普通边始终把图发送到同一个下一个节点。而 条件边 会在运行时对当前状态执行一个函数，从而选择下一个节点。在检索之后，可以用这种模式来判断文档是否相关：如果相关，就继续生成答案；如果不相关，就改写问题并重试。 1. 添加文档评分 添加一个 grade_documents 路由函数，它使用带有结构化输出模式 GradeDocuments 的模型。该函数根据评分决定返回下一个节点的名称（ generate_answer 或 rewrite_question ）： python 复制 2. 用不相关的文档测试 在工具响应中"},{"h":"改写问题#","id":"改写问题","t":"如果评分器把检索到的文档标记为不相关，图就不应基于该上下文作答。此时应把原始用户问题改写为更清晰的搜索查询，然后把控制权交回 generate-query-or-respond 节点，让智能体重新检索。这个重试循环正是智能体从第一次检索不力中恢复的方式，而不是直接停止或臆造一个答案。 1. 构建改写节点 构建 rewrite_question 节点，在检索未命中时改进原始用户问题： python 复制 2. 试一试 python 复制 输出： text 复制"},{"h":"生成答案#","id":"生成答案","t":"当评分器接受检索到的文档时，图就进入答案生成阶段。这个节点是经典的 RAG 步骤：把原始用户问题与保存检索上下文的工具消息结合起来，然后让模型给出有依据的回复。提示词要保持紧凑，让模型基于所提供的上下文作答，而不是编造细节。 1. 构建答案节点 构建 generate_answer 节点，根据问题和检索到的上下文生成最终回复： python 复制 2. 试一试 python 复制 输出： text 复制"},{"h":"组装图#","id":"组装图","t":"将节点和边组装成一张完整的图： 从 generate_query_or_respond 开始，并决定是否调用 retriever_tool 。 根据模型是否发起工具调用，路由到下一个步骤： 如果 generate_query_or_respond 返回了 tool_calls ，则调用 retriever_tool 来检索上下文。 否则，直接响应用户。 评估检索到的文档内容与问题的相关性（ grade_documents ），并路由到下一个步骤： 如果不相关，则使用 rewrite_question 重写问题，然后"},{"h":"运行智能体式 RAG#","id":"运行智能体式-rag","t":"通过用一个问题运行完整图来测试它： python 复制"},{"h":"另请参阅#","id":"另请参阅","t":"检索 Graph API 智能体 构建 RAG 智能体 构建语义搜索引擎 将这些文档连接到 你选择的智能体，通过 MCP 获取实时答案。 在 GitHub 上编辑此页面 或 提交问题 。"}]},{"slug":"sql-agent","url":"sql-agent.html","title":"构建自定义 SQL 智能体","group":"案例与实践","sections":[{"h":"概念#","id":"概念","t":"我们将涵盖以下概念： 用于从 SQL 数据库读取数据的 工具 LangGraph Graph API ，包括状态、节点、边和条件边。 人在回路 流程"},{"h":"设置#","id":"设置","t":""},{"h":"安装#","id":"安装","t":"bash 复制"},{"h":"LangSmith#","id":"langsmith","t":"设置 LangSmith 以检查你的链或智能体内部正在发生的情况。然后设置以下环境变量： shell 复制"},{"h":"1. 选择一个 LLM#","id":"1.-选择一个-llm","t":"选择一个支持 工具调用 的模型： OpenAI Anthropic Azure Google Gemini AWS Bedrock HuggingFace OpenRouter 👉 阅读 OpenAI 聊天模型集成文档 pip uv init_chat_model Model bash 复制 bash 复制 python 复制 python 复制 👉 阅读 Anthropic 聊天模型集成文档 pip uv init_chat_model Model bash 复制 bash 复制 python 复制 python"},{"h":"2. 配置数据库#","id":"2.-配置数据库","t":"你将为本教程创建一个 SQLite 数据库 。SQLite 是一个轻量级数据库，便于安装和使用。我们将加载 chinook 数据库，这是一个代表数字媒体商店的示例数据库。 为方便起见，我们已将数据库（ Chinook.db ）托管在公共 GCS 存储桶上。 python 复制 我们将使用 Python 内置的 sqlite3 模块与数据库交互： python 复制 text 复制"},{"h":"3. 为数据库交互添加工具#","id":"3.-为数据库交互添加工具","t":"⚠ 警告 以下数据库工具仅是用于演示的最小封装。它们并不安全，也不适合在生产环境中使用。在执行模型生成的 SQL 之前，请使用范围受限的数据库权限，并添加针对具体应用的校验。 我们可以使用 langchain.tools 中的 @tool 装饰器，把数据库 工具 实现为轻量封装： python 复制 text 复制"},{"h":"4. 定义应用步骤#","id":"4.-定义应用步骤","t":"我们为以下步骤构建专用节点： 列出数据库表 调用「获取 schema」工具 生成查询 检查查询 将这些步骤放入专用节点，可以让我们 (1) 在需要时强制发起工具调用，(2) 自定义与每个步骤关联的提示词。 python 复制"},{"h":"5. 实现智能体#","id":"5.-实现智能体","t":"现在，我们可以使用 Graph API 将这些步骤组装成一个工作流。我们在查询生成步骤定义一条 条件边 ：如果生成了查询，则路由到查询检查器；如果没有工具调用，则结束，此时 LLM 已经给出了对该问题的回答。 python 复制 我们在下方可视化该应用： python 复制 我们现在可以调用该图： python 复制 text 复制 💡 提示 上述运行的 LangSmith 追踪 见此处。"},{"h":"6. 实现人在回路审查#","id":"6.-实现人在回路审查","t":"在执行智能体的 SQL 查询之前，先检查其中是否存在非预期的操作或低效之处，是较为稳妥的做法。 这里我们利用 LangGraph 的 人在回路 特性，在执行 SQL 查询之前暂停运行，并等待人工审查。借助 LangGraph 的 持久化层 ，我们可以无限期地暂停运行（或者至少只要持久化层仍然存活就可以）。 让我们把 sql_db_query 工具包装在一个接收人工输入的节点中。我们可以使用 interrupt 函数来实现这一点。在下面，我们允许输入以批准工具调用、编辑其参数，或提供用户反馈。 python 复制 ℹ"},{"h":"下一步#","id":"下一步","t":"请查阅 评估图 指南，了解如何使用 LangSmith 评估 LangGraph 应用，包括像这样的 SQL 智能体。 将这些文档 通过 MCP 连接到你所选的智能体，以获取实时答案。 在 GitHub 上编辑此页面 或 提交问题 。"}]},{"slug":"thinking-in-graph-api","url":"thinking-in-graph-api.html","title":"用 Graph API 思考","group":"使用 Graph API 构建","sections":[{"h":"从你想要自动化的流程开始#","id":"从你想要自动化的流程开始","t":"设想你需要构建一个处理客户支持邮件的 AI 智能体。你的产品团队给出了以下需求： txt 复制 要用 Graph API 实现一个智能体，本指南会向你展示五个步骤。步骤 1 和步骤 2 是规划阶段。步骤 3 到步骤 5 则把这份规划转化为状态、节点，以及一个可以运行的已编译图。"},{"h":"步骤 1：将工作流拆解为离散步骤#","id":"步骤-1将工作流拆解为离散步骤","t":"首先找出流程中彼此独立的步骤。每个步骤都会成为一个 节点 （一个只做一件特定事情的函数）。然后勾勒出这些步骤之间的连接关系。请在编写代码之前完成这一步。 实线箭头是固定边：你在构建图时就声明它们，因为下一个节点在运行之前就已确定。虚线箭头是在节点内部、于运行时通过 \u00000\u0000 选择的路径。 现在各组件已经识别出来，接下来明确每个节点需要做什么： Read Email ：提取并解析邮件内容 Classify Intent ：使用 LLM 对紧急程度和主题进行分类，然后路由到搜索、缺陷跟踪或起草回复 Doc Search "},{"h":"步骤 2：确定每个步骤需要做什么#","id":"步骤-2确定每个步骤需要做什么","t":"对于步骤 1 中的每个节点，判断它属于哪类工作，以及需要哪些上下文。使用下面的分类，然后展开邮件智能体的示例，查看具体字段和重试选择。 LLM 步骤 当你需要理解、分析、生成文本或做出推理判断时使用 数据步骤 当你需要从外部来源检索信息时使用 操作步骤 当你需要执行外部操作时使用 用户输入步骤 当你需要人工介入时使用"},{"h":"LLM 步骤#","id":"llm-步骤","t":"当某个步骤需要理解、分析、生成文本或做出推理判断时： 分类意图 静态上下文（提示词）：分类类别、紧急程度定义、回复格式 动态上下文（来自状态）：邮件内容、发件人信息 期望结果：决定路由的结构化分类结果 起草回复 静态上下文（提示词）：语气规范、公司政策、回复模板 动态上下文（来自状态）：分类结果、搜索结果 期望结果：可供审核的专业邮件回复"},{"h":"数据步骤#","id":"数据步骤","t":"当某个步骤需要从外部来源检索信息时： 文档搜索 参数：根据意图和主题构建的查询 重试策略：有，针对瞬时故障使用指数退避 缓存：可以缓存常见查询以减少 API 调用"},{"h":"操作步骤#","id":"操作步骤","t":"当某个步骤需要执行外部操作时： 发送回复 执行时机：审批之后（人工或自动） 重试策略：有，针对网络问题使用指数退避 不应缓存：每次发送都是唯一的操作 缺陷跟踪 执行时机：只要意图为 \"bug\" 就执行 重试策略：有，确保不丢失缺陷报告至关重要 返回值：工单 ID，用于包含在回复中"},{"h":"用户输入步骤#","id":"用户输入步骤","t":"当某个步骤需要人工介入时： 人工审核 决策上下文：原始邮件、回复草稿、紧急程度、分类结果 期望输入格式：审批布尔值，以及可选的修改后回复 触发时机：高紧急程度、账单问题或复杂问题 被拒绝时：结束运行且不发送（由人工在图之外处理该邮件）"},{"h":"步骤 3：设计你的状态#","id":"步骤-3设计你的状态","t":"状态是智能体中所有节点都可访问的共享 记忆 。可以把它想象成智能体的笔记本，用来记录它在整个流程中了解到和决定的一切。"},{"h":"状态里应该放什么？#","id":"状态里应该放什么","t":"针对每一份数据，问自己这些问题： 放入状态 它需要在多个步骤之间持久保留吗？如果需要，就放入状态。 不要存储 你能从其他数据推导出它吗？如果能，就在需要时计算，而不是存入状态。 对于邮件智能体，需要记录： 原始邮件和发件人信息（之后无法重建） 分类结果（后续节点需要） 搜索结果或工单上下文（重新获取的代价较高） 回复草稿（需要在审核过程中保留） 执行元数据（用于调试和恢复）"},{"h":"保持状态原始，按需格式化提示词#","id":"保持状态原始按需格式化提示词","t":"💡 提示 在状态中存储原始数据，而不是格式化后的提示词文本。在节点内部需要时再格式化提示词。 这种分离意味着： 不同节点可以用不同方式格式化同一份数据 你可以修改提示词模板而不必改动状态模式 调试时能看到每个节点实际收到的数据，而不是一个预先拼好的提示词字符串 现在定义状态。后续步骤中的节点会使用这些字段。 python 复制"},{"h":"第 4 步：构建节点#","id":"第-4-步构建节点","t":"节点是一个 Python 函数，它接收当前状态并返回对状态的更新。当节点还要选择下一步时，返回 \u00000\u0000 。"},{"h":"妥善处理错误#","id":"妥善处理错误","t":"在填充节点主体之前，先想清楚每个节点可能如何失败。为调用外部 API 的节点附加重试策略。使用 interrupt() 获取人工输入。可以把下表当作指南： 错误类型 由谁修复 策略 使用场景 瞬时错误（网络问题、速率限制） 系统（自动） 节点上的重试策略 通常在重试后即可解决的临时失败 LLM 可恢复的错误（工具失败、解析问题） LLM 将错误存入状态并路由回去 模型可以借助更多上下文进行调整 用户可修复的错误（信息缺失、指令不清晰） 人 用 interrupt() 暂停 需要用户输入才能继续 重试之后仍可恢复的失"},{"h":"实现邮件智能体节点#","id":"实现邮件智能体节点","t":"把每一项工作都变成一个节点。每个节点读取共享状态，完成一项工作，然后返回更新。当下一步取决于结果时，返回一个同时包含更新和目标位置的 Command 。人工审核同样是一个节点：它在函数内部调用 interrupt() ，而不是一个独立的图原语。 下面的桩代码展示了邮件智能体的函数签名、状态更新与路由。把占位的主体替换为真实的 LLM 调用和 API 集成。请把这些节点放在第 3 步的状态所在的同一个文件中。 在本演练中， read_email 是一个直通节点。即便如此，把它保留为独立节点仍然能让你在分类之前获得一个"},{"h":"第 5 步：把它们连接起来#","id":"第-5-步把它们连接起来","t":"把节点连接成一张图。由于路由逻辑位于 Command 节点内部，你只需要少量固定边。使用 检查点保存器 进行编译，这是 interrupt() 能够暂停和恢复的前提。 python 复制 返回 Command[Literal[...]] 的 Python 节点会在类型提示中声明其目标节点。LangGraph 据此得知哪些边是有效的。"},{"h":"试用你的智能体#","id":"试用你的智能体","t":"图编译完成后，用一封示例邮件调用它。使用上面的占位分类器时，这封紧急的账单邮件会被判定为高紧急度，因此本次运行会起草回复、触发 interrupt() ，你可以借此练习恢复。首次调用和恢复调用要使用同一个 thread_id 。 python 复制 图在 interrupt() 处暂停，将状态保存到检查点保存器并等待。当你用 Command(resume=...) 恢复时， human_review 节点会从头重新运行， interrupt() 返回你的恢复值，图继续执行。 thread_id 把这轮对话的状态维系"},{"h":"总结与下一步#","id":"总结与下一步","t":""},{"h":"关键要点#","id":"关键要点","t":"构建这个邮件智能体的过程，展示了 Graph API 的思考方式： 拆分为离散的步骤 每个节点只把一件事做好。节点边界正是图执行检查点的位置，因此失败与恢复时重复的工作更少。 状态即共享内存 存储原始数据，而不是格式化后的文本。不同节点可以以不同方式使用同一份信息。 节点即函数 它们接收状态、执行工作，并返回更新。当它们进行路由时，会通过 Command 同时返回更新和下一个目的地。 错误是流程的一部分 瞬时失败会应用节点重试策略，用户可修复的问题通过 interrupt() 暂停，意料之外的错误则会让本次运行失败"},{"h":"节点粒度的取舍#","id":"节点粒度的取舍","t":"大多数应用都可以采用上面的拆分方式。当你正在决定要合并还是拆分节点时，请阅读本节。 LangGraph 在 节点 边界处创建检查点。当运行在中断或失败之后恢复时，它会从执行停止所在节点的开头重新开始。节点越小，检查点越频繁，需要重复的工作也越少。 为什么这种拆分方式适合该邮件智能体： 外部服务的隔离： Doc Search 和 Bug Track 是独立节点，因此重试只作用于这些 API 调用。 可见性： 分类是它自己的节点，因此你可以在执行下一步操作之前检查结构化结果。 不同的失败模式： LLM 调用、查询和邮件"},{"h":"接下来去哪里#","id":"接下来去哪里","t":"本演练介绍了 Graph API 的设计思路。你可以借助操作指南和相关教程进一步扩展： 构建检查清单 关于状态、控制流、Send、Command 和节点的决策指南 定义并更新状态 Schema、归并函数、消息和私有通道 控制流 顺序、分支、循环和递归限制 Send 与 Command 一步完成 map-reduce 扇出与更新并路由 配置节点 重试、超时、运行时上下文和缓存 以 Functional API 的方式思考 用入口点和任务实现同一个邮件智能体 人在回路模式 工具审批、批量审批以及其他中断模式 添加记忆 "}]},{"slug":"use-graph-api","url":"use-graph-api.html","title":"Graph API 构建清单","group":"使用 Graph API 构建","sections":[{"h":"构建图#","id":"构建图","t":"请按顺序处理这些决策。每个步骤都包含一个简短示例，并链接到完整操作指南。 1. 定义共享状态 确定节点之间共享哪些数据，以及更新如何合并。 选择一种 schema（ TypedDict 、dataclass，或在 TypeScript 中使用 StateSchema ）。 为多个节点写入的键添加 归并函数 （例如追加消息）。 当图需要向调用方隐藏内部通道时，使用私有 schema 或输入/输出 schema。 python 复制 这里 foo 会被覆盖。 bar 通过 operator.add 追加。 有关 sch"},{"h":"后续步骤#","id":"后续步骤","t":"用 Graph API 思考 ：使用电子邮件智能体的设计讲解 Graph API 概览 ：状态、节点、边、 Send 和 Command 的概念 定义和更新状态 构建顺序、分支和循环 使用 Send 和 Command 配置节点 可视化你的图 LangGraph 快速入门 ：端到端计算器智能体 在 Graph API 与 Functional API 之间选择 通过 MCP 连接这些文档 到你选择的智能体，以获取实时答案。 在 GitHub 上 编辑此页面 或 提交 issue 。"}]},{"slug":"graph-api","url":"graph-api.html","title":"Graph API 概览","group":"使用 Graph API 构建","sections":[{"h":"图#","id":"图","t":"LangGraph 将智能体工作流建模为由三部分构成的图： \u00000\u0000 ：应用的共享快照。通常是带类型的 schema。 \u00000\u0000 ：读取状态、执行工作并返回更新的函数。 \u00000\u0000 ：决定下一个节点的固定或条件式转移。 组合节点和边可构建序列、分支和循环。节点和边都是普通函数。它们可以调用 LLM 或运行其他代码。 简而言之：节点负责执行工作；边决定接下来运行什么。"},{"h":"超步#","id":"超步","t":"LangGraph 以 消息传递 的方式运行图，风格上类似 Google 的 Pregel 系统。执行以离散的 超步 推进： 并行运行的节点共享同一个超步。 顺序运行的节点使用不同的超步。 当节点在入边上收到输入时，该节点变为活跃。 一个超步结束后，没有待处理消息的节点变为非活跃。 当所有节点都非活跃且没有消息仍在传输时，运行结束。"},{"h":"StateGraph#","id":"stategraph","t":"\u00000\u0000 是主要的图构建器。用你的状态 schema 为其参数化。"},{"h":"编译图#","id":"编译图","t":"先定义 状态 ，添加 节点 和 边 ，然后编译，即可构建一个图。编译会检查图结构（例如是否存在孤立节点）。编译阶段也是你附加运行时选项（如 检查点保存器 和断点）的地方。 必须先编译图，然后才能调用或流式输出。下面是端到端的最小示例： python 复制"},{"h":"状态#","id":"状态","t":"状态是节点读取和更新的共享数据。LangGraph 将这些数据存储在 通道 中：状态 schema 中的具名槽位（即状态对象的键）。每个通道持有一个值，并定义更新如何合并进去。大多数通道采用最后写入胜出。带 归并函数 的通道则改为组合值，例如追加到列表。 状态包含两部分： 声明图中通道的 schema 控制更新如何合并到各个通道的可选 归并函数 节点返回部分更新。LangGraph 通过每个通道的归并函数应用这些更新。 使用 \u00000\u0000 、 \u00001\u0000 （用于默认值），或在需要校验时使用 Pydantic \u00002\u0000 来定义状"},{"h":"Schema#","id":"schema","t":"默认情况下，图的输入和输出 schema 与完整状态一致。当某些键仅限内部使用时，可以收窄它们。参见 定义输入和输出 schema 。 多个 schema 大多数图共用一个状态 schema。当你需要以下任一项时，请使用多个 schema： 由内部节点共享、但不属于图输入或输出的私有通道 作为完整内部状态子集的显式输入和输出 schema 节点可以写入图状态中的任何通道，包括其声明的输入 schema 之外的通道。节点在定义这些 schema 时也可以引入私有通道。输入和输出 schema 约束的是 invoke "},{"h":"归并函数#","id":"归并函数","t":"归并函数控制节点更新如何合并到状态中。每个键都有自己的归并函数。没有归并函数时，更新会覆盖先前的值。 归并函数参数 归并函数是一个二元函数： 左 ：该键当前在状态中的值 右 ：节点返回的该键更新 python 复制 定义一个归并函数，并用 Annotated 将其附加到某个状态键上： python 复制 用左值和右值调用该归并函数，即可看出值如何组合： python 复制 默认归并函数 默认归并函数用右值替换左值。节点返回的是部分更新，而不是完整状态。 例如，初始为 {\"foo\": 1, \"bar\": [\"hi\"]"},{"h":"在图状态中使用消息#","id":"在图状态中使用消息","t":"为什么要使用消息？ 聊天模型以消息列表作为输入。LangChain 的 聊天模型接口 接受 \u00000\u0000 和 \u00001\u0000 等消息对象。参见 消息概念指南 。 在图中使用消息 将对话历史作为消息列表存储在状态中，并使用一个归并函数来追加新消息、按 ID 更新已有消息。 在 messages 键上使用 \u00001\u0000 。裸用 operator.add 只会追加，因此无法在人在回路编辑过程中就地更新已有消息。 python 复制 序列化 消息归并函数还会将常见的线格式反序列化为 LangChain 消息对象。 python 复制 使用点号"},{"h":"节点#","id":"节点","t":"节点是同步或异步函数，用于实现图中的一个步骤。 节点可以接受： state ：图的 状态 config ：一个 \u00001\u0000 ，包含 thread_id 、 tags 等值 runtime ：一个 Runtime 对象，包含 运行时上下文 、 store 、 stream_writer 、 execution_info 及相关辅助工具 使用 \u00000\u0000 添加节点： python 复制 在底层，LangGraph 会将函数包装为 \u00000\u0000 ，使它们获得批处理、异步支持以及 追踪 能力。 如果省略节点名称，LangGraph 会使"},{"h":"重新执行与幂等性#","id":"重新执行与幂等性","t":"使用 检查点保存器 时，LangGraph 会在 超步 边界处保存检查点，而不是在节点内部的函数执行中途保存。在 中断 或 重试 之后，受影响的节点会从其函数的开头重新执行。暂停之前的副作用会再次执行。 设计节点逻辑时应确保重新执行是安全的。优先使用幂等键、upsert 或写前读检查。关于重试下的持久键与外部副作用，参见 重试边界与幂等性 。关于 interrupt() 周围的副作用，参见 在 \u00001\u0000 之前调用的副作用必须是幂等的 。 你可以在不破坏现有线程恢复的前提下添加或移除节点和边。恢复的运行会使用已保存的状"},{"h":"选择工作单元#","id":"选择工作单元","t":"节点 是检查点与重试的边界。它也是图可以走向不同路径的地方。确定性工作，例如解析、检索或固定的工具链，不需要单独的节点，除非你需要那样一个边界。 先问这一步是决定接下来发生什么，还是执行已经决定的事情。然后选择与你所需恢复行为相匹配的原语： 原语 自有检查点 恢复或重试时 选择时机 节点内的普通函数 否。它在该节点的 超步 内运行。 只要节点重新运行，它就会重新运行。 该步骤之后没有路由分叉，并且随节点其余部分一起重复执行是可以接受的。 任务 不产生新的图检查点。结果随正在运行的入口点或父检查点一起存储。 外层入口"},{"h":"在节点中使用任务#","id":"在节点中使用任务","t":"当一个节点运行多个需要独立保存检查点的操作时，将每个操作包装为 任务 ，而不是把工作拆分到多个节点中。使用检查点保存器时，已完成的任务结果会被保存，因此恢复的线程可以跳过节点内已完成的工作。关于模式与示例，参见 任务 和 常见陷阱 。"},{"h":"START 节点#","id":"start-节点","t":"\u00000\u0000 是将用户输入传入图的虚拟入口。用它来标记哪些节点先运行。 python 复制"},{"h":"END 节点#","id":"end-节点","t":"END 标记终止边。当某条路径应当停止时使用它。 python 复制"},{"h":"节点缓存#","id":"节点缓存","t":"LangGraph 可以按输入缓存节点（和任务）的结果。在编译图时传入缓存，并在节点上附加 \u00000\u0000 。 关于选项、端到端示例以及图级默认值，参见 添加节点缓存 。"},{"h":"边#","id":"边","t":"边决定控制权接下来走向哪里： 普通边 ：总是从一个节点走到下一个节点 条件边 ：调用一个函数来确定下一个（些）节点 入口点 ：用户输入后的第一个节点（ START → 节点） 条件入口点 ：用函数从 START 进行路由 一个节点可以有多个出边。这些边上的目标会在下一个超步中并行运行。 ⚠ 警告 对每个节点，要么使用静态边，要么使用动态路由（ 条件边 / \u00000\u0000 ），不要同时使用两者。混用可能导致两条路径都运行。"},{"h":"普通边#","id":"普通边","t":"如果你总是想从节点 A 走到节点 B，请使用 \u00000\u0000 ： python 复制"},{"h":"条件边#","id":"条件边","t":"如果你想可选地路由到一个或多个节点（或终止），请使用 \u00000\u0000 。传入源节点以及在该节点运行后要调用的路由函数： python 复制 路由函数接收当前图状态。默认情况下，其返回值是下一个节点的名称（或名称列表）。这些节点会在下一个超步中并行运行。你也可以传入一个字典，将函数的输出映射到节点名称。 路由函数可以返回节点名称、 END 、名称列表（扇出），或用于 map-reduce 的 \u00001\u0000 对象。参见 构建序列、分支与循环 。 💡 提示 当你想在单个函数中合并状态更新与路由时，请使用 \u00000\u0000 而不是条件边。"},{"h":"入口点#","id":"入口点","t":"入口点是图启动时最先运行的一个（或多个）节点。从虚拟 \u00000\u0000 节点添加一条边，指向要执行的第一个节点： python 复制"},{"h":"条件入口点#","id":"条件入口点","t":"条件入口点让你根据自定义逻辑从不同的节点开始。使用来自 \u00000\u0000 的 \u00001\u0000 ： python 复制 你还可以选择性地提供一个字典，将路由函数的输出映射到下一个节点名称。"},{"h":"Send#","id":"send","t":"当你需要对每个条目各运行一次同一个节点、且每个条目都有各自的输入，并且条目数量只有在运行时才能确定时，使用 \u00000\u0000 。这种形态通常称为 map-reduce 或 orchestrator-worker：一个节点生成列表，各个 worker 并行处理每个条目，之后由另一个节点读取合并后的结果。 普通边无法做到这一点。它们决定接下来运行哪些节点，但每个被选中的节点仍然接收共享的图状态，而且拓扑在你构建图时就已经固定。 从条件边返回一个或多个 Send 对象。每个 Send 指定一个目标节点，并传入一个自定义参数作为该次"},{"h":"Command#","id":"command","t":"当单个步骤必须既更新状态又决定接下来运行什么时，使用 \u00000\u0000 。通常这两件事是分开的：节点返回状态更新，由 边 （或 条件边 ）决定下一个节点。当下一跳取决于你在同一个函数中刚刚完成的工作时，从节点返回 Command 。 Command 还覆盖了普通返回值和边无法处理的另外两种情形：在 中断 之后恢复运行，以及从 工具 内部更新或路由。 仅用于路由时，优先使用条件边。当你需要同时完成更新与路由（或属于上述中断 / 工具情形之一）时，才使用 Command 。 Command 接受以下字段： update ：状态更"},{"h":"Return from nodes#","id":"return-from-nodes","t":"update 与 goto 返回 \u00000\u0000 以在一个步骤中同时更新状态并路由： python 复制 用允许的目标节点标注返回类型，例如 Command[Literal[\"my_other_node\"]] 。这会告诉 LangGraph 应渲染哪些边。 当你需要同时完成更新与路由时，使用 \u00000\u0000 。仅用于路由时，优先使用 条件边 。 ⚠ 警告 Command 会增加动态边。来自同一节点的静态边仍会运行。不要将 Command 路由与同一节点上的 add_edge 混用。 参见 用 Command 结合控制流与状态更新 "},{"h":"Input to invoke or stream#","id":"input-to-invoke-or-stream","t":"⚠ 警告 Command(resume=...) 是唯一可作为 invoke() / stream() 输入的 Command 模式（恢复时可选择附带 update=... ）。不要只传 Command(update=...) 来继续对话。任何作为输入的 Command 都会从最新的检查点恢复，而不是从 START 开始，因此一个已结束的线程看上去可能像卡住了。要开启新一轮，请传入普通 dict： python 复制 resume 在 中断 之后使用 Command(resume=...) 。该值会成为被暂停的 i"},{"h":"Return from tools#","id":"return-from-tools","t":"从工具中返回 \u00000\u0000 ，以便在工具执行完毕后更新状态并路由。从工具中 goto 会增加一条动态边。调用节点上的静态边仍会运行，因此不要将两者混用。 参见 在工具内部使用 。"},{"h":"Graph migrations#","id":"graph-migrations","t":"即使 检查点保存器 已经存储了线程状态，你仍可以更改图的节点、边和状态 schema。哪些改动是安全的，取决于该线程是已结束还是已暂停。 拓扑（节点与边） 已结束的线程（未中断）：你可以自由添加、删除或重命名节点和边。 已中断的线程：你可以更改边并添加节点。不要重命名或删除该线程即将进入的节点。恢复运行时，LangGraph 会按名称查找该节点，名称缺失会导致运行失败。 状态 Schema 添加或删除键是向后和向前兼容的。 重命名键会丢弃现有线程中该键已保存的值。 对现有键进行不兼容的类型变更（例如收窄类型，或将旧"},{"h":"Runtime context#","id":"runtime-context","t":"运行时上下文将依赖项传入节点，而无需把它们放进图状态（例如模型名称或数据库句柄）。 python 复制 参见 添加运行时配置 。"},{"h":"Recursion limit#","id":"recursion-limit","t":"递归上限限制一次运行可以执行多少个 超步 。超过该上限时，LangGraph 会抛出 GraphRecursionError 。 从 1.1.4 版本开始，默认值为 10,007 个超步。在 1.0.6 到 1.1.3 之间，默认值为 10,000 步。可通过 LANGGRAPH_DEFAULT_RECURSION_LIMIT 环境变量覆盖，或将 recursion_limit 作为顶层配置键传入（不要放在 configurable 下）。 关于具体做法（捕获该错误、读取 langgraph_step ，以及 Py"},{"h":"Learn more#","id":"learn-more","t":"从 Graph API 的角度思考 LangGraph 快速入门 Graph API 构建清单 定义并更新状态 构建序列、分支和循环 使用 Send 与 Command 配置节点 可视化你的图 Functional API 概览 将这些文档接入 你选择的智能体，通过 MCP 获得实时回答。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"graph-api-state","url":"graph-api-state.html","title":"定义和更新状态","group":"使用 Graph API 构建","sections":[{"h":"定义状态#","id":"定义状态","t":"LangGraph 中的 State 可以是 TypedDict 、 Pydantic 模型或 dataclass。下面的示例使用 TypedDict 。大多数图都优先使用这种形式；当你需要对输入进行运行时校验时，参见 使用 Pydantic 模型作为图状态 。 默认情况下，图对输入和输出使用相同的 schema，而状态决定了该 schema。若要使用不同的输入和输出 schema，参见 定义输入和输出 schema 。 从一个 messages 字段开始。这种形态适合许多 LLM 应用。更多细节，参见 在图状态中"},{"h":"更新状态#","id":"更新状态","t":"构建一个只包含单个 节点 的图。节点是一个 Python 函数，它读取图状态并返回更新。第一个参数始终是状态： python 复制 该节点通过在返回值中拼接来追加一条消息（还没有归并函数），并设置 extra_field 。 ⚠ 警告 节点应直接返回对状态的更新，而不是原地修改状态。 用这个节点定义一个简单的图。使用 \u00000\u0000 来构建处理该状态的图，然后用 \u00001\u0000 填充图： python 复制 LangGraph 提供了用于可视化图的内置工具。详情参见 可视化你的图 。 python 复制 mermaid 复制 该图"},{"h":"使用归并函数处理状态更新#","id":"使用归并函数处理状态更新","t":"状态中的每个键都可以有自己的 归并函数 ，它控制来自节点的更新如何被应用。如果未指定归并函数，对该键的更新会替换之前的值。 对于 TypedDict 状态 schema，通过用归并函数标注字段来定义归并函数。 在前面的示例中，节点通过返回完整的拼接列表来更新 \"messages\" 。添加一个归并函数，使更新自动追加： python 复制 此后节点只需返回新消息： python 复制 python 复制 text 复制"},{"h":"MessagesState#","id":"messagesstate","t":"在实践中，消息列表需要的不仅仅是简单的拼接： 按 ID 更新状态中已有的消息。 接受简写的 消息格式 ，例如 {\"role\": \"user\", \"content\": \"...\"} 。 LangGraph 包含一个内置归并函数 \u00000\u0000 ，它可以处理这些情况： python 复制 python 复制 text 复制 这种形态适合使用 聊天模型 的应用。为方便起见，可以继承预置的 MessagesState ： python 复制"},{"h":"重置归并函数字段#","id":"重置归并函数字段","t":"使用归并函数时一个常见的困惑来源是：对于合并型归并函数，返回空值并不会清空该字段。归并函数会把右侧参数合并进左侧参数，因此空更新会被合并进去，之前累积的值会被保留。 这个模式对于必须在重试尝试之间清空的错误缓冲区或重试计数器很重要： python 复制 要在保留合并型归并函数的同时清空字段，用 \u00000\u0000 包裹更新： python 复制 更多信息，参见 使用 Overwrite 绕过归并函数 。"},{"h":"使用 Overwrite 绕过归并函数#","id":"使用-overwrite-绕过归并函数","t":"在某些情况下，你可能希望绕过归并函数，直接覆盖状态值。当节点返回一个用 Overwrite 包裹的值时，归并函数会被绕过，通道会直接设置为该值。 当你想要重置或替换累积的状态，而不是将其与现有值合并时，这很有用。 LangGraph 为此提供了 \u00000\u0000 类型。 python 复制 text 复制 你也可以使用带有特殊键 \"__overwrite__\" 的 JSON 格式： python 复制 ⚠ 警告 当节点并行执行时，在同一个超步中，只有一个节点能对同一个状态键使用 Overwrite 。如果多个节点在同一个超步"},{"h":"定义输入和输出 schema#","id":"定义输入和输出-schema","t":"默认情况下， StateGraph 使用单个 schema 运行，所有节点都使用该 schema 进行通信。你也可以定义不同的输入和输出 schema。 当指定了不同的 schema 时，节点之间的通信仍然使用一个内部 schema。输入 schema 会校验传入的输入。输出 schema 会过滤内部数据，因此 invoke 只返回输出 schema 中的字段。 定义不同的输入和输出 schema： python 复制 text 复制 请注意， invoke 的输出只包含输出 schema。"},{"h":"在节点之间传递私有状态#","id":"在节点之间传递私有状态","t":"节点有时需要一些中间数据，这些数据不应出现在图的主输入或输出 schema 中。请将这些数据保持私有，只让需要它的节点读取。 下面的顺序图包含三个节点。私有数据在前两步之间传递。第三步只能看到公开的整体状态。 python 复制 text 复制"},{"h":"私有通道与流式输出#","id":"私有通道与流式输出","t":"输入、输出和私有 schema 约束了每个节点读取的内容以及 invoke 返回的内容。它们 不会 对流式输出隐藏通道。 值流式输出默认会发出 所有 状态通道，包括私有通道。这适用于 事件流式输出 中的 values 投影（在 version=\"v3\" 时， stream_events / streamEvents 上的 stream.values ），也适用于使用 stream_mode=\"values\" / streamMode: \"values\" 的 graph.stream 。值流式输出使用的是完整状态，而"},{"h":"使用 Pydantic 模型作为图状态#","id":"使用-pydantic-模型作为图状态","t":"StateGraph 接受一个 \u00000\u0000 参数，用于指定节点可访问和更新的状态结构。 本页大多数示例使用 Python 原生的 TypedDict 或 \u00001\u0000 作为 state_schema 。 \u00003\u0000 可以是任意 类型 。 当需要对 输入 进行运行时校验时，可以使用 Pydantic BaseModel 作为 \u00000\u0000 。 ℹ 注意 已知限制 图的输出 不是 Pydantic 模型的实例。 运行时校验只发生在图中第一个节点的输入上，不会作用于后续节点或输出。 Pydantic 的校验错误堆栈不会指出错误发生在哪个节点"},{"h":"另请参阅#","id":"另请参阅","t":"Graph API 概览 在图状态中使用消息 事件流式输出 流式输出 使用 Graph API 将这些文档接入 你的智能体，通过 MCP 获取实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"graph-api-control-flow","url":"graph-api-control-flow.html","title":"构建序列、分支与循环","group":"使用 Graph API 构建","sections":[{"h":"创建步骤序列#","id":"创建步骤序列","t":"ℹ 注意 前提条件 本指南假定你熟悉 定义和更新状态 。 本节展示如何构建顺序图。Python 还提供了用于同一模式的 add_sequence 简写。 mermaid 复制 在 StateGraph 上使用 \u00000\u0000 和 \u00001\u0000 添加节点序列： python 复制 或者使用内置简写 .add_sequence ： python 复制 为什么要使用 LangGraph 将应用步骤拆分为序列？ LangGraph 可以在图的下方添加持久化层。状态会在节点之间生成检查点，因此这些节点决定了： 如何对状态更新 创建检查点 "},{"h":"创建分支#","id":"创建分支","t":"并行节点执行可以加快图的运行速度。LangGraph 通过标准边和 conditional\\_edges 实现扇出与扇入。以下示例构建分支数据流。关于面向动态目标的 map-reduce 扇出，参见 使用 Send 和 Command 。"},{"h":"并行运行图节点#","id":"并行运行图节点","t":"此示例从 Node A 扇出到 B 和 C ，再扇入到 D 。状态使用 归并函数 ，使该键的值不断累积而不是被覆盖。对于列表而言，这意味着把新列表拼接到现有列表上。参见 使用归并函数处理状态更新 。 mermaid 复制 python 复制 使用归并函数后，可以看到每个节点中添加的值都被累积起来。 python 复制 text 复制 ℹ 注意 在上面的示例中，节点 \"b\" 和 \"c\" 在同一个 超步 中并发执行。由于它们处于同一步，节点 \"d\" 会在 \"b\" 和 \"c\" 都完成后才执行。 重要的是，来自并行超步的更"},{"h":"延迟节点执行#","id":"延迟节点执行","t":"延迟节点执行会把某个节点推迟到所有其他待处理任务完成之后。当各分支长度不同时这一点很重要，而这在 map-reduce 工作流中很常见。 上面的并行示例在每条路径都是一步时进行扇出和扇入。在 \"b\" 分支上添加一个节点 \"b_2\" ，使各路径长度不相等。节点 d 使用 defer ，因此它会等待更长的分支： mermaid 复制 python 复制 python 复制 text 复制 节点 \"b\" 和 \"c\" 在同一个超步中并发运行。节点 d 上的 defer=True 使其在所有待处理任务完成之前不会运行，因此 "},{"h":"条件分支#","id":"条件分支","t":"在运行时根据状态路由到不同节点。节点 a 更新状态，然后条件边选择 b 或 c ： mermaid 复制 虚线边表示条件路由。 如果你的扇出需要在运行时根据状态变化，可以使用 \u00000\u0000 基于图状态选择一条或多条路径。参见下面的示例，其中节点 a 生成的状态更新决定了下一个节点。 python 复制 python 复制 text 复制 💡 提示 条件边可以路由到多个目标节点。例如： python 复制"},{"h":"创建并控制循环#","id":"创建并控制循环","t":"循环需要一种停止的方式。常见模式是使用 条件边 ，在满足终止条件时路由到 END 。 你也可以在调用或流式输出时设置递归限制。该限制是 LangGraph 抛出错误之前允许的 超步 数量。参见 递归限制概念 。 以下示例使用一个简单的循环图。节点 a 要么继续到 b （ b 又返回 a ），要么退出： mermaid 复制 虚线边是条件路由。 💡 提示 要在触及限制后捕获 GraphRecursionError ，参见 设置递归限制 。要在触及限制前路由到完成路径，参见 使用 RemainingSteps 处理递归"},{"h":"设置递归限制#","id":"设置递归限制","t":"当无法保证终止条件时，请设置图的 递归限制 。LangGraph 在达到相应数量的 超步 后会抛出 GraphRecursionError 。请捕获并处理该异常： python 复制 text 复制 扩展示例：带分支的循环 一个更复杂的循环会在某一步扇出到两个节点： mermaid 复制 虚线边是从 a 出发的条件路由。 python 复制 这个图是由 超步 组成的循环：先节点 A，再节点 B，然后节点 C 和 D 并发执行，之后回到 A。列表形式的边会等待 \"c\" 和 \"d\" 都完成后才返回 \"a\" 。关于列表形"},{"h":"访问并处理递归计数器#","id":"访问并处理递归计数器","t":"节点可以从运行元数据中读取当前步骤。利用这一点在触及限制前做出反应。 python 复制 使用 RemainingSteps 处理递归 RemainingSteps 是仅 Python 支持的托管值，表示距离递归限制还剩多少步。使用它可以在 LangGraph 抛出 GraphRecursionError 之前路由到完成路径： python 复制 在图内部使用 RemainingSteps 处理限制，或在图外部捕获 GraphRecursionError ： 方式 检测时机 处理位置 控制流 主动方式（ Remai"},{"h":"异步#","id":"异步","t":"当 IO 密集型 工作可以并发运行时，异步会很有帮助。要将同步图转换为异步图： 使用 async def 而不是 def 定义节点。 在这些节点内部对异步调用使用 await 。 使用 .ainvoke 或 .astream 进行调用。 许多 LangChain 对象都实现了 Runnable 协议，该协议提供了同步方法的异步变体。异步流式输出示例请参阅 流式输出指南 。"},{"h":"另请参阅#","id":"另请参阅","t":"Graph API 概览 使用 Send 和 Command 配置节点 可视化你的图 流式输出 将这些文档连接 到你所选择的智能体，通过 MCP 获取实时答案。 在 GitHub 上编辑此页面 或 提交问题 。"}]},{"slug":"graph-api-send-command","url":"graph-api-send-command.html","title":"使用 Send 与 Command","group":"使用 Graph API 构建","sections":[{"h":"使用 Send 实现 map-reduce#","id":"使用-send-实现-map-reduce","t":"从 条件边 返回一个或多个 Send 对象。每个 Send 指定一个目标节点，并传递该次调用的输入。LangGraph 会并行运行这些调用。当多个工作节点写入同一个状态键时，请使用 归并函数 ，以便更新能够合并（例如拼接列表）。 下面的工作节点不会收到完整的图状态。 Send 会把 { \"subject\": ... } 作为该次运行的输入传递，因此工作节点的 schema 中包含 subject ，尽管整体状态中并没有它。 python 复制 python 复制 mermaid 复制 虚线表示 Send 的扇出：每"},{"h":"使用 Command 组合控制流与状态更新#","id":"使用-command-组合控制流与状态更新","t":"当某个步骤既要更新状态、又要决定接下来运行什么时，从节点中返回 Command 。如果只做路由，优先使用 条件边 。 Command 返回值的形态如下（完整图见下文）： python 复制 下面的端到端示例使用三个节点：A，然后是 B 或 C。节点 A 更新状态并通过 Command 选择下一个节点，因此图中 A、B、C 之间没有条件边。 python 复制 构建 \u00000\u0000 。控制流位于 node_a 中，因此 A、B、C 之间没有 条件边 。 python 复制 ⚠ 警告 请将返回类型标注为带可能目标节点的 \u00000\u0000"},{"h":"导航到父图中的节点#","id":"导航到父图中的节点","t":"在 子图 内的节点中，使用 graph=Command.PARENT 路由到父图中的节点： python 复制 下面的示例将节点 A 变成单节点子图，并将其添加到仍包含 B 和 C 的父图中。 ⚠ 警告 使用 Command.PARENT 时的状态更新 当子图节点更新一个同时存在于父图和子图 状态 schema 中的键时，需要在父图上为该键定义 归并函数 。参见下面的示例。 python 复制 python 复制 text 复制"},{"h":"在工具中使用#","id":"在工具中使用","t":"在工具中返回 Command(update=...) ，以便在一轮对话中写入图状态（例如客户查询结果）。下面的代码片段假设存在 get_user_info / getUserInfo 以及名为 messages 的消息历史键。请在你的应用中补全导入和辅助函数。 python 复制 ⚠ 警告 从工具返回 \u00000\u0000 时，请在 Command.update 中包含 messages （或任何存放消息历史的状态键），并且该列表必须包含 ToolMessage 。LLM 提供商要求带有工具调用的 AI 消息之后必须跟工具结果消"},{"h":"中断后恢复#","id":"中断后恢复","t":"仅当需要在 中断 后恢复时，才将 Command 作为 invoke / stream 的输入（ resume=... ，恢复时可选择性地带上 update ）。不要为了继续对话而单独传入 Command(update=...) ：任何作为输入的 Command 都会从最新的检查点恢复，而不是从 START 开始。要开始新一轮对话，请传入普通的状态更新。 完整的反模式示例见 invoke 或 stream 的输入 。中断相关模式见 中断 。"},{"h":"另请参阅#","id":"另请参阅","t":"Graph API 概览中的 Send 和 Command 中断 控制流 使用子图 配置节点 通过 MCP 将 这些文档 连接到你所选的智能体，以获取实时答案。 在 GitHub 上 编辑此页面 ，或 提交 issue 。"}]},{"slug":"graph-api-nodes","url":"graph-api-nodes.html","title":"配置节点","group":"使用 Graph API 构建","sections":[{"h":"添加运行时配置#","id":"添加运行时配置","t":"把值传入一次运行（例如使用哪个 LLM 或系统提示词），而无需把这些值放进图状态。 添加运行时配置的步骤： 为配置指定 schema 把配置添加到节点或条件边的函数签名中 把配置传入图 下面是一个简单的示例： python 复制 text 复制 扩展示例：在运行时指定 LLM 在调用时选择 OpenAI 或 Anthropic。这些示例会调用真实的提供商，需要 API 密钥。 python 复制 text 复制 扩展示例：在运行时指定模型和系统消息 在调用时同时配置模型提供商和系统消息。这些示例会调用真实的提供商，"},{"h":"添加重试策略#","id":"添加重试策略","t":"当节点调用可能发生瞬时失败的 API、数据库或 LLM 时，请附加重试策略。 把 retry_policy 传给 \u00001\u0000 。该值是一个 RetryPolicy 命名元组。下面的示例使用默认值： python 复制 默认情况下， retry_on 使用 default_retry_on ，它会重试除以下异常之外的任何异常： ValueError TypeError ArithmeticError ImportError LookupError NameError SyntaxError RuntimeError Re"},{"h":"设置节点超时#","id":"设置节点超时","t":"ℹ 注意 需要 langgraph>=1.2 。 把 timeout 传给 \u00001\u0000 ，以限制单次异步节点尝试可以运行多长时间。可以使用数字（秒）、 datetime.timedelta ，或用于分别设置运行限制和空闲限制的 \u00003\u0000 ： python 复制 节点超时仅适用于 async 节点。在同步节点上设置 timeout 会在编译时失败，因为同步 Python 执行无法在进程内被安全取消。若要分别设置运行限制和空闲限制，请传入 \u00001\u0000 。 当节点超过其超时时，LangGraph 会抛出 \u00000\u0000 。它 不 是内置 "},{"h":"处理节点错误#","id":"处理节点错误","t":"ℹ 注意 需要 langgraph>=1.2 。 把 error_handler 传给 \u00001\u0000 ，即可在节点失败且所有重试均告耗尽后运行一个函数。处理函数会接收当前状态和一个带类型的 \u00002\u0000 ，并可以通过 \u00003\u0000 路由到恢复分支： python 复制 完整的可运行示例、补偿模式以及 Command 路由，请参阅 容错 。"},{"h":"设置图级别的节点默认值#","id":"设置图级别的节点默认值","t":"ℹ 注意 需要 langgraph>=1.2 。 使用 \u00000\u0000 可以为图中的每个节点一次性设置 retry_policy 、 timeout 、 cache_policy 或 error_handler ，而不必在每次调用 \u00005\u0000 时重复设置。节点级的值始终优先，默认值在 \u00006\u0000 时应用： python 复制 retry_policy 和 timeout 默认值适用于每个节点，包括错误处理节点。 cache_policy 和 error_handler 默认值仅适用于常规节点——处理函数永远不会捕获自身，并且缓存处"},{"h":"在节点内访问执行信息#","id":"在节点内访问执行信息","t":"通过 runtime.execution_info 访问执行身份和重试信息。它会呈现线程、运行和检查点标识符以及重试状态，无需直接从 config 读取。 属性 类型 描述 thread_id str | None 当前执行的线程 ID。没有检查点时，为 None 。 run_id str | None 当前运行的运行 ID。未在 config 中提供时，为 None 。 checkpoint_id str 当前执行的检查点 ID。 checkpoint_ns str 当前执行的检查点命名空间。 task_id s"},{"h":"在节点内访问服务器信息#","id":"在节点内访问服务器信息","t":"当你的图运行在 LangGraph Server 上时，可以通过 runtime.server_info 访问服务器特有的元数据。它会呈现 assistant ID、graph ID 和已认证用户，无需直接读取 config 元数据或可配置键。 属性 类型 描述 assistant_id str 当前部署的 assistant ID。 graph_id str 当前部署的 graph ID。 user BaseUser | None 已认证的用户（如果配置了 自定义认证 ）。 python 复制 当图未运行在 La"},{"h":"在节点内访问排空状态#","id":"在节点内访问排空状态","t":"当请求了 优雅关闭 时， runtime.drain_requested 为 True 。在节点内读取该值，可以在下一个超步边界之前跳过开销较大的工作： python 复制 属性 类型 描述 drain_requested bool 如果已针对本次运行调用 RunControl.request_drain() ，则为 True 。 drain_reason str | None 传给 request_drain() 的原因字符串；如果未请求排空，则为 None 。 ℹ 注意 需要 langgraph>=1.2 。完"},{"h":"添加节点缓存#","id":"添加节点缓存","t":"当某个步骤开销较大，且你希望针对相同输入复用结果时，可以使用节点缓存。 启用缓存： 在编译图时传入一个缓存（例如 InMemoryCache ）。Python 中还提供 SqliteCache 。 在节点上附加 \u00000\u0000 。 \u00000\u0000 选项： key_func ：根据节点输入构建缓存键的函数。默认使用输入（通过 pickle）的哈希值。 ttl ：生存时间，单位为秒。省略时，缓存条目不会过期。 python 复制 由于模拟的工作负载，第一次运行大约需要两秒。第二次运行会从缓存返回。 你也可以使用 \u00000\u0000 为图一次性设置"},{"h":"另请参阅#","id":"另请参阅","t":"Graph API 控制流 容错 定义和更新状态 将这些文档连接 到你所选的智能体，通过 MCP 获取实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"graph-api-visualize","url":"graph-api-visualize.html","title":"可视化你的图","group":"使用 Graph API 构建","sections":[{"h":"Mermaid#","id":"mermaid","t":"在可绘制的图上调用 draw_mermaid() 即可得到 Mermaid 语法。将该字符串粘贴到任意 Mermaid 渲染器中，或保留在文档和 PR 中。 python 复制 text 复制"},{"h":"PNG#","id":"png","t":"可以通过以下三种方式之一，将同一个图渲染为 .png ： Mermaid.ink API（默认；无需额外安装包） Mermaid + Pyppeteer（ pip install pyppeteer ） Graphviz（ pip install pygraphviz ，另外还需要系统的 Graphviz 二进制文件） 使用 Mermaid.ink 默认情况下， draw_mermaid_png() 使用 Mermaid.ink API 生成图表。 python 复制 使用 Mermaid + Pyppeteer "},{"h":"另请参阅#","id":"另请参阅","t":"Graph API 概览 使用 Graph API LangSmith Studio 运行本地服务器 通过 MCP 将 这些文档 连接到你所选的智能体，以获取实时回答。 在 GitHub 上 编辑此页面 或 提交 issue 。"}]},{"slug":"thinking-in-functional-api","url":"thinking-in-functional-api.html","title":"使用 Functional API 进行思考","group":"使用 Functional API 构建","sections":[{"h":"从你想要自动化的流程开始#","id":"从你想要自动化的流程开始","t":"假设你需要构建一个处理客户支持邮件的 AI 智能体。你的产品团队给出了以下需求： txt 复制 要使用 Functional API 实现智能体，请遵循以下五个步骤。步骤 1 和步骤 2 是规划。步骤 3 到步骤 5 将这份计划转化为可运行的类型、任务和入口点。"},{"h":"步骤 1：将工作流拆解为离散步骤#","id":"步骤-1将工作流拆解为离散步骤","t":"首先识别流程中各个不同的步骤。每个步骤都会成为一个 任务 （执行某一特定功能的函数）。然后勾勒出入口点如何调用这些任务以及如何分支。在编写代码之前完成这一步。 该草图与入口点相对应：左侧是顺序调用和 if / else ，右侧是人工审核。Graph API 会将相同的路径编码为节点和边。 现在组件已经确定，请明确每个步骤需要做什么： Read Email ：提取并解析邮件内容 Classify Intent ：使用 LLM 对紧急程度和主题进行分类 Doc Search ：查询知识库以获取相关信息 Bug Trac"},{"h":"步骤 2：确定每个步骤需要做什么#","id":"步骤-2确定每个步骤需要做什么","t":"对于步骤 1 中的每个步骤，判断它属于哪类工作以及需要哪些输入。使用下面的分类，然后展开邮件智能体示例以了解具体字段和重试选择。 LLM 步骤 当你需要理解、分析、生成文本或做出推理决策时使用 数据步骤 当你需要从外部来源检索信息时使用 操作步骤 当你需要执行外部操作时使用 用户输入步骤 当你需要人工介入时使用"},{"h":"LLM 步骤#","id":"llm-步骤","t":"当一个步骤需要理解、分析、生成文本或做出推理决策时： 分类意图 静态上下文（提示词）：分类类别、紧急程度定义、响应格式 动态上下文（参数）：邮件内容、发件人信息 期望结果：驱动后续分支的结构化分类 起草回复 静态上下文（提示词）：语气指南、公司政策、回复模板 动态上下文（参数）：分类结果、搜索结果 期望结果：可供审核的专业邮件回复"},{"h":"数据步骤#","id":"数据步骤","t":"当一个步骤需要从外部来源检索信息时： 文档搜索 参数：根据意图和主题构建的查询 重试策略：是，对暂时性故障采用指数退避 缓存：可以缓存常见查询以减少 API 调用"},{"h":"操作步骤#","id":"操作步骤","t":"当一个步骤需要执行外部操作时： 发送回复 执行时机：审批之后（人工或自动） 重试策略：是，针对网络问题采用指数退避 不应缓存：每次发送都是唯一的操作 缺陷跟踪 执行时机：当意图为 \"bug\" 时总是执行 重试策略：是，不丢失缺陷报告至关重要 返回：要包含在回复中的工单 ID"},{"h":"用户输入步骤#","id":"用户输入步骤","t":"当一个步骤需要人工介入时： 人工审核 决策所需上下文：原始邮件、草稿回复、紧急程度、分类 预期输入格式：审批布尔值加上可选的编辑后回复 触发时机：高紧急程度、复杂问题或质量疑虑"},{"h":"步骤 3：决定任务之间传递哪些数据#","id":"步骤-3决定任务之间传递哪些数据","t":"在 Functional API 中，没有共享的图状态模式。每个任务接收参数并返回一个值。入口点将中间结果保存在局部变量中，并传递给下一个任务。 针对每一份数据，问自己以下问题： 在任务之间共享 后续任务是否需要这个值？如果需要，从创建它的任务中 返回 该值，将其存储在入口点的局部变量中，然后作为参数 传递 给需要它的任务。 保留在单个任务内部 它是否只用于在一个任务内部格式化提示词或发起调用？如果是，请将其保留在该任务本地。不要返回它。 对于邮件智能体，入口点需要携带： 原始邮件和发件人信息（工作流的输入） 分类"},{"h":"步骤 4：构建你的任务#","id":"步骤-4构建你的任务","t":"把步骤 1 中的每个工作单元变成一个任务。任务会独立地写入检查点、在失败时重试，并返回入口点可以等待的值。 \u00000\u0000 是一个 Python 函数，它完成一个工作单元并返回结果。在入口点中调用它，并用 .result() 解析结果（或在异步入口点中 await ）。"},{"h":"恰当地处理错误#","id":"恰当地处理错误","t":"在填写任务主体之前，先考虑每个任务可能如何失败。为瞬时错误在任务上附加重试。在入口点中使用 interrupt() 获取人工输入。以下表作为指引： 错误类型 由谁修复 策略 何时使用 瞬时错误（网络问题、速率限制） 系统（自动） 任务上的重试策略 通常在重试后即可解决的临时失败 LLM 可恢复的错误（工具失败、解析问题） LLM 返回错误，并在入口点中分支或重试 模型可以借助更多上下文自行调整 用户可修复的错误（信息缺失、指令不清） 人 用 interrupt() 暂停 需要用户输入才能继续 意外错误 开发者 让本"},{"h":"实现邮件智能体任务#","id":"实现邮件智能体任务","t":"为步骤 1 中的每个步骤添加一个任务（人工审核除外，它在步骤 5 中通过入口点里的 interrupt() 实现）。下面的桩函数展示了邮件智能体的函数签名、返回结构和重试策略。用真实的 LLM 调用和 API 集成替换占位的函数体。把这些任务与步骤 3 中的类型放在同一个文件里。 这里的 read_email 是一个透传任务。即便如此，把它保留为独立任务仍能在分类之前获得一个检查点，并留出一个后续添加真实 MIME 解析的位置。 python 复制 现在你有了可调用的任务。接下来，在入口点中把它们组合起来。"},{"h":"步骤 5：组合入口点#","id":"步骤-5组合入口点","t":"入口点就是工作流。把它添加在任务下方。它会按顺序调用这些任务，用 if / else 进行分支（即步骤 1 中的控制流），并用 interrupt() 为人工暂停。当你需要持久执行和人在回路时，请提供 检查点保存器 。 python 复制"},{"h":"试用你的智能体#","id":"试用你的智能体","t":"入口点定义好之后，用一封示例邮件调用它。使用上面占位版的分类器时，这封紧急的账单邮件会被判定为高紧急程度，因此本次运行会命中 interrupt() ，你可以练习恢复。首次调用和恢复调用要使用相同的 thread_id 。 python 复制 工作流在 interrupt() 处暂停，把已完成任务的结果保存到检查点保存器，然后等待。当你用 Command(resume=...) 恢复时，已完成的任务会从检查点重新加载，而不是重新运行。 thread_id 把这轮对话的状态维系在一起。"},{"h":"总结与后续步骤#","id":"总结与后续步骤","t":""},{"h":"关键要点#","id":"关键要点","t":"构建这个邮件智能体展示了 Functional API 的思维方式： 拆分为独立的任务 每个任务只做好一件事。任务边界是结果写入检查点的地方，因此失败和恢复时需要重做的工作更少。 传递值，而不是共享图状态 从任务返回原始数据，并将其作为参数传递。把提示词格式化留在需要它的任务内部。 入口点掌控控制流 使用 if / else 、循环和调用。你无需声明边或条件边映射。 错误是流程的一部分 瞬时故障交给任务重试策略，用户可修复的问题通过 interrupt() 暂停，意外错误则使本次运行失败。 人类输入是一等公民 in"},{"h":"任务粒度的权衡#","id":"任务粒度的权衡","t":"大多数应用都可以采用上述拆分方式。当你需要决定合并还是拆分任务时，请阅读本节。 LangGraph 会在入口点内部的 任务 边界处设置检查点。当一次运行在中断或失败后恢复时，已完成任务的结果会从检查点加载。位于任务之外、直接写在入口点主体中的工作可能会重新执行。 为什么这种拆分适合这个邮件智能体： 隔离外部服务： 文档搜索和缺陷跟踪是各自独立的任务，因此重试和失败都被限制在这些 API 调用范围内。 可见性： 分类是独立任务，因此你可以在分支之前检查结构化结果。 不同的失败模式： LLM 调用、数据库查询和邮件发送"},{"h":"接下来去哪里#","id":"接下来去哪里","t":"本演练介绍了 Functional API 的设计方式。你可以进一步拓展： 构建清单 关于工作流、任务、流式输出、中断和记忆的决策指南 以 Graph API 的思维思考 用节点、边和共享状态实现的同一个邮件智能体 组合工作流 并行任务、调用图以及嵌套入口点 配置任务 重试、超时、缓存以及出错后恢复 人在回路 用于审批和工具审查的中断模式 添加记忆 短期检查点器与长期存储 通过 MCP 将 这些文档 接入你选择的智能体，以获取实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"use-functional-api","url":"use-functional-api.html","title":"Functional API 构建清单","group":"使用 Functional API 构建","sections":[{"h":"构建你的工作流#","id":"构建你的工作流","t":"请按顺序逐项处理这些决策。每个步骤都链接到对应的操作指南，其中包含完整做法。 1. 组合工作流 定义一个入口点，将工作单元封装为任务，并选择各步骤之间的连接方式。 从单个入口点开始，并将输入作为单个参数传入（通常是 dict）。 对于需要独立检查点和重试的离散工作，使用任务。 当各步骤相互独立时，使用并行任务进行扇出。 需要组合时，调用已编译的 Graph API 图或另一个入口点。 参见 组合 Functional API 工作流 。 2. 配置任务 当步骤可能失败、挂起或重复时，添加可靠性控制。 针对瞬时失败的"},{"h":"下一步#","id":"下一步","t":"Functional API 设计思路 Functional API 概览 组合 Functional API 工作流 配置 Functional API 任务 使用 Functional API 进行流式输出 使用 Functional API 添加人在回路 使用 Functional API 添加记忆 LangGraph 快速开始 在 Graph API 与 Functional API 之间选择 通过 MCP 将这些文档接入 你所选的智能体，以获取实时解答。 在 GitHub 上编辑此页面 或 提交 issu"}]},{"slug":"functional-api","url":"functional-api.html","title":"Functional API 概述","group":"使用 Functional API 构建","sections":[{"h":"Functional API 与 Graph API#","id":"functional-api-与-graph-api","t":"如果你已经选择了 Functional API，本节比较可以跳过。关于并排对比的决策指南，参见 在 Graph API 与 Functional API 之间做选择 。两个 API 共享同一底层运行时，因此你可以在同一个应用中将它们结合使用。 高层差异： 控制流 ：Functional API 使用标准的语言结构。 Graph API 使用节点和边。 状态 ：Graph API 需要声明 状态 ，并且通常需要 归并函数 。Functional API 将状态限制在函数作用域内：任务通过返回值传递值，没有共享的状态模"},{"h":"入口点#","id":"入口点","t":"@entrypoint 装饰器由函数创建工作流。它负责管理长时间运行的工作和 中断 。"},{"h":"定义#","id":"定义","t":"当你需要持久化或人在回路时，传入 检查点保存器 。在配置中用 thread_id 标识每次运行。线程是一个会话或一次工作流运行的持久标识。 入口点 是被 @entrypoint 装饰的函数。 该函数 必须接受单个位置参数 作为工作流输入。要传递多个值，请使用字典（或类似结构）作为该参数。 装饰该函数会生成一个工作流对象（一个 \u00000\u0000 实例）。调用 invoke 或 ainvoke 来运行它。 同步 异步 python 复制 python 复制 ⚠ 警告 序列化 配置了检查点保存器时，入口点的 输入 和 输出 必须可"},{"h":"运行与恢复#","id":"运行与恢复","t":"调用 invoke 或 ainvoke 获取最终结果。关于流式输出，参见 使用 Functional API 进行流式输出 。 在 \u00000\u0000 之后，通过在 \u00001\u0000 中传入恢复值来恢复。关于具体做法，参见 为 Functional API 添加人在回路 。 出现错误后，用 None 恢复同一个 thread_id 。参见 错误后的恢复 。"},{"h":"短期记忆#","id":"短期记忆","t":"当 entrypoint 配置了 checkpointer 时，同一 线程 id 上的连续调用会将状态存入 检查点 。 添加一个仅限关键字的 previous 参数。LangGraph 会将其设置为该线程上最后保存的值。首次运行时它是 None 。要为下一次运行保存不同的值，请使用 \u00002\u0000 。参见 返回不同的保存值 。 关于累积和检查检查点，参见 在线程上保存状态 。"},{"h":"可注入参数#","id":"可注入参数","t":"在添加 记忆 或 自定义流式输出 之前，你可以跳过这一节。 声明 entrypoint 时，你可以请求 LangGraph 在运行时注入的额外参数： 参数 描述 previous 同一线程上一次调用的返回值（需要检查点保存器）。参见 短期记忆 。 config 一个 \u00000\u0000 对象，包含运行时配置值。 store 一个 \u00000\u0000 实例，用于 长期记忆 。也可通过 runtime.store 获取。 writer 一个 StreamWriter ，用于自定义流式输出。也可通过 runtime.stream_writer "},{"h":"任务#","id":"任务","t":"任务 是离散的工作单元（例如，一次 API 调用或一个数据步骤）。任务有两个关键属性： 并发执行 ：调用任务会立即启动它。只有当你等待结果时，入口点才会阻塞，因此独立的任务可以重叠执行。 检查点 ：任务结果会被保存，以便恢复时能够还原它们。参见 持久化 。"},{"h":"定义#","id":"定义-2","t":"使用 @task 装饰器定义任务： python 复制 ⚠ 警告 序列化 ：任务的 输出 必须是 JSON 可序列化的，以支持检查点。"},{"h":"执行#","id":"执行","t":"只能从 入口点 、另一个 任务 或 Graph API 节点 中调用 任务 。不要在位于工作流之外的应用程序代码中调用它们。 调用任务会立即返回一个 future。使用 .result() （同步）或 await （异步）来获取结果。 同步 异步 python 复制 python 复制"},{"h":"何时使用任务#","id":"何时使用任务","t":"在以下情况下使用 任务 ： 检查点 ：保存长时间运行的结果，使恢复时不会重新计算它。 人在回路 ：将暂停后不应重做的工作（例如 LLM 调用）包装在任务中。在 中断 后恢复会还原该结果。有关随机性，参见 确定性 。 并行执行 ：并发运行独立的 I/O 密集型工作。 可观测性 ：在 LangSmith 中跟踪离散步骤。 重试 ：对离散的工作单元应用重试策略。参见 配置 Functional API 任务 。"},{"h":"恢复与检查点#","id":"恢复与检查点","t":"恢复重放取决于序列化、确定性和幂等性。"},{"h":"序列化#","id":"序列化","t":"配置检查点器时适用两条规则： entrypoint 的输入和输出必须是 JSON 可序列化的。 task 的输出必须是 JSON 可序列化的。 使用 Python 基本类型，例如字典、列表、字符串、数字和布尔值。 序列化使任务结果和中间值能够为人在回路、容错和并行执行而恢复。配置检查点器时，不可序列化的值会引发运行时错误。"},{"h":"确定性#","id":"确定性","t":"恢复 不会 从执行停止的确切行继续。执行会返回到检查点边界，并向前 重放 ，直到再次遇到暂停点。 对于 Functional API，重放从 入口点 的开头开始。LangGraph 会从检查点器还原已完成的 任务 和 子图 结果，而不是重新计算它们。这样可以在多次暂停之间保持步骤顺序，包括长时间运行或非确定性的 任务 输出。 对于 人在回路 ，将非确定性工作（例如随机值）和副作用（例如文件写入或 API 调用）放入 任务 中。 不同的运行可能产生不同的结果。恢复 特定 线程时，应重放相同的已持久化 任务 和 子图 "},{"h":"幂等性#","id":"幂等性","t":"幂等性意味着多次运行同一操作与运行一次的效果相同。将 API 调用和其他写入操作放在 任务 内部，并设计这些任务，使其在再次运行时是安全的。 恢复时，LangGraph 会还原已完成的 任务 结果。已开始但未完成的 任务 可能会再次运行，因此请使用幂等键，或在写入前检查现有结果。"},{"h":"暂停以进行人工审核#","id":"暂停以进行人工审核","t":"此工作流会写一篇文章，并 中断 以进行人工审核： python 复制 使用诸如 \"cat\" 的主题进行调用。该运行会写出文章，然后在 interrupt 处暂停。暂停可以无限期持续。恢复从入口点的开头开始。 write_essay 任务的结果会被还原，而不是重新计算。 有关流式输出、恢复和工具调用审核，参见 使用 Functional API 添加人在回路 。"},{"h":"常见陷阱#","id":"常见陷阱","t":""},{"h":"处理副作用#","id":"处理副作用","t":"将副作用（写入文件、发送电子邮件）放在任务中，以便恢复时不会再次运行它们。 错误 正确 文件写入在入口点中运行，因此恢复时会第二次执行它。 python 复制 副作用位于任务中，因此恢复会还原已检查点的结果。 python 复制"},{"h":"非确定性控制流#","id":"非确定性控制流","t":"将时间和随机性封装在任务中，以便恢复时返回相同的值。 在任务中：获取随机数 (5) → 中断 → 恢复 →（再次返回 5）→ ... 不在任务中：获取随机数 (5) → 中断 → 恢复 → 获取新的随机数 (7) → ... 在多次调用 \u00000\u0000 时，LangGraph 会 按索引 将恢复值与每个中断匹配。如果恢复改变了中断的顺序，恢复值可能会附加到错误的中断上。参见 确定性 。 错误 正确 在入口点中读取时钟可能会改变恢复时运行的分支。 python 复制 在任务内部读取时钟，以便恢复时还原相同的时间戳和分支。 p"},{"h":"了解更多#","id":"了解更多","t":"以 Functional API 的方式思考 Functional API 构建检查清单 组合 Functional API 工作流 配置 Functional API 任务 使用 Functional API 进行流式输出 为 Functional API 添加人在回路 为 Functional API 添加记忆 Graph API 概览 在 Graph API 与 Functional API 之间做选择 通过 MCP 将 这些文档 连接到你所选的智能体，以获取实时回答。 在 GitHub 上 编辑此页 ，或 "}]},{"slug":"functional-api-workflows","url":"functional-api-workflows.html","title":"组合 Functional API 工作流","group":"使用 Functional API 构建","sections":[{"h":"创建一个简单的工作流#","id":"创建一个简单的工作流","t":"这是来自 在 Graph API 与 Functional API 之间选择 的奇偶流程。此版本添加了 checkpointer，因此运行拥有一个线程。 python 复制 入口点接受一个位置参数作为输入。如需传入多个字段，请使用字典： python 复制"},{"h":"并行运行任务#","id":"并行运行任务","t":"任务在你调用它时立即启动，并返回一个 future。先收集这些 future，然后用 .result() 等待，这样工作就能重叠进行。 这种模式对 I/O 密集型工作很有帮助，例如 LLM API 调用。 python 复制 扩展示例：并行的 LLM 调用 每个任务生成一段关于不同主题的段落。结果会合并成一个字符串。 python 复制"},{"h":"调用图#","id":"调用图","t":"Functional API 与 Graph API 共享同一个运行时。编译后的图也是可调用对象：你可以像调用任何其他函数一样，从入口点中调用它。 除非你把 config 传给 invoke ，否则嵌套图不会共享外层线程。请在入口点上请求注入的 config ，并将其转发下去。 python 复制"},{"h":"调用其他入口点#","id":"调用其他入口点","t":"你可以在入口点或任务内部调用其他入口点。 当子入口点定义时没有 checkpointer，从拥有 checkpointer 的父入口点调用它时，会使用父级的 checkpointer。单独调用该子入口点则不会持久化，除非你传入 checkpointer。 python 复制 扩展示例：调用另一个入口点 python 复制"},{"h":"另请参阅#","id":"另请参阅","t":"Functional API 概览 Functional API 构建清单 工作流与智能体 使用 Functional API 将 LangGraph 的功能添加到其他框架 将这些文档连接 到你所选的智能体，通过 MCP 获得实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"functional-api-tasks","url":"functional-api-tasks.html","title":"配置 Functional API 任务","group":"使用 Functional API 构建","sections":[{"h":"添加重试策略#","id":"添加重试策略","t":"在 @task 上传入 retry_policy 。默认的 RetryPolicy 会对选定的网络错误和 HTTP 5xx 错误进行重试，但不会重试 ValueError 。本示例对 ValueError 进行重试。 python 复制"},{"h":"设置超时#","id":"设置超时","t":"限制单次异步尝试可以运行多长时间。如果重试策略会重试该超时错误，则计时器在下一次尝试时重置。 在 @task 或 @entrypoint 上以秒为单位或使用 datetime.timedelta 传入 timeout 。超时仅适用于异步任务和入口点。在同步函数上设置 timeout 会在声明时引发错误。 第一次尝试的休眠时间超过了超时限制，并引发 \u00000\u0000 ，它是 TimeoutError 的子类。重试策略会重试该错误。第二次尝试立即返回。 python 复制"},{"h":"缓存任务#","id":"缓存任务","t":"按输入缓存任务结果。在 入口点 上传入缓存，在任务上传入策略。 ttl 以秒为单位。第二次调用命中缓存，因此本次运行大约耗时 1 秒，而不是 2 秒。 python 复制"},{"h":"出错后恢复#","id":"出错后恢复","t":"需要 检查点保存器 ，以便已完成的任务结果能在运行失败后保留下来。 恢复会从入口点的开头开始。LangGraph 会从检查点恢复已完成 slow_task 的结果，因此其函数体不会再次运行。失败的 get_info 任务会再次运行并返回 \"OK\" 。下面的执行日志区分了入口点的重新进入与任务的重新执行。 用 None 恢复同一个 thread_id 。 python 复制 再次传入原始输入会启动一次新的调用，而不是恢复失败的那次调用。请参阅 选择如何继续线程 。 恢复会还原已完成任务的结果，但不会选择性地重新运行某"},{"h":"另请参阅#","id":"另请参阅","t":"Functional API 概览 Functional API 构建清单 容错 使用 Functional API 进行流式输出 使用 Functional API 添加记忆 通过 MCP 将 这些文档 连接到你所选的智能体，以获取实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"functional-api-streaming","url":"functional-api-streaming.html","title":"使用 Functional API 进行流式输出","group":"使用 Functional API 构建","sections":[{"h":"发出自定义数据#","id":"发出自定义数据","t":"Functional API 使用与 Graph API 相同的流。用 writer 发出数据，然后消费 custom 数据块。关于流模式，请参阅 流式输出 。 python 复制 查看示例 trace 打开此示例对应的公开 LangSmith 运行记录。 从 langgraph.config 导入 \u00001\u0000 。 在入口点内部调用它，以获得一个 writer。 在计算前后发出自定义数据。 调用 stream(..., stream_mode=\"custom\") 并迭代数据块。 ⚠ 警告 Python \\< 3.11 "},{"h":"流式输出 values#","id":"流式输出-values","t":"复用 发出自定义数据 中的 main 入口点。迭代 stream.values 以获取状态快照。关于消息及其他投影，请参阅 事件流式输出 。 python 复制"},{"h":"另请参阅#","id":"另请参阅","t":"Functional API 概览 Functional API 构建清单 事件流式输出 流式输出 使用 Functional API 添加人在回路 将这些文档连接 到你所选的智能体，通过 MCP 获取实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"functional-api-human-in-the-loop","url":"functional-api-human-in-the-loop.html","title":"使用 Functional API 添加人在回路","group":"使用 Functional API 构建","sections":[{"h":"暂停以获取反馈#","id":"暂停以获取反馈","t":"创建三个 任务 ： 追加 \"bar\" 。 暂停以获取人工输入。恢复时追加该输入。 追加 \"qux\" 。 在入口点中将它们组合起来。 step_1 完成后， interrupt 在 human_feedback 内部运行。这些结果会被持久化，因此恢复后 step_1 不会再次运行。 使用 thread_id 标识本次运行。驱动流式输出直到其暂停，打印中断载荷，然后恢复。 python 复制 Command 的 resume 值是 human_feedback 期望的数据。恢复后，本次运行会继续执行 step_3 ，并"},{"h":"审查工具调用#","id":"审查工具调用","t":"要在工具调用执行前对其审查，可从一个辅助函数中调用 interrupt 。执行会暂停，直到你使用 Command 恢复。 对于给定的工具调用，可选择以下之一： 接受该工具调用 修改该工具调用并继续 生成自定义工具消息（例如，指示模型重新格式化其工具调用） python 复制 将该辅助函数接入入口点。被接受或被修改的调用会经由 call_tool 执行。反馈会变成一个 \u00001\u0000 并跳过执行。先前任务的结果（此处为第一次模型调用）在中断后仍保留在线程中。 下面的 call_model 和 call_tool 是占位实现。"},{"h":"另请参阅#","id":"另请参阅","t":"Functional API 概览 Functional API 构建清单 中断 使用 Functional API 添加记忆 使用 Functional API 进行流式输出 通过 MCP 将 这些文档 连接到你所选的智能体，以获取实时答案。 在 GitHub 上 编辑此页面 ，或 提交 issue 。"}]},{"slug":"functional-api-memory","url":"functional-api-memory.html","title":"使用 Functional API 添加记忆","group":"使用 Functional API 构建","sections":[{"h":"在线程上保存状态#","id":"在线程上保存状态","t":"在创建入口点时传入检查点。使用 thread_id 标识每次运行。 添加一个仅限关键字的 previous 参数。LangGraph 会将其设置为该线程上最后保存的值。首次运行时它为 None 。 python 复制"},{"h":"返回不同的已保存值#","id":"返回不同的已保存值","t":"当调用方应收到一个值、而下一次运行应读取另一个值时，请使用 \u00000\u0000 。 value 会返回给调用方。 save 则是下一次 previous 读取时看到的内容。 例如，返回状态或摘要，并保存完整的内部状态。 python 复制"},{"h":"检查检查点#","id":"检查检查点","t":"查看或删除 返回不同的已保存值 中 accumulate 工作流的检查点。 values 是已保存的检查点（ save ），而不是返回给调用方的值。"},{"h":"查看线程状态#","id":"查看线程状态","t":"python 复制 text 复制"},{"h":"查看线程历史#","id":"查看线程历史","t":"python 复制 text 复制"},{"h":"删除某个线程的检查点#","id":"删除某个线程的检查点","t":"python 复制"},{"h":"使用检查点构建聊天机器人#","id":"使用检查点构建聊天机器人","t":"让对话保持在同一个线程上。将模型消息返回给调用方，并使用 entrypoint.final 保存完整列表以供下一轮使用。 Google OpenAI Anthropic OpenRouter Fireworks Baseten Ollama python 复制 python 复制 python 复制 python 复制 python 复制 python 复制 python 复制"},{"h":"跨线程保存事实#","id":"跨线程保存事实","t":"长期记忆 存放在 存储 中，而不是检查点中。在一个 thread_id 上保存事实，在另一个 thread_id 上读取它。 在装饰入口点时传入 \u00000\u0000 。通过 runtime.store 读取它。 python 复制"},{"h":"另请参阅#","id":"另请参阅","t":"Functional API 概览 Functional API 构建清单 记忆 持久化 存储 使用 Functional API 添加人在回路 将这些文档 通过 MCP 连接到你所选择的智能体，以获得实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"local-server","url":"local-server.html","title":"运行本地服务器","group":"部署","sections":[{"h":"前置条件#","id":"前置条件","t":"开始之前，请确保已准备好以下内容： 一个 LangSmith 的 API 密钥——注册免费"},{"h":"1. 安装 LangGraph CLI#","id":"1.-安装-langgraph-cli","t":"pip uv bash 复制 bash 复制"},{"h":"2. 创建 LangGraph 智能体#","id":"2.-创建-langgraph-智能体","t":"使用 \u00000\u0000 模板 创建智能体代码。该模板展示了一个单节点图，你可以用自己的逻辑对其进行扩展。 shell 复制 💡 提示 其他模板 如果在使用 langgraph new 时未指定模板，你将看到一个交互式菜单，可从中选择可用的模板。"},{"h":"3. 安装依赖#","id":"3.-安装依赖","t":"在新建 LangGraph 应用的根目录下，以 edit 模式安装依赖，这样服务器就会使用你的本地改动： pip uv bash 复制 bash 复制"},{"h":"4. 创建 .env 文件#","id":"4.-创建-.env-文件","t":"ℹ 注意 在 基于智能体的工作区 中，发送追踪前需先 创建智能体 。使用 智能体寻址 选择其标识符和环境。如果某个集成需要 project_name ，请使用所选环境的 \u00001\u0000 作为兼容值。 在新建 LangGraph 应用的根目录中会有一个 .env.example 文件。请在根目录下创建 .env 文件，并把 .env.example 的内容复制进去，填入所需的 API 密钥： bash 复制"},{"h":"5. 启动 Agent Server#","id":"5.-启动-agent-server","t":"在本地启动 LangGraph API 服务器： shell 复制 示例输出： text 复制 langgraph dev 命令以内存模式启动 Agent Server。该模式适用于开发和测试。生产环境请部署可访问持久化存储后端的 Agent Server。更多信息请参见 平台设置概览 。"},{"h":"6. 在 Studio 中测试你的智能体#","id":"6.-在-studio-中测试你的智能体","t":"Studio 是一个专用 UI，你可以将它连接到 LangGraph API 服务器，从而在本地可视化、交互和调试你的智能体。访问 langgraph dev 命令输出中提供的 URL，即可在 Studio 中测试你的图： text 复制 如果 Agent Server 运行在自定义主机/端口上，请更新 URL 中的 baseUrl 查询参数。例如，若服务器运行在 http://myhost:3000 上： text 复制 Safari 兼容性 由于 Safari 在连接 localhost 服务器时存在限制，请在"},{"h":"7. 测试 API#","id":"7.-测试-api","t":"Python SDK（异步） Python SDK（同步） REST API 安装 LangGraph Python SDK： shell 复制 向助手发送消息（无线程运行）： python 复制 安装 LangGraph Python SDK： shell 复制 向助手发送消息（无线程运行）： python 复制 bash 复制"},{"h":"下一步#","id":"下一步","t":"现在你已在本地运行起一个 LangGraph 应用，接下来可以继续探索部署和高级特性： 部署快速开始 ：使用 LangSmith 部署你的 LangGraph 应用。 LangSmith ：了解 LangSmith 的基础概念。 SDK 参考 ：浏览 SDK API 参考文档。 通过 MCP 将这些文档 连接到你选择的智能体，以获取实时答案。 在 GitHub 上 编辑此页面 或 提交 issue 。"}]},{"slug":"application-structure","url":"application-structure.html","title":"应用结构","group":"部署","sections":[{"h":"核心概念#","id":"核心概念","t":"使用 LangSmith 进行部署时，应提供以下信息： 一个 LangGraph 配置文件 （ langgraph.json ），用于指定应用要使用的依赖、图和环境变量。 实现应用逻辑的 图 。 一个声明运行应用所需 依赖 的文件。 应用运行所需的 环境变量 。"},{"h":"文件结构#","id":"文件结构","t":"以下是应用目录结构的示例： Python（requirements.txt） Python（pyproject.toml） plaintext 复制 plaintext 复制 ℹ 注意 LangGraph 应用的目录结构会因所用的编程语言和包管理器而有所不同。"},{"h":"配置文件#","id":"配置文件","t":"langgraph.json 文件是一个 JSON 文件，用于指定部署 LangGraph 应用所需的依赖、图、环境变量和其他设置。 有关 JSON 文件中所有受支持的键的详细信息，请参阅 LangGraph 配置文件参考 。 💡 提示 LangGraph CLI 默认使用当前目录下的配置文件 langgraph.json 。"},{"h":"示例#","id":"示例","t":"依赖中包含一个本地自定义包以及 langchain_openai 包。 将从文件 ./your_package/your_file.py 中加载单个图，对应的变量为 variable 。 环境变量从 .env 文件加载。 json 复制"},{"h":"依赖#","id":"依赖","t":"一个 LangGraph 应用可能依赖其他 Python 包。 要让依赖被正确安装，通常需要指定以下信息： 目录中一个声明依赖的文件（例如 requirements.txt 、 pyproject.toml 或 package.json ）。 LangGraph 配置文件 中的 dependencies 键，用于指定运行该 LangGraph 应用所需的依赖。 任何额外的二进制文件或系统库，都可以通过 LangGraph 配置文件 中的 dockerfile_lines 键来指定。"},{"h":"图#","id":"图","t":"使用 LangGraph 配置文件 中的 graphs 键，指定部署后的 LangGraph 应用中可用的图。 你可以在配置文件中指定一个或多个图。每个图都由一个名称（应当唯一）和一个路径来标识，该路径指向：（1）已编译的图，或（2）一个用于构建图的函数。"},{"h":"环境变量#","id":"环境变量","t":"如果你在本地处理已部署的 LangGraph 应用，可以在 LangGraph 配置文件 的 env 键中配置环境变量。 对于生产环境部署，通常需要在部署环境中配置环境变量。 将这些文档 通过 MCP 连接到你所选的智能体，以获取实时回答。 在 GitHub 上编辑此页面 或 提交问题 。"}]},{"slug":"test","url":"test.html","title":"测试","group":"部署","sections":[{"h":"前置条件#","id":"前置条件","t":"首先，确保你已经安装了 \u00000\u0000 ： bash 复制"},{"h":"快速开始#","id":"快速开始","t":"由于许多 LangGraph 智能体依赖状态，一个有用的模式是在每次使用图进行测试之前先创建图，然后在测试中使用新的检查点实例对其编译。 下面的示例展示了它在一条简单的线性图上的工作方式，该图依次经过 node1 和 node2 。每个节点都会更新单个状态键 my_key ： python 复制"},{"h":"测试单个节点和边#","id":"测试单个节点和边","t":"编译后的 LangGraph 智能体会以 graph.nodes 的形式暴露对每个单独节点的引用。你可以利用这一点来测试智能体中的单个节点。请注意，这样做会绕过编译图时传入的任何检查点： python 复制"},{"h":"部分执行#","id":"部分执行","t":"对于由较大图构成的智能体，你可能希望测试智能体内部的部分执行路径，而不是端到端地测试整个流程。在某些情况下， 将这些部分重构为子图 在语义上可能更合理，因为子图可以像普通图一样被单独调用。 不过，如果你不希望改动智能体图的整体结构，可以使用 LangGraph 的持久化机制来模拟一种状态：智能体恰好暂停在目标部分的起点之前，并将再次暂停在目标部分的终点处。步骤如下： 使用检查点编译你的智能体（内存检查点 \u00000\u0000 就足以用于测试）。 调用智能体的 \u00000\u0000 方法，并将 \u00001\u0000 参数设置为你想开始测试的那个节点*之前*的"}]},{"slug":"backward-compatibility","url":"backward-compatibility.html","title":"向后兼容","group":"部署","sections":[{"h":"技术兼容性#","id":"技术兼容性","t":"技术兼容性相当于微服务中的 API 破坏性变更。这里的“API”指的是你的图代码与 检查点保存器 为已有线程已持久化的数据之间的约定。当线程恢复时，LangGraph 会反序列化已保存的状态，按名称将其分派给某个节点，并期望该节点返回符合状态模式的值。 常见的技术性破坏： 重命名或删除节点 ，而线程正暂停在该节点处或即将进入该节点，例如停在某个 \u00000\u0000 处，或经由一条已被检查点记录、仍路由到旧名称的条件边。恢复时，LangGraph 无法按其保存的名称找到该节点，运行就会失败。恢复运行的起点是执行停止所在节点的开头"},{"h":"推荐模式#","id":"推荐模式","t":"把新增的状态字段声明为 NotRequired （或 Optional[...] = None ），这样旧的检查点仍能通过校验： python 复制 把删除当作弃用处理。即使没有节点读取该字段，也要在状态上至少保留一个排空周期，以便已有的检查点继续加载。 通过*先加后删*来完成重命名。在旧字段或旧节点旁边新增新的字段或节点，在弃用窗口内双写或同时路由到两者，待确认没有任何在途线程依赖旧字段或旧节点后，再将其删除。 让节点函数能够容忍未知的键。 TypedDict 在运行时忽略多余的键，因此旧代码版本遗留的状态不会报"},{"h":"检测在途线程#","id":"检测在途线程","t":"在你删除节点、重命名状态键，或进行其他旧线程无法容忍的变更之前，你会想知道当前是否有线程停留在你即将废弃的那个代码版本上。LangGraph 本身并不维护线程状态的搜索索引，因此答案取决于你的图运行在哪里。 如果你部署到 LangSmith 。 使用 Agent Server 的线程搜索按状态过滤。 status 字段接受 idle 、 busy 、 interrupted 和 error ，因此你可以批量查询 interrupted 或 busy 的线程，还可以选择用元数据过滤进一步收窄范围。参见 按线程状态过滤"},{"h":"业务兼容性#","id":"业务兼容性","t":"有时某项变更在技术上是有效的（每个已有检查点仍能加载，每个节点仍能解析），但新图的*含义*与旧图不同。新行为对新线程来说是正确的，而你并不希望把它追溯应用到在旧逻辑下启动的线程。 例如，假设你的图执行 intake → triage → respond ，而你决定在 triage 和 respond 之间插入一个新的 policy_check 步骤： 已经通过 triage 的线程应当直接继续到 respond （旧流程）。 新线程应当执行完整的新流程。 推荐的模式是在线程启动时把相关的*行为版本*记录到状态上，然"},{"h":"非确定性#","id":"非确定性","t":"这一类问题仅适用于 Functional API ，以及 Graph API 节点 内部的 任务 或 \u00000\u0000 调用。普通的 Graph API 节点 在恢复时会 从节点函数的开头重新运行 ；应把副作用设计为幂等的，但除非你在该 节点 中使用了 任务 或 \u00001\u0000 ，否则无需保持任务调用顺序。 Functional API 的 入口点 会编译为单个 节点 ，当运行恢复时，该节点会从头重放入口点主体，并利用缓存的 \u00000\u0000 结果跳过已经完成的工作。有两类变更会破坏这一模型： 新增、删除或重新排序 位于恢复点*之前*的 @t"}]},{"slug":"studio","url":"studio.html","title":"LangSmith Studio","group":"部署","sections":[{"h":"前提条件#","id":"前提条件","t":"开始之前，请确保你具备以下条件： 一个 LangSmith 账户 ：在 smith.langchain.com 免费注册或登录。 一个 LangSmith API 密钥 ：请参阅 创建 API 密钥 指南。 如果你不希望数据被 追踪 到 LangSmith，请在智能体的 .env 文件中设置 LANGSMITH_TRACING=false 。禁用追踪后，任何数据都不会离开你的本地服务器。"},{"h":"设置本地 Agent 服务器#","id":"设置本地-agent-服务器","t":""},{"h":"1. 安装 LangGraph CLI#","id":"1.-安装-langgraph-cli","t":"LangGraph CLI 提供了一个本地开发服务器（也称为 Agent Server ），用于将你的智能体连接到 Studio。 shell 复制"},{"h":"2. 准备你的智能体#","id":"2.-准备你的智能体","t":"如果你已经有一个 LangChain 智能体，可以直接使用它。本示例使用一个简单的邮件智能体： python 复制"},{"h":"3. 环境变量#","id":"3.-环境变量","t":"ℹ 注意 在 基于智能体的工作区 中，在发送追踪数据之前先 创建一个智能体 。使用 智能体寻址 来选择其标识符和环境。如果某个集成需要 project_name ，请使用所选环境的 \u00001\u0000 作为兼容值。 Studio 需要 LangSmith API 密钥才能连接你的本地智能体。在项目根目录创建 .env 文件，并添加来自 LangSmith 的 API 密钥。 ⚠ 警告 确保你的 .env 文件未被提交到版本控制（如 Git）。 bash 复制"},{"h":"4. 创建 LangGraph 配置文件#","id":"4.-创建-langgraph-配置文件","t":"LangGraph CLI 使用配置文件来定位你的智能体并管理依赖。在应用目录中创建 langgraph.json 文件： json 复制 \u00000\u0000 函数会自动返回一个已编译的 LangGraph 图，这正是配置文件中 graphs 键所期望的内容。 ℹ 注意 有关配置文件 JSON 对象中每个键的详细说明，请参阅 LangGraph 配置文件参考 。 此时，项目结构如下： bash 复制"},{"h":"5. 安装依赖#","id":"5.-安装依赖","t":"从根目录安装项目依赖： pip uv shell 复制 shell 复制"},{"h":"6. 在 Studio 中查看你的智能体#","id":"6.-在-studio-中查看你的智能体","t":"启动开发服务器，将你的智能体连接到 Studio： shell 复制 ⚠ 警告 Safari 会阻止 localhost 连接到 Studio。要解决此问题，请使用 --tunnel 运行上述命令，通过安全隧道访问 Studio。你需要点击 Studio UI 中的 Connect to a local server ，手动将隧道 URL 添加到允许的来源。具体步骤请参阅 故障排除指南 。 服务器运行后，你的智能体既可以通过 http://127.0.0.1:2024 的 API 访问，也可以通过 https://"},{"h":"视频指南#","id":"视频指南","t":"Studio 通过 MCP 将 这些文档 连接到你所选的智能体，以获取实时答案。 在 GitHub 上编辑此页 或 提交 issue 。"}]},{"slug":"ui","url":"ui.html","title":"Agent Chat UI","group":"部署","sections":[{"h":"快速开始#","id":"快速开始","t":"最快的上手方式是使用托管版本： 访问 Agent Chat UI 连接你的智能体 ：输入你的部署 URL 或本地服务器地址 开始聊天 ：UI 会自动检测并渲染工具调用与中断"},{"h":"本地开发#","id":"本地开发","t":"如需自定义或本地开发，你可以在本地运行 Agent Chat UI： Use Clone bash 复制 bash 复制"},{"h":"连接到你的智能体#","id":"连接到你的智能体","t":"Agent Chat UI 既可连接 本地 智能体，也可连接 已部署的智能体 。 启动 Agent Chat UI 后，你需要对其进行配置以连接到你的智能体： Graph ID ：输入你的图名称（可在 langgraph.json 文件的 graphs 下找到） Deployment URL ：你的 Agent 服务器端点（例如本地开发时为 http://localhost:2024 ，或你已部署智能体的 URL） LangSmith API key (optional) ：添加你的 LangSmith API k"}]},{"slug":"deploy","url":"deploy.html","title":"部署","group":"部署","sections":[{"h":"LangSmith Cloud#","id":"langsmith-cloud","t":"本节介绍如何从 GitHub 仓库将你的智能体部署到 LangSmith Cloud。LangSmith 负责基础设施、扩缩容以及运维相关事宜。"},{"h":"前提条件#","id":"前提条件","t":"开始之前，请确保你已具备以下条件： 一个 GitHub 账号 一个 LangSmith 账号 （可免费注册）"},{"h":"部署你的智能体#","id":"部署你的智能体","t":"1. 在 GitHub 上创建仓库 你的应用代码必须位于 GitHub 仓库中，才能部署到 LangSmith。公有仓库和私有仓库均受支持。对于本快速入门，请先按照 本地服务器设置指南 确保你的应用兼容 LangGraph。然后，将你的代码推送到该仓库。 2. 部署到 LangSmith 1. 前往 LangSmith 部署页面 登录 LangSmith 。在左侧边栏中，选择 Deployments 。 2. 创建新部署 点击 + New Deployment 按钮。将打开一个面板，你可以在其中填写必填字段。 3."}]},{"slug":"observability","url":"observability.html","title":"LangSmith 可观测性","group":"部署","sections":[{"h":"前置条件#","id":"前置条件","t":"在开始之前，请确保你已具备以下条件： 一个 LangSmith 账户 ：在 smith.langchain.com 免费注册或登录。 一个 LangSmith API 密钥 ：请遵循 创建 API 密钥 指南。"},{"h":"启用追踪#","id":"启用追踪","t":"ℹ 注意 在 基于智能体的工作区 中，发送追踪之前请先 创建一个智能体 。使用 智能体寻址 来选择其标识符和环境。如果某个集成需要 project_name ，请使用所选环境的 \u00001\u0000 作为兼容值。 要为你的智能体启用追踪，请设置以下环境变量： bash 复制 追踪将显示在设置期间配置的目标位置。 更多信息，请参阅 使用 LangGraph 追踪 。"},{"h":"选择性追踪#","id":"选择性追踪","t":"你可以选择使用 LangSmith 的 tracing_context 上下文管理器来追踪智能体的特定调用或部分： python 复制"},{"h":"选择智能体与环境#","id":"选择智能体与环境","t":"使用 LANGSMITH_AGENT_ID 和 LANGSMITH_AGENT_ENVIRONMENT 来选择已注册的智能体和环境。如需按请求路由，请在代码中传入智能体地址。请参阅 将追踪记录到智能体 。 基于项目的工作区与自托管 LangSmith 设置 LANGSMITH_PROJECT 为追踪项目名称，而不是设置智能体相关变量。对于在基于智能体的工作区中需要 project_name 的集成，请使用环境的 \u00002\u0000 作为兼容值。"},{"h":"为追踪添加元数据#","id":"为追踪添加元数据","t":"你可以使用自定义元数据和标签来注解你的追踪： python 复制 tracing_context 同样接受标签和元数据，以实现更精细的控制： python 复制 这些自定义元数据和标签将附加到 LangSmith 中的追踪上。 💡 提示 如需进一步了解如何使用追踪来调试、评估和监控你的智能体，请参阅 LangSmith 文档 。"},{"h":"使用匿名化器防止在追踪中记录敏感数据#","id":"使用匿名化器防止在追踪中记录敏感数据","t":"你可能希望遮蔽敏感数据，以免其被记录到 LangSmith。你可以创建 匿名化器 ，并通过配置将它们应用到 你的图。此示例将从发送到 LangSmith 的追踪中隐去任何匹配社会安全号码格式 XXX-XX-XXXX 的内容。 python 复制 通过 MCP 将 这些文档 连接到你所选的智能体，以获取实时答案。 在 GitHub 上 编辑此页面 或 提交问题 。"}]},{"slug":"frontend-overview","url":"frontend-overview.html","title":"概览","group":"前端","sections":[{"h":"架构#","id":"架构","t":"LangGraph 图由通过边连接的具名节点组成。每个节点执行一个步骤（分类、检索、分析、综合），并将输出写入特定的状态键。在前端，SDK 的流句柄提供对节点输出、流式 token 和已发现子图的响应式访问，因此你可以将每个节点映射到一张 UI 卡片。 mermaid 复制 python 复制 在前端， \u00000\u0000 暴露了用于图节点发现的 stream.subgraphs ，以及诸如 useMessages(stream, node) 之类的选择器辅助函数，用于获取节点范围内的流式内容。当你需要诸如最终的 synthe"},{"h":"与聊天流的区别#","id":"与聊天流的区别","t":"自定义图通常支撑着产品工作流：检索流水线、审批流、数据流水线、数据增强、代码审查、规划以及多步分析。前端 SDK 让你可以使用图原生信号来渲染这些工作流： 运行时概念 前端用户体验 具名节点 每个图节点对应一张卡片、一个时间线步骤或一个状态徽章。 状态键 为分类、来源、分析和最终综合等类型化输出提供专门的 UI 区域。 流式元数据 将部分消息路由到产生它的节点。 检查点 检查或从先前的图状态恢复，用于调试和审计。 中断 暂停某个节点以等待人工输入、审批或修正，然后再继续。 子图 仅在用户需要更多细节时才展示嵌套执行"},{"h":"模式#","id":"模式","t":"图执行 可视化多步图流水线，并呈现每个节点的状态和流式内容。 自定义流通道 将自定义的服务端数据流式输出到前端，并使用 useExtension 和 useChannel 读取。"},{"h":"相关模式#","id":"相关模式","t":"LangChain 前端模式 ——Markdown 消息、工具调用、人在回路、可恢复流和时间旅行——适用于任何 LangGraph 图。无论你使用 createAgent 、 createDeepAgent 还是自定义 StateGraph ，流 API 都提供相同的核心数据模型。 将这些文档连接 到你所选的智能体，通过 MCP 获取实时答案。 在 GitHub 上编辑此页面 或 提交 issue 。"}]},{"slug":"frontend-graph-execution","url":"frontend-graph-execution.html","title":"图执行","group":"前端","sections":[{"h":"图节点如何映射到 UI 卡片#","id":"图节点如何映射到-ui-卡片","t":"一个 LangGraph 图定义了一系列节点，每个节点负责一项具体任务。例如，一条研究流水线可能包含： 分类 ：对用户的查询进行分类 研究 ：收集相关信息 分析 ：从研究结果中得出结论 综合 ：产出最终打磨过的回复 每个节点都会把输出写入图状态中某个特定的键。在前端，你无需硬编码这种映射，因为 \u00000\u0000 会在运行时通过 stream.subgraphs 发现每个节点，并为每个观测到的步骤暴露一个 \u00002\u0000 ： ts 复制 在进度条和卡片标题中，用 node.nodeName 作为标签。把每个快照传给 useMessag"},{"h":"配置 useStream#","id":"配置-usestream","t":"像往常一样接入 \u00000\u0000 。你会用到的主要属性是 messages （用于对话）和 subgraphs （用于当前运行中发现的图节点）。把每个已发现的子图快照传给选择器，即可读取该节点作用域内的消息。 ℹ 注意 代码示例使用 useStream<typeof myAgent> 以获得类型安全的流状态。类型推断请参阅 Python 或 JavaScript 后端。 React Vue Svelte Angular tsx 复制 vue 复制 svelte 复制 ts 复制"},{"h":"将流式 token 路由到节点#","id":"将流式-token-路由到节点","t":"在图进行流式输出的过程中，每个已发现的子图快照都会标明它所属的节点。把该快照传给选择器 Hook 或组合式函数，即可读取该节点作用域内的消息： tsx 复制 首个挂载的选择器会为该节点命名空间开启一个作用域订阅。当节点卡片卸载时，订阅会自动释放。"},{"h":"判断节点状态#","id":"判断节点状态","t":"每个已发现的节点都携带当前状态。直接使用 node.status 即可；发现快照会报告 \"pending\" 、 \"running\" 、 \"complete\" 或 \"error\" ： ts 复制"},{"h":"构建流水线进度条#","id":"构建流水线进度条","t":"顶部的一条水平进度条能让用户纵览整条流水线。每个步骤都是一个带标签的分段，随着节点完成而填充： tsx 复制"},{"h":"构建可折叠的 NodeCard 组件#","id":"构建可折叠的-nodecard-组件","t":"每个节点都有自己的卡片，展示状态徽标、内容（流式输出或最终结果），以及用于长输出的可折叠主体： tsx 复制"},{"h":"流式内容与已完成内容#","id":"流式内容与已完成内容","t":"节点卡片会读取作用域内的消息，用于流式内容和最终内容。这样就避免了一个假设：图节点名称与它写入的状态键一致（例如，在 playground 图中， do_research 写入的是 research ）： 来源 使用场景 useMessages(stream, node) 渲染节点作用域内的流式消息和最终消息 stream.values 使用真实的状态键读取整图状态，例如最终的 synthesis 字段 模式是这样的：在节点卡片中展示最近一条作用域内的 AI 消息，只有在确实需要某个图状态字段时才使用 stream"},{"h":"整合起来#","id":"整合起来","t":"下面是完整的卡片列表，它结合了路由、状态检测和卡片渲染： tsx 复制"},{"h":"使用场景#","id":"使用场景","t":"图执行卡片非常适合任何重视可见性的多步骤流水线： 研究流水线 ：分类 → 收集来源 → 分析 → 综合成报告 内容生成 ：列大纲 → 起草 → 事实核查 → 编辑 → 发布 数据处理 ：摄取 → 校验 → 转换 → 聚合 → 导出 代码生成 ：理解需求 → 规划架构 → 编写代码 → 评审 → 测试 决策工作流 ：收集上下文 → 评估选项 → 为备选方案打分 → 给出建议"},{"h":"处理动态流水线#","id":"处理动态流水线","t":"并非所有图都拥有固定的节点集合。有些流水线会根据输入添加或跳过节点。发现映射中只包含当前线程观测到的节点： ts 复制 这样可以确保 UI 只展示与当前执行相关的节点卡片，避免出现空的占位卡片。 ℹ 注意 如果你的图存在条件分支（例如，对于简单的事实类查询跳过 \"Research\"），被跳过的节点不会出现在 stream.subgraphs 中。你的流水线进度条可以只渲染已发现的节点，或者将没有匹配快照的预期节点置灰。"},{"h":"最佳实践#","id":"最佳实践","t":"从流中发现节点 。从 stream.subgraphs 渲染卡片，而不是硬编码预期节点；条件分支或跳过的步骤在执行前不会出现。 将状态键视为 UI 契约 。决定哪些图输出足够稳定、可供前端渲染，并在图定义旁边记录这些键。 为节点卡片使用作用域消息 。它们在节点流式输出期间和完成之后都能工作，且不会让 UI 卡片与状态键名称耦合。 自动折叠已完成的节点 。在长流水线中，自动折叠已完成的卡片，让用户可以专注于当前活跃的步骤。 展示预估耗时 。如果你有每个节点耗时的历史数据，展示时间估计以设定用户预期。 添加全局进度指示"}]},{"slug":"frontend-custom-stream-channels","url":"frontend-custom-stream-channels.html","title":"自定义流式输出通道","group":"前端","sections":[{"h":"自定义通道的工作方式#","id":"自定义通道的工作方式","t":"自定义通道有两端。在服务器端， \u00000\u0000 打开一个具名的 \u00001\u0000 并向其中推送负载。在客户端，选择器订阅匹配的 custom:<name> 通道，并将负载以响应式状态的形式暴露出来。 转换器的 process 方法会针对每个协议事件运行。它可以就地修改事件（这里的做法是把 messages 、 tools 和 values 数据中的 PII 清除掉），并在有任何需要上报的内容时推送旁路通道更新。 客户端选择器（ useExtension 、 useChannel ）随 v1 前端 SDK 包一起提供（ @langch"},{"h":"设置 useStream#","id":"设置-usestream","t":"按常规方式接入 \u00000\u0000 。自定义通道选择器接受这里返回的同一个 stream 句柄。 ℹ 注意 代码示例使用 useStream<typeof myAgent> 来获得类型安全的流状态。关于类型推断，请参见 Python 或 JavaScript 后端。 React Vue Svelte Angular tsx 复制 vue 复制 svelte 复制 ts 复制"},{"h":"使用 useExtension 读取最新负载#","id":"使用-useextension-读取最新负载","t":"useExtension 订阅一个 custom:<name> 通道，并返回转换器最近一次推送的负载，且已解包并附带类型。当 UI 只需要当前值时，例如实时计数器、进度百分比或状态徽章，它是更顺手的选型。 传入裸通道名（ \"redaction-stats\" ），而不是带 custom: 前缀的名称： React Vue Svelte Angular tsx 复制 vue 复制 svelte 复制 ts 复制 返回值遵循各框架的响应式模型：React 和 Svelte 中是普通值，Vue 中是 Ref （ lates"},{"h":"使用 useChannel 缓冲原始事件#","id":"使用-usechannel-缓冲原始事件","t":"useChannel 是原始事件的应急出口。它订阅一个或多个通道，返回底层协议事件的有界缓冲区，而不是单个已解包的值。当你需要历史记录而非最新值（例如事件日志或审计记录），或者需要某个没有更高层选择器覆盖的通道时，就用它。 传入完整的通道 id（ \"custom:redaction-stats\" ）： React Vue Svelte Angular tsx 复制 vue 复制 svelte 复制 ts 复制 每个条目都是一个原始协议事件，因此负载位于 event.params.data 下。你需要自行解包： ts"},{"h":"在 useExtension 和 useChannel 之间选择#","id":"在-useextension-和-usechannel-之间选择","t":"两者读取的是同一个自定义通道，但返回的内容不同： useExtension useChannel 返回 最新负载（ T | undefined ） 有界缓冲区的原始事件（ Event[] ） 形态 已解包、带类型的负载 原始协议事件；需自行解包 event.params.data 订阅方式 通道名称（ \"redaction-stats\" ） 完整通道 id（ [\"custom:redaction-stats\"] ） 适用场景 你需要当前值 你需要历史记录、日志或多个通道 选项 — bufferSize 、 repl"},{"h":"使用场景#","id":"使用场景","t":"自定义通道适用于任何无法清晰映射到消息、工具调用或图状态的服务器端信号： 合规与脱敏统计 ：被清洗的 PII、被拦截的内容或策略命中的计数，如上述示例所示。 进度报告 ：长时间运行的工具发出的完成百分比或步骤标签。 实时指标 ：运行期间累积的 token 用量、延迟或成本。 来源与引用 ：在智能体为回答提供依据时，将检索到的文档推送到侧边面板。 领域事件 ：你的后端希望在不改动消息记录的情况下呈现的任何结构化更新。"},{"h":"相关内容#","id":"相关内容","t":"概览 —— LangGraph 前端流式输出 API 与架构。 图执行 —— 用于多节点管道的命名空间作用域选择器。 Connect these docs to your agent of choice via MCP for real-time answers. Edit this page on GitHub or file an issue ."}]},{"slug":"pregel","url":"pregel.html","title":"LangGraph 运行时","group":"进阶","sections":[{"h":"概述#","id":"概述","t":"在 LangGraph 中，Pregel 将 actor 和 通道 （channel）组合到单个应用中。 Actor 从通道读取数据，并向通道写入数据。Pregel 遵循 Pregel 算法 / 整体同步并行 （Bulk Synchronous Parallel）模型，将应用的执行组织为多个步骤。 每个步骤包含三个阶段： 规划 ：确定本步骤要执行哪些 actor 。例如，在第一步中选择订阅特殊 input 通道的 actor ；在后续步骤中选择订阅上一步已更新通道的 actor 。 执行 ：并行执行所有选定的 ac"},{"h":"Actor#","id":"actor","t":"Actor 就是一个 PregelNode 。它订阅通道、从通道读取数据，并向通道写入数据。可以把它看作 Pregel 算法中的 actor 。 PregelNodes 实现了 LangChain 的 Runnable 接口。"},{"h":"通道#","id":"通道","t":"通道用于在 actor（ PregelNode ）之间通信。每个通道都有值类型、更新类型和更新函数——更新函数接收一系列更新并修改存储的值。通道可用于将数据从一个链发送到另一个链，也可用于在后续步骤中将数据从链发送给自身。"},{"h":"LastValue#","id":"lastvalue","t":"\u00000\u0000 是默认的通道类型。它存储最后写入的值，并覆盖之前的任何值。它适用于输入值和输出值，或用于将数据从一个步骤传递到下一个步骤。 python 复制"},{"h":"Topic#","id":"topic","t":"\u00000\u0000 是一种可配置的 PubSub 通道，适用于在 actor 之间发送多个值，或跨步骤累积输出。可以将其配置为对值去重，或累积一次运行期间写入的所有值。 python 复制"},{"h":"BinaryOperatorAggregate#","id":"binaryoperatoraggregate","t":"\u00000\u0000 存储一个持久化的值，该值通过将二元运算符应用于当前值和每个新更新来更新。它适用于跨步骤计算累计聚合结果。 python 复制"},{"h":"DeltaChannel#","id":"deltachannel","t":"⚠ 警告 DeltaChannel 需要 langgraph>=1.2 ，目前处于 beta 阶段。其 API 在后续版本中可能发生变化。 \u00000\u0000 在每个步骤只存储增量 delta，而不是完整累积值。这最适用于写入频繁且随时间累积大量值的通道——例如，长时间运行的线程中的对话消息列表。如果不使用 delta 存储，完整列表会在每个检查点中被重新序列化；使用 DeltaChannel 时，只存储每个步骤新写入的消息。 💡 提示 当一个通道既被频繁写入、又随时间不断增大时，可以考虑使用 DeltaChannel 。一个"},{"h":"示例#","id":"示例","t":"虽然大多数用户会通过 StateGraph API 或 \u00000\u0000 装饰器与 Pregel 交互，但也可以直接使用 Pregel。 下面几个不同的示例可以让你对 Pregel API 有一个直观的感受。 单节点 多个节点 Topic BinaryOperatorAggregate 环 python 复制 con 复制 python 复制 con 复制 python 复制 pycon 复制 本示例演示如何使用 \u00000\u0000 通道来实现归并函数。 python 复制 console 复制 本示例演示如何在图中引入环：让一条链写入"},{"h":"高阶 API#","id":"高阶-api","t":"LangGraph 提供两种高阶 API 来创建 Pregel 应用： StateGraph（Graph API） 和 Functional API 。 StateGraph（Graph API） Functional API StateGraph（Graph API） 是一个更高层的抽象，它简化了 Pregel 应用的创建。它允许你定义一个由节点和边构成的图。当你编译该图时，StateGraph API 会自动为你创建 Pregel 应用。 python 复制 编译后的 Pregel 实例会关联一组节点和通道。你"}]}];
